window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0230", [{"word":"immense","ipa_uk":"/ɪˈmens/","ipa_us":"/ɪˈmens/","definition_zh":"巨大的；广阔的；极大的；无限的","definition_en":"extremely large in size, extent or degree, and in older usage unbounded or immeasurable","core_image":"观景台上望出去，湖面铺到视线尽头，远山一层层退向天边，人只剩一个小小剪影","scene":"清晨的观景台上，湖面一直铺到视线尽头，远山一层层退开，人显得很小。From the viewpoint the lake covered an immense plain that no map could fully show.","sceneCN":"这里指空间范围极其广大的（第 1 个义项：巨大的空间规模）；句意为从观景台望去，湖面覆盖着一片任何地图都无法完整呈现的广袤平原。","pos":[{"tag":"adj.","zh":"巨大的；广阔的；极大的；无限的"}],"collocations":[{"phrase":"immense scale","zh":"巨大的规模"},{"phrase":"immense pressure","zh":"巨大的压力"},{"phrase":"immense value","zh":"巨大的价值"},{"phrase":"an immense amount of","zh":"数量极大的"},{"phrase":"immense wealth","zh":"巨额财富"},{"phrase":"immense relief","zh":"极大的宽慰"}],"forms":[{"label":"原级","form":"immense"},{"label":"比较级","form":"more immense"},{"label":"最高级","form":"most immense"},{"label":"名词（巨大）","form":"immensity"},{"label":"副词","form":"immensely"}],"derivatives":[{"word":"immensely","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「极大地；非常」"},{"word":"immensity","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「巨大；浩瀚」"},{"word":"immenseness","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「巨大」，是较常用名词形式的少见变体"}],"senses":[{"no":"01","title":"Extremely large in size","titleCN":"体积或规模极其巨大","definition":"far larger than the ordinary size of things of the same kind","definitionCN":"比同类事物常见的大小要大得多","example":"The stadium was immense, holding more than eighty thousand people.","exampleCN":"那座体育场极其巨大，可容纳八万多人。","why":"The word begins with a negative prefix, so literally it means not measurable, and an object too big to measure is simply huge.","whyCN":"这个词以否定前缀开头，字面上意为「无法测量」，而大到无法测量的东西就是巨大。"},{"no":"02","title":"Vast in extent","titleCN":"范围辽阔","definition":"covering a very wide area, so that its edges are hard to reach or see","definitionCN":"覆盖极广的区域，边界难以到达或看见","example":"An immense forest once covered the whole valley.","exampleCN":"一片辽阔的森林曾覆盖整个山谷。","why":"Size can be measured along a line as well as around a body, and this sense applies the same bigness to land.","whyCN":"大小既可沿一条线量，也可绕一个物体量，这个义项把同一种「大」用在土地上。"},{"no":"03","title":"Extremely great in degree","titleCN":"程度极大","definition":"of a very high degree in effort, difficulty or intensity","definitionCN":"在付出、难度或强度上达到很高的程度","example":"The plan required immense effort from every member of the team.","exampleCN":"这项计划要求团队每位成员付出极大的努力。","why":"What cannot be measured can still be felt, and the word transfers from physical size to the size of an effort or a difficulty.","whyCN":"无法测量的东西仍然可以被感受到，于是这个词从物理大小转到努力或困难的大小。"},{"no":"04","title":"Of enormous importance","titleCN":"分量极重","definition":"carrying consequences so serious that they dominate a decision or an era","definitionCN":"带来的后果极其严重，足以主导一项决定或一个时代","example":"The decision carried immense consequences for the whole region.","exampleCN":"这个决定对整个地区带来了极其重大的后果。","why":"Importance is weighed rather than measured, and an unmeasurable weight is the natural image for a matter of the greatest seriousness.","whyCN":"重要性是被称量的而非被测量的，无法测量的重量自然成为最严重事务的意象。"},{"no":"05","title":"Unbounded or without limit","titleCN":"无边无际、没有限度","definition":"having no boundary, used especially of space, time or the divine in older writing","definitionCN":"没有边界，旧时多用于空间、时间或神性","example":"Ancient writers described the heavens as immense beyond measure.","exampleCN":"古代作家把天穹描述为无法计量的无边无际。","why":"The Latin source meant unmeasured, and early English kept that literal sense of something with no boundary at all.","whyCN":"拉丁语来源意为「未经测量」，早期英语保留了「完全没有边界」的字面义。"},{"no":"06","title":"Very large in amount","titleCN":"数额巨大","definition":"of money, wealth or a quantity that is far beyond ordinary figures","definitionCN":"指金钱、财富或数量远远超出常见数字","example":"The family fortune was immense by any standard of the time.","exampleCN":"按当时任何标准衡量，这家人的财富都极其巨大。","why":"Counting is a form of measuring, so an amount too large to grasp easily falls under the same word.","whyCN":"清点也是一种测量，因此大到难以把握的数额也归入这个词。"},{"no":"07","title":"Extremely good or enjoyable","titleCN":"极好的、非常令人愉快的","definition":"used in informal British speech to praise something as excellent","definitionCN":"英式口语中用来称赞某事极好","example":"The concert was immense fun for everyone in the hall.","exampleCN":"那场音乐会对礼堂里的每个人来说都极有趣。","why":"Slang often takes a word for size and applies it to quality, because a great experience feels larger than ordinary ones.","whyCN":"俚语常把表示大小的词用到质量上，因为极好的体验感觉比平常的经验更大。"},{"no":"08","title":"Very great in intensity","titleCN":"强度极大","definition":"of a feeling such as relief, joy or fear that fills a person completely","definitionCN":"指宽慰、喜悦或恐惧等感觉完全充满一个人","example":"She felt immense relief when the results finally arrived.","exampleCN":"结果终于到来时，她感到极大的宽慰。","why":"A feeling that fills the whole inner space is described with the same word as a space that fills the eye.","whyCN":"充满整个内心空间的感觉，用的正是描述充满视野的空间的那个词。"},{"no":"09","title":"Immeasurable by ordinary means","titleCN":"以寻常手段无法计量","definition":"so great that ordinary instruments or units cannot express it","definitionCN":"大到寻常仪器或单位无法表达","example":"The distance was immense, beyond any surveyor's chain.","exampleCN":"那段距离极其遥远，超出任何测量链所能及。","why":"This sense keeps the negative prefix visible: not measured rather than merely large.","whyCN":"这个义项让否定前缀保持可见：不是「量大」，而是「未被测量」。"}],"etymology":{"intro":{"en":"Immense comes from Latin immensus, unmeasured, built from a negative prefix and the participle of metiri, to measure. English borrowed it through French in the late Middle Ages.","cn":"这个词来自拉丁语 immensus「未经测量的」，由否定前缀与 metiri「测量」的过去分词构成，英语在中世纪末经法语借入。"},"items":[{"era":"LATIN METIRI","en":"Metiri meant to measure or allot, and it also gave English measure and dimension through related forms.","cn":"metiri 意为测量或分配，它还通过相关形式给英语带来「测量」与「维度」等词。"},{"era":"LATIN MENSUS","en":"The past participle mensus meant measured, so the compound began as a statement about measurement rather than about size.","cn":"过去分词 mensus 意为「已测量的」，因此这个复合词起初是在讲测量，而不是在讲大小。"},{"era":"LATIN IMMENSUS","en":"The negative prefix in- joined mensus to make immensus, unmeasured or boundless, a word used of the sea, the sky and the divine.","cn":"否定前缀 in- 与 mensus 结合成 immensus「未经测量的、无边的」，用于海、天与神性。"},{"era":"FRENCH IMMENSE","en":"French passed the adjective to English, where the literal idea of the unmeasured gradually faded into the simpler idea of the very large.","cn":"法语把这个形容词传给英语，其中「未经测量」的字面意思逐渐淡化为「非常大」这个更简单的意思。"},{"era":"ENGLISH IMMENSE","en":"English used the word for vast spaces first, then extended it to effort, wealth and feeling; the exact date of each extension is uncertain.","cn":"英语先用它形容辽阔空间，再扩展到努力、财富与情感；每次扩展的确切年代不确定。"},{"era":"MODERN INFORMAL USE","en":"Twentieth-century British speech added the praising sense of excellent, which now sits beside the older sense of huge.","cn":"二十世纪的英式口语加上「极好」的称赞义，如今与较旧的「巨大」义并存。"}]},"similar":{"note":{"en":"The first group looks or sounds like immense; the second group names neighbouring ideas of size and scale.","cn":"第一组在形音上与 immense 相近；第二组是与「大小、规模」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"immensity","ipa":"/ɪˈmensəti/","tag":"same root","definition":"The noun for the quality of being immense.","definitionCN":"指「巨大」这一性质的名词。"},{"word":"immensely","ipa":"/ɪˈmensli/","tag":"same root","definition":"The adverb meaning to a very great degree.","definitionCN":"指程度极大地。"},{"word":"immerse","ipa":"/ɪˈmɜːs/","tag":"different root","definition":"To put something completely into liquid; it looks close but comes from a verb meaning to dip.","definitionCN":"指把某物完全浸入液体；形近，但来自意为「浸入」的动词。"},{"word":"eminent","ipa":"/ˈemɪnənt/","tag":"different root","definition":"Famous and respected; it comes from a verb meaning to stand out.","definitionCN":"指著名而受尊敬；来自意为「突出」的动词。"},{"word":"imminent","ipa":"/ˈɪmɪnənt/","tag":"different root","definition":"About to happen very soon; the opening sound is similar but the root means to overhang.","definitionCN":"指即将发生；开头音相近，但词根意为「悬临」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"vast","ipa":"/vɑːst/","tag":"near meaning","definition":"Extremely wide or spread out, used mainly of land, sea and space.","definitionCN":"指极其宽广辽阔，多用于陆地、海洋与空间。"},{"word":"enormous","ipa":"/ɪˈnɔːməs/","tag":"near meaning","definition":"Very large in size or amount, often with a sense of excess.","definitionCN":"指体积或数量极大，常带有「过度」的意味。"},{"word":"colossal","ipa":"/kəˈlɒsl/","tag":"near meaning","definition":"Of a size that shocks the eye, as large as a giant statue.","definitionCN":"指大得令人吃惊，如巨型雕像般。"},{"word":"boundless","ipa":"/ˈbaʊndləs/","tag":"near meaning","definition":"Having no edge or limit, closer to the archaic sense of immense.","definitionCN":"指没有边缘或限度，更接近本词的旧义。"},{"word":"tremendous","ipa":"/trəˈmendəs/","tag":"near meaning","definition":"Very great in degree or force rather than in mere size.","definitionCN":"指程度或力量极大，而非仅指体积大。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the negative prefix, the measuring root and the real words built on it.","cn":"正常联想利用否定前缀、测量词根以及由它构成的真实单词。"},"normal":[{"en":"Immense begins with the same negative in- found in impossible, so it says not measurable.","cn":"词首的否定前缀与「不可能」一词相同，所以它说的是「无法测量」。"},{"en":"The measuring root survives in measure and dimension, which helps recall why the word means beyond measure.","cn":"测量词根仍留在「测量」与「维度」等同族词中，这有助于记住它为何是「超出测量」。"},{"en":"Think of a plain so wide that a map has to stop drawing it.","cn":"想象一片平原，宽到地图只能停止绘制。"},{"en":"Immense effort, immense pressure and immense wealth are the three phrases learners meet first.","cn":"极大的努力、极大的压力、巨额财富是学习者最先遇到的三组搭配。"},{"en":"The adverb immensely often does the work of very in ordinary speech.","cn":"它的副词形式在日常口语中常代替「非常」。"}],"abstract":[{"en":"What cannot be measured becomes a word for anything that overwhelms the senses.","cn":"无法测量的东西，最后成了形容一切压倒感官之物的词。"},{"en":"A thing is immense only relative to an observer small enough to feel it.","cn":"一物之所以巨大，只是相对于一个小到能感受到它的观察者。"},{"en":"The word carries a quiet warning: beyond measure is also beyond control.","cn":"这个词带着安静的警告：超出测量，也意味着超出控制。"}]},"examples":[{"en":"The bridge spans an immense river that freezes only in the coldest winters.","cn":"这座桥横跨一条巨大的河流，只有最冷的冬天它才会结冰。"},{"en":"She took immense pleasure in watching the garden come back to life.","cn":"看着花园重新焕发生机，她获得了极大的快乐。"},{"en":"The project consumed an immense amount of public money.","cn":"这个项目耗费了数额巨大的公共资金。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「亿门斯」——「亿」门那么大的东西，一眼望不到边：巨大的、广阔的","word":"immense"},"root":"拉丁语 immensus「未经测量的」← 否定前缀 in- + mensus「已测量的」（metiri「测量」的过去分词），经法语 immense 进入英语。同族有 measure、dimension。首义为「无边、无法计量」，后世俗化为「巨大」；各义项扩展的首见年代不确定。","sensesIntro":{"en":"Nine senses move from the body to the world and then inward: size, extent, degree, importance, boundlessness, amount, praise, feeling and the literal sense of the unmeasured.","cn":"九个义项从物体走向世界再转向内心：体积、范围、程度、重要性、无边界、数额、称赞、情感，以及「未经测量」的字面义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lake reaching past the horizon while the viewer shrinks to a small silhouette.","cn":"核心意象：湖面一直延伸到地平线之外，观看者缩成一个小小剪影。"},"chain":["NOT MEASURED","BEYOND THE EYE","GREAT SIZE","WIDE EXTENT","GREAT DEGREE","OVERWHELMING FEELING"],"branches":[{"senses":"01 · 02","en":"THE SPATIAL BRANCH: a body or a stretch of land too large to take in at once.","cn":"空间分支：一个物体或一片土地，大到无法一次收入眼中。"},{"senses":"03 · 08","en":"THE INTENSITY BRANCH: effort, pressure and feeling that fill the whole space of experience.","cn":"强度分支：填满整个经验空间的努力、压力与情感。"},{"senses":"04 · 06","en":"THE WEIGHT BRANCH: consequences and sums that dominate any ordinary scale.","cn":"重量分支：压过任何寻常尺度的后果与金额。"},{"senses":"05 · 09","en":"THE LITERAL BRANCH: the old sense of no boundary and no possible unit of measure.","cn":"字面分支：没有边界、也没有可用单位的旧义。"},{"senses":"07","en":"THE PRAISING BRANCH: informal speech turns sheer size into sheer enjoyment.","cn":"称赞分支：口语把纯粹的「大」转成纯粹的「好」。"}]},"affixes":{"intro":{"en":"Immense is a Latin participle wearing a negative prefix, with a small but living English family around it.","cn":"这是一个带否定前缀的拉丁语分词，周围有一小族仍在使用的英语派生词。"},"latinIntro":{"en":"Latin supplies in- and the measuring verb metiri with its participle mensus; French supplies the adjective form English borrowed.","cn":"拉丁语提供 in- 与测量动词 metiri 及其分词 mensus；法语提供英语借入的形容词形式。"},"items":[{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不；非","example":"The prefix turns measured into unmeasured.","exampleCN":"这个前缀把「已测量」变成「未测量」。"},{"word":"metiri","structure":"Latin verb, third conjugation","meaning":"to measure, to allot","meaningCN":"测量；分配","example":"The verb is the source of the whole family.","exampleCN":"这个动词是整族词的来源。"},{"word":"mensus","structure":"past participle of metiri","meaning":"measured","meaningCN":"已测量的","example":"The participle carries the idea of a finished measurement.","exampleCN":"这个分词带着「测量已完成」的意思。"},{"word":"immensus","structure":"in- plus mensus","meaning":"unmeasured, boundless","meaningCN":"未经测量的；无边的","example":"The Latin adjective described sea and sky.","exampleCN":"这个拉丁形容词曾用于描写海与天。"},{"word":"immense","structure":"English adjective from French","meaning":"huge, vast","meaningCN":"巨大的；广阔的","example":"English kept the adjective and dropped the literal negative force.","exampleCN":"英语留下了形容词，却淡化了字面的否定力量。"},{"word":"-ly","structure":"English adverb ending","meaning":"in a ... manner","meaningCN":"以……方式","example":"It builds immensely.","exampleCN":"它构成表示「极大地」的副词。"},{"word":"-ity","structure":"Latin noun ending through French","meaning":"quality of being","meaningCN":"……的性质","example":"It builds immensity.","exampleCN":"它构成表示「巨大」的名词。"},{"word":"-ness","structure":"English noun ending","meaning":"state of being","meaningCN":"……的状态","example":"It builds immenseness beside immensity.","exampleCN":"它构成与常用名词形式并存的另一名词形式，较少使用。"}],"latinEntries":[{"word":"metiri","structure":"metior, mensus sum (verb, third conjugation, deponent)","meaning":"to measure, to estimate","meaningCN":"测量；估量"},{"word":"mensus","structure":"past participle of metiri","meaning":"measured","meaningCN":"已测量的"},{"word":"immensus","structure":"immensus, immensa, immensum (adjective)","meaning":"unmeasured, boundless","meaningCN":"未经测量的；无边的"}],"derivatives":[{"word":"immensely","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「极大地；非常」"},{"word":"immensity","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「巨大；浩瀚」"},{"word":"immenseness","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「巨大」，是较常用名词形式的少见变体"}]}},{"word":"indispensable","ipa_uk":"/ˌɪndɪˈspensəbl/","ipa_us":"/ˌɪndɪˈspensəbl/","definition_zh":"不可或缺的；必不可少的；不可替代的","definition_en":"so necessary that it cannot be left out, given up or replaced","core_image":"手术台旁，护士把器械一件件递到医生手里，缺任何一件，流程立刻停住","scene":"手术开始前，护士把器械一件件排到医生手边，缺了任何一件，整个流程就停住。A steady supply of clean water is indispensable to any hospital.","sceneCN":"这里指完全不可缺少的（第 1 个义项：必不可少的）；句意为稳定的清洁水供应对任何医院来说都不可或缺。","pos":[{"tag":"adj.","zh":"不可或缺的；必不可少的；不可替代的"},{"tag":"n.","zh":"不可缺少的人或物（多用于口语）"}],"collocations":[{"phrase":"indispensable to","zh":"对……不可或缺"},{"phrase":"an indispensable part","zh":"不可缺少的部分"},{"phrase":"indispensable tool","zh":"必备工具"},{"phrase":"indispensable role","zh":"不可缺少的作用"},{"phrase":"indispensable condition","zh":"必要条件"},{"phrase":"absolutely indispensable","zh":"绝对不可缺少的"}],"forms":[{"label":"原级","form":"indispensable"},{"label":"比较级","form":"more indispensable"},{"label":"最高级","form":"most indispensable"},{"label":"名词（不可缺少）","form":"indispensability"},{"label":"副词","form":"indispensably"},{"label":"否定基础词（可省去的）","form":"dispensable"}],"derivatives":[{"word":"indispensability","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「不可或缺性」"},{"word":"indispensably","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「不可缺少地」"},{"word":"dispensable","pos":"adj.","zh":"该词去掉否定前缀后的基础形容词，义为「可省去的；可有可无的」"}],"senses":[{"no":"01","title":"Absolutely necessary","titleCN":"绝对必要","definition":"required to such a degree that the whole activity fails without it","definitionCN":"必要到一旦缺少，整个活动就无法进行","example":"Clean water is indispensable in any operating room.","exampleCN":"在任何手术室里，清洁的水都不可或缺。","why":"The Latin base meant something that could be dispensed with or exempted, so the negative form says it cannot be set aside.","whyCN":"拉丁词基意为「可以被免除、被省去的东西」，因此否定形式表示「不能被搁置一旁」。"},{"no":"02","title":"Impossible to replace","titleCN":"无法替代","definition":"of a person whose skills or presence no substitute can supply","definitionCN":"指某人的技能或在场没有任何替代者能够提供","example":"The old engineer was indispensable to the repair team.","exampleCN":"那位老工程师对维修班组来说不可替代。","why":"If a thing cannot be dispensed with, it also cannot be swapped for another, so necessity slides into uniqueness.","whyCN":"如果一样东西不能被省去，它也不能被换成别的，于是「必要」滑向「唯一」。"},{"no":"03","title":"Essential to a process","titleCN":"流程中的关键要件","definition":"a step, part or supply that the working order of a system depends on","definitionCN":"系统运转所依赖的步骤、部件或供应","example":"A cooling stage is indispensable in this manufacturing process.","exampleCN":"在这道制造流程中，冷却环节不可或缺。","why":"Processes are chains, and a link that cannot be removed is exactly what the negative word describes.","whyCN":"流程是一条链，而不能被去掉的一环正是这个否定词所描述的。"},{"no":"04","title":"Not subject to dispensation","titleCN":"教会法中不可豁免","definition":"in church law, of a rule or duty that no authority may waive for an individual","definitionCN":"教会法中指某项规则或义务，任何权威都不得对个人免除","example":"The council declared the obligation indispensable and refused every petition for waiver.","exampleCN":"会议宣布这项义务不可豁免，驳回了一切免除申请。","why":"This is the oldest sense: a dispensation is a granting of exemption, and what is indispensable cannot receive one.","whyCN":"这是最古老的义项：豁免是一种免除的授予，而不可或缺者无法获得这种授予。"},{"no":"05","title":"A person who is always needed","titleCN":"总被需要的人","definition":"in relaxed speech, someone whose help is sought on every occasion","definitionCN":"口语中指每逢事情都被求助的人","example":"At harvest time he becomes indispensable to every neighbour.","exampleCN":"到了收获季节，他对每一户邻居都变得不可或缺。","why":"The abstract sense of necessity attaches easily to people, especially where seasonal work creates sudden demand.","whyCN":"抽象的「必要」很容易附着在人身上，尤其当季节性劳作造成突然的需求时。"},{"no":"06","title":"A piece of essential equipment","titleCN":"必备的工具装备","definition":"an instrument or item that a trade or journey cannot be carried out without","definitionCN":"某种行业或旅程离开就无法进行的器具或物品","example":"A good lamp is indispensable on a night survey.","exampleCN":"夜间测量时，一盏好灯是必备的。","why":"Tools are the smallest removable parts of a task, so the word marks the ones that cannot be removed.","whyCN":"工具是任务中最小的可卸部件，因此这个词标出那些不能卸下的。"},{"no":"07","title":"A necessary condition","titleCN":"必要条件","definition":"a circumstance that must hold before a result can occur at all","definitionCN":"结果发生之前必须成立的情形","example":"Trust is an indispensable condition for any long negotiation.","exampleCN":"信任是任何长期谈判的必要条件。","why":"Logic speaks of necessary and sufficient conditions, and this sense names the necessary half in plain words.","whyCN":"逻辑学讲必要条件和充分条件，这个义项用平实的说法指出「必要」的那一半。"},{"no":"08","title":"Central to a role or function","titleCN":"在角色或功能上居于核心","definition":"performing a function that the whole organization or system relies on","definitionCN":"承担整个组织或系统所依赖的功能","example":"She played an indispensable role in holding the coalition together.","exampleCN":"她在维系这个联盟方面发挥了不可缺少的作用。","why":"A role is a place in a structure, and a place without which the structure collapses is indispensable by definition.","whyCN":"角色是结构中的一个位置，而缺少它结构就会崩塌的位置，按定义就是不可或缺的。"}],"etymology":{"intro":{"en":"Indispensable is an English negative built on Medieval Latin dispensabilis, which came from dispensare, to distribute or manage, and earlier from dispendere, to weigh out.","cn":"这个词是英语在中世纪拉丁语 dispensabilis 之上加否定成分构成，而 dispensabilis 出自 dispensare「分配、管理」，更早出自 dispendere「称量发放」。"},"items":[{"era":"LATIN PENDERE","en":"Pendere meant to hang or to weigh, and the weighing image sits under the whole family.","cn":"pendere 意为悬挂或称量，称量的意象支撑着整族词。"},{"era":"LATIN DISPENDERE","en":"The compound meant to weigh out or pay out, with the prefix marking distribution in different directions.","cn":"这个复合词意为称出、付出，前缀标出向不同方向的分配。"},{"era":"LATIN DISPENSARE","en":"The frequentative verb meant to manage, arrange or administer, and church Latin used it for granting exemptions.","cn":"这个反复动词意为管理、安排、经办，教会拉丁语用它表示授予豁免。"},{"era":"MEDIEVAL LATIN DISPENSABILIS","en":"The adjective meant that could be dispensed with or exempted, a term of canon law rather than of daily speech.","cn":"这个形容词意为「可以被免除、被豁免的」，是教会法术语而非日常用语。"},{"era":"ENGLISH INDISPENSABLE","en":"English added the negative prefix and reversed the sense: what cannot be exempted becomes what cannot be done without.","cn":"英语加上否定前缀，把意思翻转：不能被豁免的东西，变成不能缺少的东西。"},{"era":"MODERN GENERAL USE","en":"The legal flavour faded and the word spread to tools, people and conditions; the date of that spread is uncertain.","cn":"法律色彩淡去，词扩展到工具、人与条件；这一扩展的年代不确定。"}]},"similar":{"note":{"en":"The first group looks or sounds like indispensable; the second group names neighbouring ideas of necessity.","cn":"第一组在形音上与 indispensable 相近；第二组是与「必要」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dispensable","ipa":"/dɪˈspensəbl/","tag":"same root","definition":"Able to be given up or replaced, the base adjective without the negative prefix.","definitionCN":"指可以省去或替换的，是去掉否定前缀的基础形容词。"},{"word":"dispensation","ipa":"/ˌdɪspenˈseɪʃn/","tag":"same root","definition":"An official granting of exemption from a rule.","definitionCN":"指官方对某项规则的免除。"},{"word":"dispensary","ipa":"/dɪˈspensəri/","tag":"same root","definition":"A place where medicines are measured out and given.","definitionCN":"指称量并发放药品的场所。"},{"word":"indispensability","ipa":"/ˌɪndɪˌspensəˈbɪləti/","tag":"same root","definition":"The quality of being impossible to do without.","definitionCN":"指不可或缺的性质。"},{"word":"expense","ipa":"/ɪkˈspens/","tag":"different root","definition":"Money paid out; it shares a weighing image but comes through a different Latin compound.","definitionCN":"指支出的钱；共享称量的意象，但来自另一个拉丁复合词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"essential","ipa":"/ɪˈsenʃl/","tag":"near meaning","definition":"Belonging to the very nature of a thing, so that without it the thing is not itself.","definitionCN":"指属于事物本质的，缺少它事物便不再是自身。"},{"word":"vital","ipa":"/ˈvaɪtl/","tag":"near meaning","definition":"Necessary for life or for the success of something.","definitionCN":"指对生命或某事成功必不可少的。"},{"word":"crucial","ipa":"/ˈkruːʃl/","tag":"near meaning","definition":"Decisive at a turning point, where the outcome depends on it.","definitionCN":"指在转折点上起决定作用的。"},{"word":"necessary","ipa":"/ˈnesəsəri/","tag":"near meaning","definition":"Required by the situation, the weakest and most neutral of the group.","definitionCN":"指情形所要求的，是这组词中最弱、最中性的。"},{"word":"irreplaceable","ipa":"/ˌɪrɪˈpleɪsəbl/","tag":"near meaning","definition":"Of something whose loss no substitute can make good.","definitionCN":"指其损失无替代品可以弥补的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the negative prefix, the weighing-out root and the everyday phrases built on the word.","cn":"正常联想利用否定前缀、称量发放的词根以及由这个词构成的日常搭配。"},"normal":[{"en":"The prefix in- says no, and dispensable says able to be handed out or spared, so indispensable means cannot be spared.","cn":"否定前缀表示「不」，而基础形容词表示「可以发放、可以省去」，所以这个词就是「不能省去」。"},{"en":"A dispensary weighs and gives out medicine, which links the family to the idea of measuring out.","cn":"药房称量并发放药品，把这个词族与「称量发放」的意思连在一起。"},{"en":"In an operating room the indispensable things are the ones the nurse never puts down.","cn":"手术室里不可或缺的东西，就是护士从不放下的那些。"},{"en":"The usual pattern is indispensable to plus a noun or an activity.","cn":"常见结构是本词后接表示对象的介词，再加名词或活动。"},{"en":"Dispensable and indispensable are a matched pair, one with the negative prefix and one without.","cn":"基础形容词与本词是一对，一个带否定前缀，一个不带。"}],"abstract":[{"en":"Indispensable is a judgement made from inside a system, not a property a thing carries alone.","cn":"「不可或缺」是系统内部作出的判断，而不是事物单独携带的属性。"},{"en":"What cannot be exempted from a duty becomes, in modern speech, what cannot be excused from a task.","cn":"在旧时不能从义务中豁免的，到现代说法里变成不能从任务中缺席的。"},{"en":"Calling a person indispensable is a compliment with a burden inside it.","cn":"称一个人不可或缺，是一句里面藏着负担的赞美。"}]},"examples":[{"en":"A reliable power supply is indispensable for the data centre.","cn":"可靠供电对这座数据中心不可或缺。"},{"en":"The committee treated her as indispensable and refused to let her retire.","cn":"委员会视她为不可替代者，不肯让她退休。"},{"en":"Patience is indispensable when you teach beginners.","cn":"教初学者时，耐心是不可缺少的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因迪斯盆瑟波」——「因」为缺「盆」就装不了水，所以一样都不能少：不可或缺的","word":"indispensable"},"root":"中世纪拉丁语 dispensabilis「可免除的」← dispensare「分配、管理」← dispendere「称量发放」← pendere「悬挂、称量」；英语加否定前缀 in- 构成，意为「不可免除的」，再转为「不可或缺的」。教会法色彩为最早用法；世俗化的确切年代不确定。","sensesIntro":{"en":"Eight senses run from strict necessity through unreplaceable people, process steps, church exemption, tools, conditions and central roles.","cn":"八个义项从严格必要性出发，经过不可替代的人、流程环节、教会豁免、工具、条件，直到核心角色。"},"semanticMap":{"core":{"en":"CORE IMAGE: an instrument tray where one empty slot stops the whole operation.","cn":"核心意象：器械盘上有一个空位，整个手术就停住。"},"chain":["CANNOT BE SPARED","NO SUBSTITUTE","PROCESS LINK","NO EXEMPTION","REQUIRED CONDITION","CENTRAL ROLE"],"branches":[{"senses":"01 · 07","en":"THE STRICT NECESSITY BRANCH: the thing without which nothing starts and the condition that must hold.","cn":"严格必要分支：缺少它一切无法开始，以及必须成立的条件。"},{"senses":"02 · 05","en":"THE PEOPLE BRANCH: the expert no one can replace and the neighbour everyone calls on.","cn":"人的分支：无人能替代的专家，以及人人都会求助的邻居。"},{"senses":"03","en":"THE PROCESS BRANCH: a link in the chain that cannot be removed.","cn":"流程分支：链条中不能被去掉的一环。"},{"senses":"04","en":"THE LEGAL BRANCH: the oldest sense, where no authority may grant a waiver.","cn":"法律分支：最古老的义项，任何权威都不得授予豁免。"},{"senses":"06 · 08","en":"THE INSTRUMENT AND ROLE BRANCH: the tool the trade needs and the function the structure rests on.","cn":"工具与角色分支：行业需要的工具，以及结构所倚赖的功能。"}]},"affixes":{"intro":{"en":"Indispensable is a negative English formation over a Latin adjective that belonged to church law before it belonged to workshops.","cn":"这是一个英语否定构词，覆在拉丁形容词之上，而那个形容词先属教会法，后属工坊。"},"latinIntro":{"en":"Latin supplies the negative prefix in-, the verb pendere and its compounds dispendere, dispensare and dispensabilis.","cn":"拉丁语提供否定前缀 in-、动词 pendere 及其复合词 dispendere、dispensare 与 dispensabilis。"},"items":[{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不；非","example":"It reverses the meaning of the base adjective.","exampleCN":"它把基础形容词的意思翻转。"},{"word":"dis-","structure":"Latin prefix","meaning":"apart, in different directions","meaningCN":"分开；向各方","example":"The prefix marks goods being handed out.","exampleCN":"这个前缀标出货物被分发出去。"},{"word":"pendere","structure":"Latin verb, third conjugation","meaning":"to hang, to weigh","meaningCN":"悬挂；称量","example":"Weighing is the physical act under the family.","exampleCN":"称量是这个词族底下的物理动作。"},{"word":"dispendere","structure":"dis- plus pendere","meaning":"to weigh out, pay out","meaningCN":"称出；付出","example":"The compound adds the paying-out sense.","exampleCN":"这个复合词加上「付出」的意思。"},{"word":"dispensare","structure":"frequentative of dispendere","meaning":"to manage, distribute, exempt","meaningCN":"管理；分配；免除","example":"Church Latin used it for official exemption.","exampleCN":"教会拉丁语用它表示官方免除。"},{"word":"dispensabilis","structure":"dispensare plus -bilis","meaning":"that can be exempted","meaningCN":"可以被免除的","example":"The suffix -bilis marks possibility.","exampleCN":"这个拉丁词尾标出「可能性」。"},{"word":"-able","structure":"English possibility ending through French","meaning":"capable of being","meaningCN":"能被……的","example":"It turns the Latin stem into an English adjective.","exampleCN":"它把拉丁词干变成英语形容词。"},{"word":"-ity","structure":"Latin noun ending","meaning":"quality of being","meaningCN":"……的性质","example":"It builds indispensability.","exampleCN":"它构成表示「不可或缺性」的名词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in a ... manner","meaningCN":"以……方式","example":"It builds indispensably.","exampleCN":"它构成表示「不可缺少地」的副词。"}],"latinEntries":[{"word":"pendere","structure":"pendo, pependi, pensum (verb, third conjugation)","meaning":"to hang, weigh out","meaningCN":"悬挂；称量"},{"word":"dispendere","structure":"dis- plus pendere (verb, third conjugation)","meaning":"to weigh out, pay","meaningCN":"称出；支付"},{"word":"dispensare","structure":"dispenso, dispensavi, dispensatum (verb, first conjugation)","meaning":"to manage, distribute","meaningCN":"管理；分配"},{"word":"dispensabilis","structure":"adjective from dispensare","meaning":"that can be exempted","meaningCN":"可被免除的"}],"derivatives":[{"word":"indispensability","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「不可或缺性」"},{"word":"indispensably","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「不可缺少地」"},{"word":"dispensable","pos":"adj.","zh":"该词去掉否定前缀后的基础形容词，义为「可省去的；可有可无的」"}]}},{"word":"intermittent","ipa_uk":"/ˌɪntəˈmɪtənt/","ipa_us":"/ˌɪntərˈmɪtənt/","definition_zh":"间歇的；断断续续的；阵发的","definition_en":"stopping for a time and then starting again, so that activity comes in separate bursts","core_image":"山道上雨停一阵又下一阵，骑手反复收放雨衣，路面一会儿干一会儿湿","scene":"山道上，雨停一阵又下一阵，骑手反复收放雨衣，路面一会儿干一会儿湿。The rain was intermittent all afternoon, so the riders kept stopping.","sceneCN":"这里指活动时断时续的（第 1 个义项：间歇的）；句意为整个下午雨都下下停停，骑手只好不断停车。","pos":[{"tag":"adj.","zh":"间歇的；断断续续的；阵发的"}],"collocations":[{"phrase":"intermittent rain","zh":"间歇的降雨"},{"phrase":"intermittent fasting","zh":"间歇性禁食"},{"phrase":"intermittent signal","zh":"断续的信号"},{"phrase":"intermittent fault","zh":"偶发故障"},{"phrase":"intermittent employment","zh":"断断续续的就业"},{"phrase":"at intermittent intervals","zh":"以间歇的间隔"}],"forms":[{"label":"原级","form":"intermittent"},{"label":"比较级","form":"more intermittent"},{"label":"最高级","form":"most intermittent"},{"label":"名词（间歇）","form":"intermittence"},{"label":"副词","form":"intermittently"},{"label":"动词（中断）","form":"intermit"}],"derivatives":[{"word":"intermittently","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「间歇地；断断续续地」"},{"word":"intermittence","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「间歇性」"},{"word":"intermit","pos":"v.","zh":"去掉形容词词尾得到的同族动词，义为「暂时中断；间断」"}],"senses":[{"no":"01","title":"Stopping and starting at intervals","titleCN":"间歇发生","definition":"coming and going in separate periods rather than continuing without a break","definitionCN":"分成一段一段地来去，而不是不停顿地持续","example":"The machine made an intermittent noise that no technician could locate.","exampleCN":"这台机器发出间歇的噪声，没有技师能找到来源。","why":"The Latin verb meant to leave off between two points, so the adjective describes anything with gaps built into it.","whyCN":"拉丁动词意为「在两点之间停下」，因此这个形容词描述任何内建空隙的事物。"},{"no":"02","title":"Of a recurring fever or pulse","titleCN":"间歇性发热或脉搏","definition":"in medicine, of a symptom that returns in distinct episodes with free periods between them","definitionCN":"医学上指症状以独立发作反复出现，两次之间有正常期","example":"The patient ran an intermittent fever for six days.","exampleCN":"病人间歇性发热六天。","why":"Malaria taught doctors to name the pattern, because the fever vanished and returned on a schedule.","whyCN":"疟疾让医生学会为这种模式命名，因为发热按规律消失又回来。"},{"no":"03","title":"Of rain or weather in showers","titleCN":"阵发性的降雨","definition":"falling for short spells with dry intervals rather than steadily","definitionCN":"短时间落下，中间有干燥间隔，而非持续不断","example":"Farmers waited through intermittent showers to bring in the hay.","exampleCN":"农民在阵阵小雨中等待，好把干草收进来。","why":"Weather is the most visible example of on-and-off behaviour, so the word attaches to it early.","whyCN":"天气是「时有时无」最可见的例子，所以这个词很早就附着在天气上。"},{"no":"04","title":"Of a broken signal or connection","titleCN":"断续的信号或连接","definition":"of sound, power or data that keeps dropping out and returning","definitionCN":"指声音、电力或数据不断中断又恢复","example":"The radio gave an intermittent signal behind the hills.","exampleCN":"在山丘背后，收音机只给出断续的信号。","why":"A signal that disappears and reappears is the technical version of the same rhythm.","whyCN":"消失又出现的信号，是同一节奏的技术版本。"},{"no":"05","title":"Of eating or treatment in cycles","titleCN":"周期性进行的饮食或治疗","definition":"carried out in planned periods of action separated by periods of rest","definitionCN":"按计划分成行动期与休息期交替进行","example":"Intermittent fasting asks people to eat only within a fixed window.","exampleCN":"间歇性禁食要求人们只在固定时段内进食。","why":"The word supplies the idea of deliberate gaps, which is exactly what a cycle of eating and resting needs.","whyCN":"这个词提供「刻意留出空隙」的意思，而这正是进食与休息循环所需要的。"},{"no":"06","title":"Of work that comes and goes","titleCN":"断断续续的工作","definition":"of employment or effort that is available only in separate periods","definitionCN":"指就业或劳作只在分开的时段内可得","example":"Seasonal hotels depend on intermittent labour.","exampleCN":"季节性旅馆依赖断断续续的劳动力。","why":"Work that stops between seasons has the same shape as rain that stops between showers.","whyCN":"季节之间停工的工作，与阵雨之间停下的雨形状相同。"},{"no":"07","title":"Of attention that comes and goes","titleCN":"时有时无的注意","definition":"of concentration that is strong for a while and then lapses","definitionCN":"指专注维持一阵之后又滑走","example":"His intermittent attention missed half of the instructions.","exampleCN":"他时有时无的注意力漏掉了半数指令。","why":"Attention is a resource that switches on and off, and the word is borrowed to describe that switching.","whyCN":"注意力是一种会开启又关闭的资源，这个词被借来描述这种开关。"},{"no":"08","title":"Of a fault that appears and disappears","titleCN":"偶发故障","definition":"of a defect that cannot be reproduced on demand and vanishes during tests","definitionCN":"指无法按需复现、在检测时消失的缺陷","example":"The intermittent fault disappeared the moment the engineer arrived.","exampleCN":"工程师一到，那个偶发故障就消失了。","why":"Engineering needs a word for failures that refuse to stay still, and on-and-off is their defining feature.","whyCN":"工程领域需要为不肯静止的故障找个词，而「时有时无」正是它们的定义特征。"}],"etymology":{"intro":{"en":"Intermittent comes from the Latin present participle intermittens, from intermittere, to leave off or break off, built from inter, between, and mittere, to send or let go.","cn":"这个词来自拉丁语现在分词 intermittens，出自 intermittere「中止、中断」，由 inter「在……之间」与 mittere「送出、放开」构成。"},"items":[{"era":"LATIN MITTERE","en":"Mittere meant to send or to let go, and its family includes admit, submit and transmit.","cn":"mittere 意为送出或放开，同族包括 admit、submit 与 transmit。"},{"era":"LATIN INTER PREFIX","en":"The prefix meant between or among, and it places a gap in the middle of an action.","cn":"这个前缀意为「在……之间」，把一段空隙放进一个动作的中间。"},{"era":"LATIN INTERMITTERE","en":"The verb meant to leave off for a time, to break off in the middle, and it was used of work, speech and illness.","cn":"这个动词意为暂停一段时间、中途断开，曾用于工作、言语与疾病。"},{"era":"LATIN INTERMITTENTEM","en":"The participle described something that was leaving off, and medical Latin used it for fevers with free intervals.","cn":"这个分词描述正在中断的事物，医学拉丁语用它指有正常间隔的发热。"},{"era":"ENGLISH INTERMITTENT","en":"English adopted the adjective in the seventeenth century, first for fevers and then for any rhythm of stopping and starting.","cn":"英语在十七世纪引入这个形容词，先用于发热，再用于任何一停一启的节奏。"},{"era":"MODERN TECHNICAL USE","en":"Telegraphy, radio and engineering extended the word to signals and faults; each extension has an uncertain first date.","cn":"电报、无线电与工程把它扩展到信号与故障；每次扩展的确切首见年代不确定。"}]},"similar":{"note":{"en":"The first group looks or sounds like intermittent; the second group names neighbouring ideas of rhythm and frequency.","cn":"第一组在形音上与 intermittent 相近；第二组是与「节奏、频率」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"intermittently","ipa":"/ˌɪntəˈmɪtəntli/","tag":"same root","definition":"The adverb meaning in an on-and-off way.","definitionCN":"指以时断时续的方式。"},{"word":"intermittence","ipa":"/ˌɪntəˈmɪtəns/","tag":"same root","definition":"The noun for the state of stopping and starting.","definitionCN":"指时断时续状态的名词。"},{"word":"intermit","ipa":"/ˌɪntəˈmɪt/","tag":"same root","definition":"The verb meaning to suspend activity for a time.","definitionCN":"指暂时停止活动。"},{"word":"intermission","ipa":"/ˌɪntəˈmɪʃn/","tag":"same root","definition":"A pause between two parts of an event, such as a play or a storm.","definitionCN":"指事件两部分之间的停顿，如演出或风暴的中场。"},{"word":"intermingle","ipa":"/ˌɪntəˈmɪŋɡl/","tag":"different root","definition":"To mix together; it shares the prefix but its root means to mix.","definitionCN":"指混合在一起；共享前缀，但词根意为「混合」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sporadic","ipa":"/spəˈrædɪk/","tag":"near meaning","definition":"Happening here and there without any regular pattern.","definitionCN":"指零散发生，没有规律。"},{"word":"periodic","ipa":"/ˌpɪəriˈɒdɪk/","tag":"near meaning","definition":"Repeating at regular intervals, the opposite of irregular.","definitionCN":"指按固定间隔重复，与「不规则」相反。"},{"word":"episodic","ipa":"/ˌepɪˈsɒdɪk/","tag":"near meaning","definition":"Arranged in separate episodes rather than as a continuous whole.","definitionCN":"指分成独立片段而非连续整体。"},{"word":"fitful","ipa":"/ˈfɪtfl/","tag":"near meaning","definition":"Active in short uneven bursts, often of sleep or wind.","definitionCN":"指以短促而不均匀的阵发方式进行，常用于睡眠或风。"},{"word":"occasional","ipa":"/əˈkeɪʒənl/","tag":"near meaning","definition":"Happening from time to time without regularity.","definitionCN":"指不时发生而无规律。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the between-prefix, the letting-go root and the medical phrases the word first served.","cn":"正常联想利用「之间」前缀、「放开」词根，以及这个词最早服务的医学搭配。"},"normal":[{"en":"Inter- means between, so intermittent describes what has a gap between its parts.","cn":"前缀意为「之间」，所以这个词描述的是各部分之间有间隙的东西。"},{"en":"Intermittent fever was the first common use, which is why the word still sounds medical.","cn":"间歇热是最早的常见用法，所以这个词至今听来仍带医学味。"},{"en":"Intermittent rain and intermittent fasting are the two phrases most learners already know.","cn":"间歇降雨与间歇性禁食是学习者最熟悉的两个搭配。"},{"en":"The verb intermit is rarer than the adjective but carries the same middle gap.","cn":"同族动词比形容词少见，但带着同一个「中间的间隙」。"},{"en":"An intermittent fault is the engineer's nightmare because it hides during tests.","cn":"偶发故障是工程师的噩梦，因为它在检测时躲起来。"}],"abstract":[{"en":"Intermittent is the shape of anything that cannot keep a promise of continuity.","cn":"「间歇」是一切无法守住连续性承诺之物的形状。"},{"en":"The word measures not how often a thing happens but how cleanly it stops.","cn":"这个词量的不是事情多常发生，而是它停得有多干净。"},{"en":"A gap is part of the event, not an absence of it.","cn":"空隙是事件的一部分，而不是事件缺失。"}]},"examples":[{"en":"The lighthouse sent an intermittent beam across the water.","cn":"灯塔向水面送出间歇的光束。"},{"en":"Intermittent power cuts slowed the factory for a month.","cn":"间歇停电让工厂减产了一个月。"},{"en":"Her cough was intermittent but never fully went away.","cn":"她的咳嗽时有时无，却从未完全消失。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因特米腾特」——雨「因」为「特」别爱「腾」来腾去，停一阵下一阵：间歇的","word":"intermittent"},"root":"拉丁语 intermittens（intermittere 的现在分词）← inter-「在……之间」+ mittere「送出、放开」；mittere 同族有 admit、submit、transmit。最初用于有正常间隔的发热，十七世纪进入英语，后扩展到信号、故障等；各技术义项的首见年代不确定。","sensesIntro":{"en":"Eight senses share one rhythm: general on-and-off behaviour, fever, showers, signals, cycles of eating, seasonal work, wavering attention and elusive faults.","cn":"八个义项共享一种节奏：一般的时断时续、发热、阵雨、信号、饮食周期、季节性工作、游移的注意，以及难以捕捉的故障。"},"semanticMap":{"core":{"en":"CORE IMAGE: a shower that stops, lets the road dry, and starts again.","cn":"核心意象：一阵雨停下，路面刚干，又下起来。"},"chain":["A GAP IN THE MIDDLE","STOP AND START","RETURN ON A RHYTHM","VISIBLE IN WEATHER","MEASURED IN MACHINES","FELT IN THE BODY"],"branches":[{"senses":"01 · 06","en":"THE GENERAL RHYTHM BRANCH: on-and-off activity and work that exists only in seasons.","cn":"一般节奏分支：时断时续的活动，以及只在季节中存在的工作。"},{"senses":"02 · 07","en":"THE BODY BRANCH: fever with free intervals and attention that lapses.","cn":"身体分支：有正常间隔的发热，以及会滑走的注意力。"},{"senses":"03","en":"THE WEATHER BRANCH: showers that leave dry stretches between them.","cn":"天气分支：阵雨之间留下干燥的间隔。"},{"senses":"04 · 08","en":"THE MACHINE BRANCH: signals that drop out and faults that hide during tests.","cn":"机器分支：会掉线的信号，以及检测时躲藏的故障。"},{"senses":"05","en":"THE PLANNED CYCLE BRANCH: eating or treatment divided into deliberate periods.","cn":"计划周期分支：把进食或治疗划分成刻意安排的时段。"}]},"affixes":{"intro":{"en":"Intermittent is a Latin participle used as an English adjective, with a prefix that puts a gap in the middle of an action.","cn":"这是一个用作英语形容词的拉丁语分词，其前缀把一个空隙放进动作的中间。"},"latinIntro":{"en":"Latin inter- and mittere combine in intermittere, whose participle intermittens is the direct source.","cn":"拉丁语 inter- 与 mittere 合成 intermittere，其分词 intermittens 是直接来源。"},"items":[{"word":"inter-","structure":"Latin prefix","meaning":"between, among","meaningCN":"在……之间；在……之中","example":"The prefix places the gap inside the action.","exampleCN":"这个前缀把空隙放进动作内部。"},{"word":"mittere","structure":"Latin verb, third conjugation","meaning":"to send, let go","meaningCN":"送出；放开","example":"The root also builds admit and transmit.","exampleCN":"这个词根也构成表示「准许进入」与「传送」的同族动词。"},{"word":"intermittere","structure":"inter- plus mittere","meaning":"to leave off, break off","meaningCN":"暂停；中断","example":"The verb is the source of the whole family.","exampleCN":"这个动词是整族词的来源。"},{"word":"intermittens","structure":"present participle of intermittere","meaning":"leaving off, intermittent","meaningCN":"正在中断的；间歇的","example":"Medical Latin used it for fevers.","exampleCN":"医学拉丁语用它形容发热。"},{"word":"-ent","structure":"Latin participle ending","meaning":"being in a state","meaningCN":"处于某种状态","example":"The ending makes the participle an adjective.","exampleCN":"这个词尾把分词变成形容词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in a ... manner","meaningCN":"以……方式","example":"It builds intermittently.","exampleCN":"它构成表示「间歇地」的副词。"},{"word":"-ence","structure":"Latin noun ending through French","meaning":"state or quality","meaningCN":"状态或性质","example":"It builds intermittence.","exampleCN":"它构成表示「间歇性」的名词。"},{"word":"intermit","structure":"English verb from the Latin stem","meaning":"to suspend for a time","meaningCN":"暂时中止","example":"English formed a verb from the same stem.","exampleCN":"英语用同一词干造出一个动词。"}],"latinEntries":[{"word":"mittere","structure":"mitto, misi, missum (verb, third conjugation)","meaning":"to send, let go","meaningCN":"送出；放开"},{"word":"intermittere","structure":"inter- plus mittere (verb, third conjugation)","meaning":"to leave off, interrupt","meaningCN":"暂停；中断"},{"word":"intermittens","structure":"present participle of intermittere","meaning":"intermittent, leaving off","meaningCN":"间歇的；中断的"},{"word":"intermissio","structure":"noun from intermittere","meaning":"a pause, an interruption","meaningCN":"停顿；中断"}],"derivatives":[{"word":"intermittently","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「间歇地；断断续续地」"},{"word":"intermittence","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「间歇性」"},{"word":"intermit","pos":"v.","zh":"去掉形容词词尾得到的同族动词，义为「暂时中断；间断」"}]}},{"word":"irreversible","ipa_uk":"/ˌɪrɪˈvɜːsəbl/","ipa_us":"/ˌɪrɪˈvɜːrsəbl/","definition_zh":"不可逆的；无法挽回的；不可撤销的","definition_en":"impossible to turn back, undo or restore to an earlier state","core_image":"推土机把最后一段沙洲推平，河水立刻改了方向，原来的浅滩再也回不来","scene":"河岸边，推土机刚把最后一段沙洲推平，河水立刻改了方向，旧浅滩再也回不来。Once the wetland was filled, the loss became irreversible.","sceneCN":"这里指已经无法挽回的（第 2 个义项：不可撤销、无法复原）；句意为湿地一旦被填平，损失就再也无法挽回。","pos":[{"tag":"adj.","zh":"不可逆的；无法挽回的；不可撤销的"}],"collocations":[{"phrase":"irreversible change","zh":"不可逆的变化"},{"phrase":"irreversible damage","zh":"不可逆的损伤"},{"phrase":"irreversible process","zh":"不可逆过程"},{"phrase":"irreversible decision","zh":"不可撤回的决定"},{"phrase":"irreversible decline","zh":"不可逆转的衰退"},{"phrase":"virtually irreversible","zh":"几乎不可逆的"}],"forms":[{"label":"原级","form":"irreversible"},{"label":"比较级","form":"more irreversible"},{"label":"最高级","form":"most irreversible"},{"label":"名词（不可逆性）","form":"irreversibility"},{"label":"副词","form":"irreversibly"},{"label":"肯定形式","form":"reversible"}],"derivatives":[{"word":"irreversibly","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「不可逆地」"},{"word":"irreversibility","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「不可逆性」"},{"word":"reversible","pos":"adj.","zh":"该词去掉否定前缀后的基础形容词，义为「可逆的；可翻转的」"}],"senses":[{"no":"01","title":"Impossible to turn back in direction","titleCN":"方向不可倒转","definition":"of a movement or process that cannot run the opposite way once it has begun","definitionCN":"指运动或过程一旦开始，就无法朝相反方向运行","example":"The current through the valve is irreversible, so water never flows back.","exampleCN":"通过阀门的水流不可倒转，所以水从不回流。","why":"The base verb means to turn, and the negative prefix forbids the turning back, so the word literally says cannot be turned.","whyCN":"基础动词意为「转」，否定前缀禁止「转回去」，所以这个词字面上就是「不能被转回」。"},{"no":"02","title":"Impossible to undo","titleCN":"无法撤销或复原","definition":"of a decision or an act whose effects cannot be cancelled afterwards","definitionCN":"指决定或行为的效果事后无法取消","example":"Signing the deed made the sale irreversible.","exampleCN":"签署契据使这笔买卖无法撤销。","why":"Some acts are doors that close behind you, and English uses the turning image for exactly those.","whyCN":"有些行为是会在身后关上的门，英语正是用「转回」的意象来形容它们。"},{"no":"03","title":"Of a thermodynamic process","titleCN":"热力学中的不可逆过程","definition":"in physics, of a process that increases entropy and cannot be run backwards without outside work","definitionCN":"物理学中指使熵增加、若无外界做功便无法反向进行的过程","example":"Heat flowing from a hot body to a cold one is an irreversible process.","exampleCN":"热从高温物体流向低温物体是一个不可逆过程。","why":"Physics needed a precise word for the direction of time written into energy, and the everyday word supplied it.","whyCN":"物理学需要为写在能量里的时间方向找一个精确的词，而日常词语正好提供了它。"},{"no":"04","title":"Of permanent damage","titleCN":"永久性损伤","definition":"of harm to tissue, material or land that no treatment or repair can remove","definitionCN":"指对组织、材料或土地的伤害，任何治疗或修复都无法消除","example":"The frost caused irreversible damage to the young trees.","exampleCN":"霜冻对幼树造成了不可逆的损伤。","why":"Damage is measured by whether it can be repaired, and this word marks the point where repair stops being possible.","whyCN":"损伤以能否修复来衡量，而这个词标出了修复不再可能的那条线。"},{"no":"05","title":"Of a change that cannot be reversed","titleCN":"不可逆转的变化","definition":"of a long trend or transformation that will not return to its starting condition","definitionCN":"指长期趋势或转变不会回到起始状态","example":"The shift from coal to gas proved irreversible.","exampleCN":"从煤转向天然气的转变被证明不可逆转。","why":"Large changes are judged by whether a society could plausibly go back, and the word answers that question.","whyCN":"重大变化以「社会是否可能退回」来评判，而这个词回答的正是这个问题。"},{"no":"06","title":"Of a medical condition","titleCN":"不可逆的病情","definition":"of a disease or loss of function that treatment can slow but never restore","definitionCN":"指治疗只能延缓、永远无法恢复的疾病或功能丧失","example":"The scan showed irreversible damage to the optic nerve.","exampleCN":"扫描显示视神经受到了不可逆的损伤。","why":"Medicine divides conditions by whether the body can return, and the word names the side where it cannot.","whyCN":"医学以身体能否恢复来划分病情，而这个词命名的正是「不能」的那一侧。"},{"no":"07","title":"Of a commitment that cannot be withdrawn","titleCN":"不可撤回的承诺","definition":"of a promise or contract that binds the maker with no way out","definitionCN":"指承诺或合同约束作出者，没有退路","example":"The treaty created an irreversible commitment to the alliance.","exampleCN":"该条约造成了对同盟不可撤回的承诺。","why":"A promise is a door that locks, and the turning image suits a choice that cannot be taken back.","whyCN":"承诺是一扇会锁上的门，「转回」的意象正适合无法收回的选择。"},{"no":"08","title":"Of an environmental loss","titleCN":"不可逆的环境损失","definition":"of the destruction of an ecosystem or species that no restoration can bring back","definitionCN":"指生态系统或物种的毁坏，任何修复都无法带回","example":"Draining the marsh caused an irreversible loss of habitat.","exampleCN":"排干沼泽造成了栖息地的不可逆丧失。","why":"Extinction is the clearest case of no return, and the word carries that finality into policy language.","whyCN":"灭绝是「无法回头」最清楚的例子，而这个词把这种终结性带进政策语言。"},{"no":"09","title":"Of decline that cannot be halted","titleCN":"不可逆转的衰退","definition":"of a fall in health, memory or capacity that continues regardless of effort","definitionCN":"指健康、记忆或能力的下降，无论怎样努力都持续下去","example":"The patient entered an irreversible decline after the second stroke.","exampleCN":"第二次中风之后，病人进入了不可逆转的衰退。","why":"Decline is a slope, and a slope with no uphill direction is naturally called irreversible.","whyCN":"衰退是一道坡，而没有上坡方向的坡自然被称作不可逆。"}],"etymology":{"intro":{"en":"Irreversible joins a negative prefix to reversible, which comes from Latin reversibilis, from revertere, to turn back, built from re-, back, and vertere, to turn.","cn":"这个词把否定前缀加在 reversible 上，而 reversible 出自拉丁语 reversibilis，来自 revertere「转回」，由 re-「向后」与 vertere「转」构成。"},"items":[{"era":"LATIN VERTERE","en":"Vertere meant to turn, and its family reaches English through convert, divert, invert and version.","cn":"vertere 意为转，其同族通过 convert、divert、invert 与 version 进入英语。"},{"era":"LATIN REVERTERE","en":"The compound meant to turn back or return, and it is the direct ancestor of reverse and revert.","cn":"这个复合词意为转回、返回，是 reverse 与 revert 的直接祖先。"},{"era":"LATIN REVERSIBILIS","en":"The adjective meant able to be turned back, a word of logic and later of physics.","cn":"这个形容词意为「可以被转回的」，先是逻辑学术语，后来成为物理学术语。"},{"era":"FRENCH REVERSIBLE","en":"French passed the adjective to English, where reversible described garments, decisions and machines.","cn":"法语把这个形容词传给英语，reversible 在那里形容可翻面的衣物、可撤销的决定与可反转的机器。"},{"era":"ENGLISH IRREVERSIBLE","en":"English formed the negative with the assimilated prefix ir-, and the word entered technical writing in the nineteenth century; the exact first date is uncertain.","cn":"英语用同化后的前缀 ir- 构成否定形式，这个词在十九世纪进入技术写作；确切首见年代不确定。"},{"era":"MODERN SCIENTIFIC USE","en":"Thermodynamics gave the word its sharpest sense, where an irreversible process fixes the direction of time.","cn":"热力学赋予这个词最锋利的意义：不可逆过程固定了时间的方向。"}]},"similar":{"note":{"en":"The first group looks or sounds like irreversible; the second group names neighbouring ideas of permanence.","cn":"第一组在形音上与 irreversible 相近；第二组是与「永久、不可更改」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reversible","ipa":"/rɪˈvɜːsəbl/","tag":"same root","definition":"Able to be turned back or undone, the base of this word.","definitionCN":"指可以转回或撤销的，是本词的基础形式。"},{"word":"irreversibly","ipa":"/ˌɪrɪˈvɜːsəbli/","tag":"same root","definition":"The adverb meaning in a way that cannot be undone.","definitionCN":"指以无法挽回的方式。"},{"word":"irreversibility","ipa":"/ˌɪrɪˌvɜːsəˈbɪləti/","tag":"same root","definition":"The noun for the state of being impossible to reverse.","definitionCN":"指不可逆转状态的名词。"},{"word":"reverse","ipa":"/rɪˈvɜːs/","tag":"same root","definition":"To turn something the other way, or the opposite side of it.","definitionCN":"指把某物转向另一面，或指其反面。"},{"word":"irrevocable","ipa":"/ɪˈrevəkəbl/","tag":"different root","definition":"Impossible to cancel; it looks close but its root means to call back, not to turn.","definitionCN":"指无法取消的；形近，但词根意为「召回」而非「转」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"permanent","ipa":"/ˈpɜːmənənt/","tag":"near meaning","definition":"Lasting for the whole future, with no planned end.","definitionCN":"指持续到整个未来，没有计划的终点。"},{"word":"irreparable","ipa":"/ɪˈrepərəbl/","tag":"near meaning","definition":"Of damage or loss that cannot be repaired or made good.","definitionCN":"指损伤或损失无法修复或弥补。"},{"word":"irretrievable","ipa":"/ˌɪrɪˈtriːvəbl/","tag":"near meaning","definition":"Of something that cannot be recovered once lost.","definitionCN":"指一旦失去便无法找回。"},{"word":"final","ipa":"/ˈfaɪnl/","tag":"near meaning","definition":"Settling a matter so that no further change is allowed.","definitionCN":"指对事情作出定论，不再允许更改。"},{"word":"irremediable","ipa":"/ˌɪrɪˈmiːdiəbl/","tag":"near meaning","definition":"Of a bad condition that no remedy can cure.","definitionCN":"指恶劣状况无药可救。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the negative prefix, the turning root and the scientific phrases the word now lives in.","cn":"正常联想利用否定前缀、「转」的词根，以及这个词如今栖身的科学搭配。"},"normal":[{"en":"Reverse means to turn back, so irreversible means the turning back is forbidden.","cn":"同族动词意为「转回」，所以这个词意为「转回被禁止」。"},{"en":"The same root builds convert, divert and invert, all of which describe a change of direction.","cn":"同一词根构成表示「转换」「转向」与「倒转」的同族词，都在描述方向的改变。"},{"en":"An irreversible process is the physicist's way of saying time has a direction.","cn":"不可逆过程是物理学家表达「时间有方向」的方式。"},{"en":"Irreversible damage is the phrase used in medicine, law and environmental reports alike.","cn":"不可逆损伤是医学、法律与环境报告中都在用的说法。"},{"en":"The prefix appears as ir- rather than in- because the following sound is r.","cn":"否定前缀在流音前发生同化，拼写也随之改变。"}],"abstract":[{"en":"Irreversible is the price tag attached to any act that closes its own door.","cn":"「不可逆」是贴在一切自我关门的行为上的价签。"},{"en":"The word does not say the past is long; it says the past cannot be re-entered.","cn":"这个词说的不是过去很长，而是过去无法再进入。"},{"en":"Every irreversible choice makes the future narrower and the present heavier.","cn":"每一个不可逆的选择都让未来更窄、当下更重。"}]},"examples":[{"en":"Once the ice sheet melts past that point, the rise becomes irreversible.","cn":"一旦冰盖越过那个临界点，海面上升就变得不可逆。"},{"en":"The court treated the transfer of land as an irreversible act.","cn":"法院把这块土地的转让视为不可撤销的行为。"},{"en":"Years of overgrazing pushed the grassland into irreversible decline.","cn":"多年过度放牧把草原推入不可逆转的衰退。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「伊利佛瑟波」——「伊利」都「佛」了，倒带键按不下去：不可逆的","word":"irreversible"},"root":"拉丁语 reversibilis「可转回的」← revertere「转回」← re-「向后」+ vertere「转」；英语加同化否定前缀 ir- 构成。vertere 同族有 convert、divert、invert、version。十九世纪进入技术写作，确切首见年代不确定。","sensesIntro":{"en":"Nine senses apply one idea to different fields: direction, undone acts, entropy, damage, trends, illness, promises, extinction and decline.","cn":"九个义项把同一个观念用到不同领域：方向、撤销的行为、熵、损伤、趋势、疾病、承诺、物种灭绝与衰退。"},"semanticMap":{"core":{"en":"CORE IMAGE: a river that has cut a new channel and will not return to the old one.","cn":"核心意象：河流已开出新河道，不会回到旧河道。"},"chain":["NO TURNING BACK","NO UNDOING","DIRECTION FIXED","STATE FIXED","TIME FIXED","FUTURE NARROWED"],"branches":[{"senses":"01 · 03","en":"THE PHYSICAL DIRECTION BRANCH: flow that cannot run backwards and entropy that only grows.","cn":"物理方向分支：不能倒流的水流，以及只增不减的熵。"},{"senses":"02 · 07","en":"THE BINDING ACT BRANCH: a signature or a promise that closes behind the maker.","cn":"约束行为分支：在作出者身后关上的签字或承诺。"},{"senses":"04 · 06","en":"THE BODY AND MATERIAL BRANCH: damage that no treatment or repair can remove.","cn":"身体与材料分支：任何治疗或修复都无法消除的损伤。"},{"senses":"05 · 08","en":"THE LARGE-SCALE BRANCH: social trends and lost habitats that will not return.","cn":"大规模分支：不会回返的社会趋势与消失的栖息地。"},{"senses":"09","en":"THE SLOPE BRANCH: decline with no uphill direction left.","cn":"斜坡分支：没有上坡方向可走的衰退。"}]},"affixes":{"intro":{"en":"Irreversible is a Latin adjective of turning with a negative prefix that has assimilated to the following sound.","cn":"这是一个表示「转」的拉丁形容词，加上一个已与后接音同化的否定前缀。"},"latinIntro":{"en":"Latin supplies vertere, revertere and reversibilis; the English negative prefix appears as ir- before r.","cn":"拉丁语提供 vertere、revertere 与 reversibilis；英语否定前缀在 r 前写作 ir-。"},"items":[{"word":"ir-","structure":"assimilated negative prefix","meaning":"not","meaningCN":"不；非","example":"It negates the base adjective.","exampleCN":"它否定基础形容词。"},{"word":"re-","structure":"Latin prefix","meaning":"back, again","meaningCN":"向后；再次","example":"The prefix marks a return to the starting point.","exampleCN":"这个前缀标出回到起点。"},{"word":"vertere","structure":"Latin verb, third conjugation","meaning":"to turn","meaningCN":"转；转动","example":"The root builds many English direction words.","exampleCN":"这个词根构成许多英语方向词。"},{"word":"revertere","structure":"re- plus vertere","meaning":"to turn back, return","meaningCN":"转回；返回","example":"The compound is the source of reverse.","exampleCN":"这个复合词是表示「逆转」的同族词的来源。"},{"word":"reversibilis","structure":"revertere plus -bilis","meaning":"able to be turned back","meaningCN":"可以被转回的","example":"The suffix marks possibility.","exampleCN":"这个后缀标出可能性。"},{"word":"-ible","structure":"Latin possibility ending through French","meaning":"capable of being","meaningCN":"能被……的","example":"It forms the English adjective.","exampleCN":"它构成英语形容词。"},{"word":"-ity","structure":"Latin noun ending","meaning":"quality of being","meaningCN":"……的性质","example":"It builds irreversibility.","exampleCN":"它构成表示「不可逆性」的名词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in a ... manner","meaningCN":"以……方式","example":"It builds irreversibly.","exampleCN":"它构成表示「不可逆地」的副词。"}],"latinEntries":[{"word":"vertere","structure":"verto, verti, versum (verb, third conjugation)","meaning":"to turn","meaningCN":"转；转动"},{"word":"revertere","structure":"re- plus vertere (verb, third conjugation)","meaning":"to turn back","meaningCN":"转回；返回"},{"word":"reversibilis","structure":"adjective from revertere","meaning":"able to be turned back","meaningCN":"可转回的"},{"word":"reversio","structure":"noun from revertere","meaning":"a turning back","meaningCN":"转回；返回"}],"derivatives":[{"word":"irreversibly","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「不可逆地」"},{"word":"irreversibility","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「不可逆性」"},{"word":"reversible","pos":"adj.","zh":"该词去掉否定前缀后的基础形容词，义为「可逆的；可翻转的」"}]}},{"word":"legitimate","ipa_uk":"/lɪˈdʒɪtɪmət/","ipa_us":"/lɪˈdʒɪtɪmət/","definition_zh":"合法的；合理的；正当的；正统的；婚生的","definition_en":"allowed by law, supported by good reason, genuine and valid, or rightful by established authority","core_image":"市政厅窗口前，办事员把执照递到申请人手上，逐条核对经营范围和地址","scene":"市政厅窗口前，办事员把执照递到申请人手上，逐条核对经营范围和地址。Only businesses with a legitimate licence may operate here.","sceneCN":"这里指依法获准的（第 1 个义项：合法的）；句意为只有持有合法执照的企业才能在此经营。","pos":[{"tag":"adj.","zh":"合法的；合理的；正当的；正统的；婚生的"},{"tag":"v.","zh":"使合法；使正当（较少用）"}],"collocations":[{"phrase":"legitimate business","zh":"合法经营"},{"phrase":"legitimate concern","zh":"合理的关切"},{"phrase":"legitimate government","zh":"正统政府"},{"phrase":"legitimate claim","zh":"正当主张"},{"phrase":"legitimate reason","zh":"正当理由"},{"phrase":"legitimate authority","zh":"合法权威"}],"forms":[{"label":"原级","form":"legitimate"},{"label":"比较级","form":"more legitimate"},{"label":"最高级","form":"most legitimate"},{"label":"第三人称单数（动词）","form":"legitimates"},{"label":"过去式（动词）","form":"legitimated"},{"label":"过去分词（动词）","form":"legitimated"},{"label":"现在分词（动词）","form":"legitimating"},{"label":"名词（正当性）","form":"legitimacy"}],"derivatives":[{"word":"legitimacy","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「合法性；正当性」"},{"word":"legitimately","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「合法地；正当地」"},{"word":"legitimize","pos":"v.","zh":"由该形容词加表示「使成为」的动词尾构成，义为「使合法化」"},{"word":"legitimation","pos":"n.","zh":"由同族动词加表示动作结果的名词尾构成，义为「合法化；认领」"},{"word":"illegitimate","pos":"adj.","zh":"由否定前缀加该形容词构成，义为「非法的；不正当的」"}],"senses":[{"no":"01","title":"Allowed by law","titleCN":"法律允许的","definition":"permitted by the legal order of a country or institution","definitionCN":"为一个国家或机构的法律秩序所允许","example":"Only a legitimate licence allows you to trade here.","exampleCN":"只有合法执照才允许你在此经营。","why":"The Latin root is law itself, so the first sense is simply conformity with what the law permits.","whyCN":"拉丁词根就是「法律」，所以第一个义项就是与法律所允许的一致。"},{"no":"02","title":"Supported by good reason","titleCN":"理由充分的","definition":"justified by evidence or by a fair argument, even where no law is involved","definitionCN":"由证据或公平论证证明为正当，即使不涉及法律","example":"Parents have a legitimate concern about the new timetable.","exampleCN":"家长对新课表有合理的关切。","why":"Law is the model of what is acceptable, and the word extends to whatever would pass a fair test of reason.","whyCN":"法律是「可接受」的范本，这个词于是扩展到任何能通过公正理性检验的事物。"},{"no":"03","title":"Genuine and valid","titleCN":"真实有效的","definition":"of a document, claim or result that is authentic and stands up to checking","definitionCN":"指文件、主张或结果真实且经得起核查","example":"The archive held a legitimate copy of the original map.","exampleCN":"档案馆藏有一份真实有效的原图副本。","why":"A forged document is illegitimate even when no statute is named, because authenticity is a kind of law.","whyCN":"伪造文件即使不涉及具体法条也是不正当的，因为真实性本身是一种法则。"},{"no":"04","title":"Born to married parents","titleCN":"婚生的","definition":"in older legal language, of a child born within a recognized marriage","definitionCN":"旧法律用语中指在获认可的婚姻中出生的孩子","example":"The old will named only the legitimate son as heir.","exampleCN":"那份旧遗嘱只指定婚生儿子为继承人。","why":"Marriage was once the legal form that made a birth regular, so the word applied to the child as well as the union.","whyCN":"婚姻曾是使出生合乎规范的法定形式，因此这个词既用于婚姻，也用于孩子。"},{"no":"05","title":"Rightful by established authority","titleCN":"依既有权威而正统","definition":"of a ruler or government whose right to rule is accepted rather than merely seized","definitionCN":"指统治者或政府的统治权被承认，而不只是被夺取","example":"The old dynasty was still regarded as the legitimate ruler of the province.","exampleCN":"旧王朝仍被视为该省的合法统治者。","why":"Power becomes authority when it can point to a recognized line, and the word names that recognized line.","whyCN":"权力在能指向一条被承认的谱系时成为权威，而这个词命名的正是那条被承认的谱系。"},{"no":"06","title":"Of lawful business activity","titleCN":"合法经营","definition":"of trade, work or profit that is registered, taxed and open to inspection","definitionCN":"指登记、纳税并接受检查的贸易、工作或收益","example":"The family ran a legitimate shipping business for three generations.","exampleCN":"这家人合法经营航运生意达三代之久。","why":"Commerce needed a word to separate licensed trade from smuggling, and the legal sense did the work.","whyCN":"商业需要一个词把持牌贸易与走私区分开，而「合法」这一义项正好承担了这个功能。"},{"no":"07","title":"Of a fair question or worry","titleCN":"合理的疑问或担忧","definition":"of a doubt or objection that deserves an answer rather than dismissal","definitionCN":"指值得回答而不该被驳回的怀疑或反对","example":"It is legitimate to ask where the money went.","exampleCN":"追问这笔钱去了哪里是合理的。","why":"A question is legitimate when it has a right to be heard, and rights are the shadow of law behind the word.","whyCN":"一个问题在有权被听见时就是合理的，而权利正是这个词背后法律的影子。"},{"no":"08","title":"Of a government with accepted title","titleCN":"具有被承认资格的正统政府","definition":"of a regime recognized by its own people or by other states as properly constituted","definitionCN":"指被本国人民或其他国家承认其组建正当的政权","example":"Foreign offices argued over which cabinet was legitimate.","exampleCN":"各国外交部门争论哪一个内阁才是正统的。","why":"Recognition is the international form of law, and a government without it is called illegitimate even if it holds the capital.","whyCN":"承认是法律在国际层面的形式，缺少承认的政府即使占据首都也被称为不正当。"},{"no":"09","title":"Of a claim one is entitled to make","titleCN":"有权提出的正当主张","definition":"of a demand that rests on a right rather than on force or favour","definitionCN":"指依据权利而非武力或恩惠提出的要求","example":"The workers had a legitimate claim to the unpaid wages.","exampleCN":"工人们对未付工资有正当的主张权。","why":"A claim is legitimate when it can be traced to an entitlement, which is again law in miniature.","whyCN":"主张在能追溯到一项权利时就是正当的，这又是微缩的法律。"}],"etymology":{"intro":{"en":"Legitimate comes from Latin legitimatus, the past participle of legitimare, to make lawful, from legitimus, lawful, from lex, law.","cn":"这个词来自拉丁语 legitimatus，即 legitimare「使合法」的过去分词，而 legitimare 出自 legitimus「合法的」，其根为 lex「法律」。"},"items":[{"era":"LATIN LEX","en":"Lex meant law or statute, and its stem legis appears in legal, legislate and legitimacy alike.","cn":"lex 意为法律或法令，其词干 legis 同时出现在 legal、legislate 与 legitimacy 中。"},{"era":"LATIN LEGITIMUS","en":"The adjective meant lawful or according to law, and it could describe a person, a claim or a birth.","cn":"这个形容词意为合法的或依法的，可形容人、主张或出生。"},{"era":"LATIN LEGITIMARE","en":"The verb meant to make lawful or to declare lawful, used of wills, marriages and offices.","cn":"这个动词意为使合法或宣布合法，曾用于遗嘱、婚姻与职位。"},{"era":"FRENCH LEGITIME","en":"French carried the adjective to English, which kept the legal core while widening it to reason and authenticity.","cn":"法语把这个形容词带给英语，英语保留法律核心，同时把它拓宽到理性与真实性。"},{"era":"ENGLISH LEGITIMATE","en":"English used the word for lawful births and lawful rulers before it used it for fair arguments; the date of the widening is uncertain.","cn":"英语先用它讲婚生与合法统治者，之后才用它讲公正论证；这一拓宽的年代不确定。"},{"era":"MODERN EVERYDAY USE","en":"Today the word often means simply reasonable, as in a legitimate question, with the legal sense still underneath.","cn":"今天这个词常只表示「合理」，如「合理的疑问」，但法律义仍在底下。"}]},"similar":{"note":{"en":"The first group looks or sounds like legitimate; the second group names neighbouring ideas of law and fairness.","cn":"第一组在形音上与 legitimate 相近；第二组是与「法律、公正」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"legitimacy","ipa":"/lɪˈdʒɪtɪməsi/","tag":"same root","definition":"The quality of being lawful or accepted as rightful.","definitionCN":"指合法或被承认为正当的性质。"},{"word":"legitimately","ipa":"/lɪˈdʒɪtɪmətli/","tag":"same root","definition":"The adverb meaning in a lawful or justified way.","definitionCN":"指以合法或有正当理由的方式。"},{"word":"legitimize","ipa":"/lɪˈdʒɪtɪmaɪz/","tag":"same root","definition":"To make something lawful or acceptable.","definitionCN":"指使某事物合法或可接受。"},{"word":"legislate","ipa":"/ˈledʒɪsleɪt/","tag":"same root","definition":"To make laws; it shares the law root but is not formed from legitimate.","definitionCN":"指制定法律；共享法律词根，但并非由本词派生。"},{"word":"legacy","ipa":"/ˈleɡəsi/","tag":"different root","definition":"Property left by will; it looks close but comes from a word for a commission or bequest.","definitionCN":"指遗嘱留下的财产；形近，但来自意为「委托、遗赠」的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"lawful","ipa":"/ˈlɔːfl/","tag":"near meaning","definition":"Permitted by statute, the plainest member of the group.","definitionCN":"指为成文法所允许，是这组词中最朴素的。"},{"word":"legal","ipa":"/ˈliːɡl/","tag":"near meaning","definition":"Relating to law or allowed by it, often used of procedures.","definitionCN":"指与法律有关或为法律所允许，常指程序。"},{"word":"valid","ipa":"/ˈvælɪd/","tag":"near meaning","definition":"Officially acceptable because the required conditions are met.","definitionCN":"指因满足所需条件而获正式接受。"},{"word":"justified","ipa":"/ˈdʒʌstɪfaɪd/","tag":"near meaning","definition":"Shown to have a good reason behind it.","definitionCN":"指被证明背后有充分理由。"},{"word":"rightful","ipa":"/ˈraɪtfl/","tag":"near meaning","definition":"Holding a position or property by proper title.","definitionCN":"指凭正当名分持有职位或财产。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the law root, the three layers of the word and the phrases that keep them apart.","cn":"正常联想利用「法律」词根、这个词的三层意思，以及区分这三层的搭配。"},"normal":[{"en":"The root is lex, law, so legitimate starts from what the law allows and then widens to what reason allows.","cn":"词根意为「法律」，所以这个词从「法律允许」出发，再扩展到「理性允许」。"},{"en":"Legislate and legal share the root but are different words, not derivatives of legitimate.","cn":"表示「立法」与「法律的」同族词共享词根，却是另外的词，不是本词的派生词。"},{"en":"A legitimate licence is lawful, a legitimate question is reasonable, a legitimate king is rightful.","cn":"合法的执照、合理的疑问、正统的国王，三层意思各自清楚。"},{"en":"The noun legitimacy is the abstract form used in politics and in arguments about proof.","cn":"名词形式是用于政治与证据争论的抽象说法。"},{"en":"Illegitimate simply adds the negative prefix and denies all three layers at once.","cn":"否定形式只是加上否定前缀，一次否定三层意思。"}],"abstract":[{"en":"Legitimacy is the story power tells about why it should be obeyed.","cn":"正当性是权力讲述的、关于自己为何该被服从的故事。"},{"en":"The word quietly moves from statutes to feelings, because people want their worries to have standing.","cn":"这个词悄悄从法条移到感受，因为人希望自己的担忧拥有地位。"},{"en":"To call something legitimate is to say it has a right to exist, not merely a permission.","cn":"称某事正当，是说它有存在的权利，而不只是有许可。"}]},"examples":[{"en":"The commission asked whether the election had produced a legitimate government.","cn":"委员会询问这场选举是否产生了正统政府。"},{"en":"There is a legitimate reason to delay the launch until the tests finish.","cn":"把发布推迟到测试结束是有正当理由的。"},{"en":"Only legitimate copies carry the printer's mark on the last page.","cn":"只有正版副本的末页才带印刷商标记。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「利己提马特」——凡事「利己」又「提」得出「马」上能查的凭据，才算合法正当","word":"legitimate"},"root":"拉丁语 legitimatus（legitimare「使合法」的过去分词）← legitimus「合法的」← lex, legis「法律」。同根有 legal、legislate、legitimacy；legacy 形近但来自「遗赠」义，不同源。三层义（合法、合理、正统）由法律义向外扩展；扩展年代不确定。","sensesIntro":{"en":"Nine senses arrange three layers: law (licence, business, birth), reason (concern, question, claim) and recognized title (ruler, government, authentic document).","cn":"九个义项排成三层：法律（执照、经营、婚生）、理性（关切、疑问、主张）与被承认的名分（统治者、政府、真实文件）。"},"semanticMap":{"core":{"en":"CORE IMAGE: a clerk checking a licence line by line against the register.","cn":"核心意象：办事员把执照逐条对照登记册。"},"chain":["ACCORDING TO LAW","PERMITTED ACTIVITY","ACCEPTED BIRTH","RECOGNIZED TITLE","FAIR REASON","AUTHENTIC PROOF"],"branches":[{"senses":"01 · 06","en":"THE LICENSED BRANCH: what the statute allows and the trade that is registered and taxed.","cn":"持牌分支：成文法允许之事，以及登记纳税的经营。"},{"senses":"02 · 07","en":"THE REASONABLE BRANCH: a fair worry and a question that deserves an answer.","cn":"合理分支：公平的担忧，以及值得回答的疑问。"},{"senses":"03 · 09","en":"THE PROOF BRANCH: an authentic copy and a claim backed by an entitlement.","cn":"凭据分支：真实副本，以及有权利支撑的主张。"},{"senses":"04","en":"THE BIRTH BRANCH: the old legal sense of a child born within marriage.","cn":"出生分支：婚内所生子女的旧法律义。"},{"senses":"05 · 08","en":"THE TITLE BRANCH: a ruler and a cabinet whose right to rule is recognized.","cn":"名分分支：统治权被承认的君主与内阁。"}]},"affixes":{"intro":{"en":"Legitimate is a Latin law word that English widened from statutes to reason, with a productive family on both sides.","cn":"这是一个拉丁法律词，英语把它从法条拓宽到理性，两侧都有一族能产的派生词。"},"latinIntro":{"en":"Latin lex and its stem legis supply the root; legitimus, legitimare and legitimatus supply the forms English borrowed or imitated.","cn":"拉丁语 lex 及其词干 legis 提供词根；legitimus、legitimare 与 legitimatus 提供英语借用或仿造的形式。"},"items":[{"word":"lex","structure":"Latin noun, third declension","meaning":"law, statute","meaningCN":"法律；法令","example":"The root is short but stands under a large family.","exampleCN":"这个词根很短，却支撑着一大族词。"},{"word":"legis","structure":"genitive stem of lex","meaning":"of law","meaningCN":"法律的","example":"The stem appears in legal and legislate.","exampleCN":"这个词干出现在表示「法律的」与「立法」的同族词中。"},{"word":"legitimus","structure":"adjective from lex","meaning":"lawful, according to law","meaningCN":"合法的；依法的","example":"It could describe a person or a claim.","exampleCN":"它可形容人或主张。"},{"word":"legitimare","structure":"verb from legitimus","meaning":"to make lawful","meaningCN":"使合法","example":"Wills and marriages were its objects.","exampleCN":"遗嘱与婚姻曾是它的对象。"},{"word":"legitimatus","structure":"past participle of legitimare","meaning":"made lawful","meaningCN":"已使合法的","example":"The participle is the direct source of the English adjective.","exampleCN":"这个分词是英语形容词的直接来源。"},{"word":"-ate","structure":"Latin adjective and verb ending","meaning":"having or making","meaningCN":"具有……或使成为……","example":"It lets the same form serve as adjective and verb.","exampleCN":"它让同一形式兼作形容词与动词。"},{"word":"-acy","structure":"Latin noun ending through French","meaning":"state or quality","meaningCN":"状态或性质","example":"It builds legitimacy.","exampleCN":"它构成表示「合法性」的名词。"},{"word":"il-","structure":"assimilated negative prefix","meaning":"not","meaningCN":"不；非","example":"It builds illegitimate.","exampleCN":"它构成表示「非法的」的否定形容词。"},{"word":"-ize","structure":"verb ending","meaning":"to make","meaningCN":"使成为","example":"It builds legitimize.","exampleCN":"它构成表示「使合法化」的动词。"}],"latinEntries":[{"word":"lex","structure":"lex, legis (f., third declension)","meaning":"law, statute","meaningCN":"法律；法令"},{"word":"legitimus","structure":"legitimus, legitima, legitimum (adjective)","meaning":"lawful, legitimate","meaningCN":"合法的；正当的"},{"word":"legitimare","structure":"legitimo, legitimavi, legitimatum (verb, first conjugation)","meaning":"to make lawful","meaningCN":"使合法"},{"word":"legitimatus","structure":"past participle of legitimare","meaning":"made lawful","meaningCN":"已使合法的"}],"derivatives":[{"word":"legitimacy","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「合法性；正当性」"},{"word":"legitimately","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「合法地；正当地」"},{"word":"legitimize","pos":"v.","zh":"由该形容词加表示「使成为」的动词尾构成，义为「使合法化」"},{"word":"legitimation","pos":"n.","zh":"由同族动词加表示动作结果的名词尾构成，义为「合法化；认领」"},{"word":"illegitimate","pos":"adj.","zh":"由否定前缀加该形容词构成，义为「非法的；不正当的」"}]}},{"word":"redundant","ipa_uk":"/rɪˈdʌndənt/","ipa_us":"/rɪˈdʌndənt/","definition_zh":"多余的；冗余的；冗余备份的；被裁员的；赘余的","definition_en":"beyond what is needed, kept as a spare, repeated without adding meaning, or no longer employed because the job has gone","core_image":"机房里两排服务器同时运行，一排出故障，另一排立刻接手，指示灯始终亮着","scene":"机房里两排服务器同时运行，一排出故障，另一排立刻接手，指示灯始终亮着。The second array is redundant, so a single failure cannot stop the service.","sceneCN":"这里指作为冗余备份而存在的（第 2 个义项：冗余备份的）；句意为第二组阵列是冗余配置，因此单点故障无法让服务停止。","pos":[{"tag":"adj.","zh":"多余的；冗余的；冗余备份的；被裁员的；赘余的"}],"collocations":[{"phrase":"redundant information","zh":"冗余信息"},{"phrase":"redundant system","zh":"冗余系统"},{"phrase":"redundant staff","zh":"冗员"},{"phrase":"made redundant","zh":"被裁员"},{"phrase":"redundant capacity","zh":"过剩产能"},{"phrase":"redundant wording","zh":"啰嗦重复的措辞"}],"forms":[{"label":"原级","form":"redundant"},{"label":"比较级","form":"more redundant"},{"label":"最高级","form":"most redundant"},{"label":"名词（冗余）","form":"redundancy"},{"label":"副词","form":"redundantly"}],"derivatives":[{"word":"redundancy","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「冗余；裁员」"},{"word":"redundantly","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「多余地；冗余地」"},{"word":"redundance","pos":"n.","zh":"与常用名词形式同义的另一名词形式，使用频率较低"}],"senses":[{"no":"01","title":"More than is needed","titleCN":"超出所需","definition":"present in a quantity greater than the purpose requires","definitionCN":"存在的数量超过用途所需","example":"The report repeats the same figure in three redundant tables.","exampleCN":"报告用三张多余的表重复同一个数字。","why":"The Latin verb meant to overflow, and anything that spills past its container is naturally called more than needed.","whyCN":"拉丁动词意为「溢出」，任何漫出容器的东西自然被称为超出所需。"},{"no":"02","title":"Duplicated as a safety backup","titleCN":"作为安全备份的冗余","definition":"in engineering, of a second component kept so that failure of the first does not stop the system","definitionCN":"工程中指保留的第二套部件，使第一套失效时系统仍能运行","example":"The aircraft carries redundant hydraulic lines on each wing.","exampleCN":"这架飞机在每个机翼上都装有冗余液压管路。","why":"Here the overflow is deliberate: the extra copy is not waste but insurance against failure.","whyCN":"这里的「溢出」是刻意的：多出的副本不是浪费，而是对失效的保险。"},{"no":"03","title":"Dismissed because the job is no longer needed","titleCN":"因岗位不再需要而被裁员","definition":"in British employment language, of a worker whose position has been abolished","definitionCN":"英式就业用语中指岗位被撤销的工人","example":"Two hundred workers were made redundant when the plant closed.","exampleCN":"工厂关闭时，两百名工人被裁员。","why":"The worker is not at fault; the post itself has become an extra part of the company, so the word moves from things to people.","whyCN":"工人本身没有过错；是岗位变成了公司里多余的一部分，于是这个词从物移到人。"},{"no":"04","title":"Repeated without adding meaning","titleCN":"语言上的赘余重复","definition":"in language, of a word or construction that repeats information already carried elsewhere","definitionCN":"语言中指重复别处已承载信息的词或结构","example":"The phrase free gift is redundant because a gift is already free.","exampleCN":"免费礼物这个说法是赘余的，因为礼物本就免费。","why":"Speech also has a container, and words that spill past the meaning are overflow in the same sense.","whyCN":"言语也有容器，漫出意义的词就是同一意义上的溢出。"},{"no":"05","title":"Of duplicated data","titleCN":"重复冗余的数据","definition":"of data stored or transmitted more than once, either for safety or by poor design","definitionCN":"指被重复存储或传输的数据，或为安全，或源于设计不佳","example":"Compression removes redundant data before the file is sent.","exampleCN":"文件发送前，压缩会去掉冗余数据。","why":"Digital storage made overflow countable, so the word became a technical measure of repeated bits.","whyCN":"数字存储让「溢出」变得可计数，于是这个词成为重复比特的技术量度。"},{"no":"06","title":"Of surplus workers","titleCN":"冗员","definition":"of employees whose number exceeds the work available","definitionCN":"指人数超过现有工作量的雇员","example":"The review found the department heavily redundant.","exampleCN":"审查发现该部门冗员严重。","why":"A workforce has a needed size, and the part beyond that size is the overflow made of people.","whyCN":"劳动力有一个需要的规模，超出这个规模的部分就是由人构成的溢出。"},{"no":"07","title":"Of a duplicated system","titleCN":"冗余系统","definition":"of equipment or software installed in pairs so that one copy can take over","definitionCN":"指成对安装的设备或软件，使一份可以接替另一份","example":"A redundant power supply kept the servers running through the outage.","exampleCN":"冗余电源让服务器在停电期间继续运行。","why":"Redundancy in engineering is a promise that no single failure is final, and the word carries that promise.","whyCN":"工程中的冗余是一个承诺：没有任何单点故障是终结性的，而这个词承载着这个承诺。"},{"no":"08","title":"Of wordy repetition","titleCN":"啰嗦重复的措辞","definition":"of writing that uses more words than the idea requires","definitionCN":"指用词多于意思所需的写作","example":"Editors cut the redundant clauses and the letter fitted one page.","exampleCN":"编辑删去赘余的从句，信就装进了一页。","why":"Style guides borrowed the engineering word because both deal with parts that could be removed without loss.","whyCN":"文体指南借用了工程上的词，因为两者都涉及可以去掉而无损失的部分。"},{"no":"09","title":"Of excess capacity","titleCN":"过剩产能","definition":"of productive capacity that stands idle because demand is lower","definitionCN":"指因需求较低而闲置的生产能力","example":"The industry carried redundant capacity for a decade.","exampleCN":"该行业保有过多产能达十年之久。","why":"Machines that could work but are not needed are overflow in the industrial sense of the word.","whyCN":"能运转却无人需要的机器，正是这个词工业意义上的溢出。"}],"etymology":{"intro":{"en":"Redundant comes from the Latin present participle redundans, from redundare, to overflow, built from re(d)-, again or back, and undare, to surge, from unda, a wave.","cn":"这个词来自拉丁语现在分词 redundans，出自 redundare「溢出」，由 re(d)-「再、回」与 undare「涌流」构成，而 undare 又出自 unda「波浪」。"},"items":[{"era":"LATIN UNDA","en":"Unda meant a wave, and it also stands behind undulate and inundate.","cn":"unda 意为波浪，它也是 undulate 与 inundate 的词根。"},{"era":"LATIN UNDARE","en":"The verb meant to surge or to flow in waves, used of rivers and of blood.","cn":"这个动词意为涌起或以波浪流动，曾用于河流与血液。"},{"era":"LATIN REDUNDARE","en":"The compound meant to overflow or to be in excess, literally to flow back over the brim.","cn":"这个复合词意为溢出、过剩，字面上是「水漫过边缘流回」。"},{"era":"LATIN REDUNDANS","en":"The participle described water or speech that spills beyond its proper limit.","cn":"这个分词描述漫出应有界限的水或言语。"},{"era":"ENGLISH REDUNDANT","en":"English adopted the adjective for excess in speech and then in law and employment; the earlier uses date from the sixteenth century, later ones are uncertain.","cn":"英语先用这个形容词讲言语的过剩，再用到法律与就业；较早用法始于十六世纪，较晚用法的年代不确定。"},{"era":"BRITISH EMPLOYMENT SENSE","en":"British industrial language turned the word into a polite term for dismissal, a usage of the twentieth century whose first date is uncertain.","cn":"英国工业用语把这个词变成对解雇的委婉说法，这是二十世纪的用法，首见年代不确定。"}]},"similar":{"note":{"en":"The first group looks or sounds like redundant; the second group names neighbouring ideas of excess and spares.","cn":"第一组在形音上与 redundant 相近；第二组是与「多余、备份」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"redundancy","ipa":"/rɪˈdʌndənsi/","tag":"same root","definition":"The noun for excess, for a backup, or for a dismissal.","definitionCN":"指多余、备份或裁员的名词。"},{"word":"redundantly","ipa":"/rɪˈdʌndəntli/","tag":"same root","definition":"The adverb meaning in a way that repeats what is already there.","definitionCN":"指以重复已有内容的方式。"},{"word":"redundance","ipa":"/rɪˈdʌndəns/","tag":"same root","definition":"A rarer noun form with the same meaning as redundancy.","definitionCN":"与常用名词形式同义但较少用的另一形式。"},{"word":"abundant","ipa":"/əˈbʌndənt/","tag":"different root","definition":"Present in large quantities; it shares the wave image but its prefix means away from.","definitionCN":"指大量存在；共享波浪意象，但前缀意为「离开」。"},{"word":"redundant","ipa":"/rɪˈdʌndənt/","tag":"same root","definition":"The headword itself, used here to contrast the family forms.","definitionCN":"本词条本身，此处用于对照同族形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"superfluous","ipa":"/suːˈpɜːfluəs/","tag":"near meaning","definition":"More than enough, often with a hint of waste.","definitionCN":"指多到超出所需，常带浪费意味。"},{"word":"surplus","ipa":"/ˈsɜːpləs/","tag":"near meaning","definition":"The amount left over after needs are met.","definitionCN":"指满足需求后剩下的量。"},{"word":"spare","ipa":"/speə/","tag":"near meaning","definition":"An extra copy kept ready in case the first fails.","definitionCN":"指为防第一件失效而备好的额外副本。"},{"word":"excess","ipa":"/ɪkˈses/","tag":"near meaning","definition":"An amount beyond a stated or permitted limit.","definitionCN":"指超过规定或允许限度的量。"},{"word":"pleonastic","ipa":"/ˌpliːəˈnæstɪk/","tag":"near meaning","definition":"Of wording that uses more words than the meaning needs.","definitionCN":"指措辞用词多于意思所需。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the overflowing-wave image, the three modern lines and the phrases that keep them apart.","cn":"正常联想利用「波浪溢出」的意象、三条现代义线，以及区分它们的搭配。"},"normal":[{"en":"The root is a wave, so think of water spilling over the rim of a full basin.","cn":"词根是波浪，所以想象水从满盆的边缘漫出来。"},{"en":"Redundant information is waste, a redundant system is insurance, and a redundant worker is a post that disappeared.","cn":"冗余信息是浪费，冗余系统是保险，而被裁员的工人是岗位消失了。"},{"en":"In British English made redundant is the standard polite phrase for lost a job.","cn":"在英式英语里，被列为「多余」是「失去工作」的标准委婉说法。"},{"en":"The noun redundancy covers all three lines, which is why context decides the meaning.","cn":"名词形式覆盖三条义线，所以靠上下文决定意思。"},{"en":"Engineers say redundancy with pride, while editors say redundant as criticism.","cn":"工程师带着自豪说冗余，编辑却带着批评说赘余。"}],"abstract":[{"en":"Redundancy is the only kind of waste that can save a system.","cn":"冗余是唯一能拯救系统的浪费。"},{"en":"A word for overflow became a word for people, which shows how economic language borrows from water.","cn":"一个表示溢出的词变成了指人的词，这说明经济语言如何向水借词。"},{"en":"What is extra depends entirely on what the container was built to hold.","cn":"什么算多余，完全取决于这个容器本来要装多少。"}]},"examples":[{"en":"The editor removed every redundant sentence from the draft.","cn":"编辑删去了草稿中每一个赘余的句子。"},{"en":"The network uses redundant links so that one cut cannot isolate the town.","cn":"这个网络使用冗余链路，使一处断线无法孤立该镇。"},{"en":"Half the workshop was made redundant after the order was cancelled.","cn":"订单取消后，车间一半的人被裁员。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「瑞丹登特」——「瑞」气装满还往「登」着加，装不下的都成了多余：冗余的","word":"redundant"},"root":"拉丁语 redundans（redundare 的现在分词）← re(d)-「再、回」+ undare「涌流」← unda「波浪」。同族有 undulate、inundate；abundant 共享波浪意象但前缀不同。三条现代义线（多余、备份、裁员）均由「溢出」引申，其中裁员义为二十世纪英式用法，首见年代不确定。","sensesIntro":{"en":"Nine senses follow the overflow image into three lines: surplus things and words, deliberate technical backups, and people or capacity left beyond need.","cn":"九个义项沿「溢出」意象分成三条线：多余的事物与言语、刻意设置的技术备份，以及超出需要的人与产能。"},"semanticMap":{"core":{"en":"CORE IMAGE: a full basin with water running over its rim.","cn":"核心意象：装满的盆，水从边缘漫出。"},"chain":["FLOW OVER THE RIM","MORE THAN NEEDED","REPEATED WITHOUT GAIN","KEPT ON PURPOSE","THE JOB DISAPPEARS","CAPACITY LEFT IDLE"],"branches":[{"senses":"01 · 08","en":"THE SURPLUS BRANCH: too many things and too many words for the same meaning.","cn":"过剩分支：物太多，词也太多而意思不变。"},{"senses":"02 · 07","en":"THE DELIBERATE BACKUP BRANCH: duplicate parts kept so that one failure is not final.","cn":"刻意备份分支：保留重复部件，使单次失效不成为终结。"},{"senses":"03 · 06","en":"THE WORKFORCE BRANCH: the post abolished and the workers beyond the needed number.","cn":"劳动力分支：被撤销的岗位，以及超出所需人数的工人。"},{"senses":"04 · 05","en":"THE LANGUAGE AND DATA BRANCH: repetition in speech and duplicated bits in storage.","cn":"语言与数据分支：言语中的重复，以及存储中重复的比特。"},{"senses":"09","en":"THE IDLE CAPACITY BRANCH: machines able to work but without demand.","cn":"闲置产能分支：能运转却无需求的机器。"}]},"affixes":{"intro":{"en":"Redundant is a Latin participle of overflowing, and English extended it from water to speech, machines and employment.","cn":"这是一个表示「溢出」的拉丁语分词，英语把它从水扩展到言语、机器与就业。"},"latinIntro":{"en":"Latin re(d)- and unda with its verb undare build redundare, whose participle redundans is the direct source.","cn":"拉丁语 re(d)- 与 unda 及其动词 undare 构成 redundare，其分词 redundans 是直接来源。"},"items":[{"word":"re-","structure":"Latin prefix","meaning":"again, back","meaningCN":"再次；向后","example":"The prefix marks water flowing back over the edge.","exampleCN":"这个前缀标出水从边缘流回。"},{"word":"unda","structure":"Latin noun, first declension","meaning":"wave","meaningCN":"波浪","example":"The noun is the image under the whole family.","exampleCN":"这个名词是整族词底下的意象。"},{"word":"undare","structure":"verb from unda","meaning":"to surge, flow in waves","meaningCN":"涌起；波浪般流动","example":"It supplied the moving water in the compound.","exampleCN":"它为复合词提供了流动的水。"},{"word":"redundare","structure":"re- plus undare","meaning":"to overflow, be in excess","meaningCN":"溢出；过剩","example":"The verb is the source of the English family.","exampleCN":"这个动词是英语词族的来源。"},{"word":"redundans","structure":"present participle of redundare","meaning":"overflowing","meaningCN":"正在溢出的","example":"The participle became the English adjective.","exampleCN":"这个分词变成了英语形容词。"},{"word":"-ant","structure":"Latin participle ending","meaning":"being in a state","meaningCN":"处于某种状态","example":"The ending marks the adjective.","exampleCN":"这个词尾标出形容词。"},{"word":"-ancy","structure":"Latin noun ending through French","meaning":"state or quality","meaningCN":"状态或性质","example":"It builds redundancy.","exampleCN":"它构成表示「冗余」的名词。"},{"word":"-ly","structure":"English adverb ending","meaning":"in a ... manner","meaningCN":"以……方式","example":"It builds redundantly.","exampleCN":"它构成表示「多余地」的副词。"}],"latinEntries":[{"word":"unda","structure":"unda, undae (f., first declension)","meaning":"wave","meaningCN":"波浪"},{"word":"undare","structure":"undo, undavi, undatum (verb, first conjugation)","meaning":"to surge, overflow","meaningCN":"涌起；溢出"},{"word":"redundare","structure":"re- plus undare (verb, first conjugation)","meaning":"to overflow, abound","meaningCN":"溢出；充盈"},{"word":"redundantia","structure":"noun from redundare","meaning":"overflow, excess","meaningCN":"溢出；过剩"}],"derivatives":[{"word":"redundancy","pos":"n.","zh":"由该形容词加表示性质的名词尾构成，义为「冗余；裁员」"},{"word":"redundantly","pos":"adv.","zh":"由该形容词加表示方式的副词尾构成，义为「多余地；冗余地」"},{"word":"redundance","pos":"n.","zh":"与常用名词形式同义的另一名词形式，使用频率较低"}]}},{"word":"stabilize","ipa_uk":"/ˈsteɪbəlaɪz/","ipa_us":"/ˈsteɪbəlaɪz/","definition_zh":"使稳定；使稳固；稳定下来；使（价格、病情）趋于平稳","definition_en":"to make something steady or keep it from changing, and also to become steady without outside help","core_image":"拍摄现场，一只手扶住晃动的三脚架，另一只手把最后一个旋钮拧紧，取景框里的画面终于不再抖","scene":"拍摄现场，一只手扶住晃动的三脚架，另一只手把最后一个旋钮拧紧，取景框里的画面终于不再抖。A heavy base helped stabilize the tower before the storm arrived.","sceneCN":"这里指使实物稳固、不再晃动（第 1 个义项：使物体保持稳定）；句意为在暴风雨到来之前，一个沉重的底座帮助把塔架稳定住。","pos":[{"tag":"v.","zh":"使稳定；使稳固；稳定下来；使趋于平稳"}],"collocations":[{"phrase":"stabilize the economy","zh":"稳定经济"},{"phrase":"stabilize prices","zh":"稳定物价"},{"phrase":"stabilize the patient","zh":"使病人病情稳定"},{"phrase":"stabilize a currency","zh":"稳住货币"},{"phrase":"stabilize the situation","zh":"稳定局势"},{"phrase":"stabilize a compound","zh":"使化合物稳定"}],"forms":[{"label":"原形","form":"stabilize"},{"label":"三单","form":"stabilizes"},{"label":"过去式","form":"stabilized"},{"label":"过去分词","form":"stabilized"},{"label":"现在分词","form":"stabilizing"},{"label":"名词（稳定化）","form":"stabilization"}],"derivatives":[{"word":"stabilization","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「稳定化；稳定过程」"},{"word":"stabilizer","pos":"n.","zh":"由该动词加表示施动者或器具的名词尾构成，义为「稳定器；安定剂」"},{"word":"stabilized","pos":"adj.","zh":"由该动词的过去分词转成的形容词，义为「已稳定的」"},{"word":"stabilizing","pos":"adj.","zh":"由该动词的现在分词转成的形容词，义为「起稳定作用的」"}],"senses":[{"no":"01","title":"Make an object steady in place","titleCN":"使物体稳固不晃","definition":"to fix something physically so that it no longer rocks, shifts or falls","definitionCN":"从物理上固定某物，使它不再摇晃、移动或倒下","example":"Steel props were used to stabilize the wall.","exampleCN":"人们用钢支撑把那段墙稳住。","why":"The word is built on an adjective meaning able to stand, so the first job it does is keep a thing standing.","whyCN":"这个词建立在「能够站立」的形容词之上，所以它的第一件工作就是让东西立住。"},{"no":"02","title":"Keep a quantity at a fixed level","titleCN":"使数值保持恒定","definition":"to hold temperature, pressure or another measurable quantity near one value","definitionCN":"把温度、压力或其他可测量的量维持在某一数值附近","example":"A thermostat helps stabilize the temperature inside the room.","exampleCN":"恒温器有助于把室内温度保持稳定。","why":"A quantity that does not drift is steady in the same sense as a table that does not wobble.","whyCN":"一个不漂移的数值，和一张不晃的桌子，是同一个意义上的「稳」。"},{"no":"03","title":"Calm a situation or relationship","titleCN":"使局势或关系缓和","definition":"to keep a conflict, market mood or negotiation from breaking apart","definitionCN":"使冲突、市场情绪或谈判不至于崩散","example":"The mediator tried to stabilize the talks after the quarrel.","exampleCN":"争吵之后，调解人试图让谈判重新稳定下来。","why":"Human affairs also wobble, and the same word is used for the hand that keeps them from tipping over.","whyCN":"人间事务也会摇晃，同一个词也用来形容那只不让局面倾覆的手。"},{"no":"04","title":"Steady a patient's condition","titleCN":"使病人病情稳定","definition":"in medicine, to bring vital signs under control so that the patient is no longer in immediate danger","definitionCN":"医学上指把生命体征控制住，使病人脱离即刻危险","example":"Doctors worked all night to stabilize the patient.","exampleCN":"医生们整夜工作，使病人的情况稳定下来。","why":"A body in crisis is described as unstable, so the verb naturally names the work of bringing it back to a steady state.","whyCN":"危急中的身体被称为「不稳定」，于是这个动词自然用来指把它带回稳定状态的工作。"},{"no":"05","title":"Become steady by itself","titleCN":"自行稳定下来","definition":"of a thing or condition that settles without anyone acting on it","definitionCN":"指事物或状况无需他人作用便自行安定","example":"The plane's altitude began to stabilize after the turbulence.","exampleCN":"颠簸之后，飞机的高度开始稳定下来。","why":"This is the intransitive use, where the subject is the thing that settles rather than the hand that settles it.","whyCN":"这是不及物用法，主语是安定下来的事物，而不是使它安定的那只手。"},{"no":"06","title":"Keep a chemical substance from changing","titleCN":"使化学物质不易变质","definition":"to prevent a compound, mixture or material from decomposing or reacting further","definitionCN":"防止化合物、混合物或材料分解或继续反应","example":"A little acid was added to stabilize the solution.","exampleCN":"加入少量酸以使溶液保持稳定。","why":"Chemistry borrowed the everyday word because a substance that does not break down is steady in the most literal way.","whyCN":"化学借用了这个日常词，因为不分解的物质正是最字面意义上的「稳」。"},{"no":"07","title":"Hold a currency or market firm","titleCN":"稳住货币或市场","definition":"of a government or bank, to stop a currency or market from swinging sharply","definitionCN":"指政府或银行阻止货币或市场剧烈波动","example":"The central bank moved to stabilize the currency.","exampleCN":"中央银行采取行动稳住货币。","why":"Money is measured like temperature, and a rate that stops swinging is called stable in every financial report.","whyCN":"货币像温度一样被计量，而止住摆动的汇率在每份金融报告里都被称为稳定。"},{"no":"08","title":"Restore the balance of a craft","titleCN":"使飞行器或船只恢复平衡","definition":"of a pilot or helmsman, to bring an aircraft or vessel back to level flight or an even keel","definitionCN":"指飞行员或舵手使飞行器或船只恢复水平飞行或平稳航行","example":"The pilot had to stabilize the aircraft in the crosswind.","exampleCN":"飞行员必须在侧风中把飞机稳住。","why":"A craft out of balance is unstable, and the verb describes the correction that returns it to level.","whyCN":"失去平衡的飞行器是不稳定的，而这个动词描述的正是把它带回水平的那一修正。"},{"no":"09","title":"Bring a natural system toward balance","titleCN":"使自然系统趋于平衡","definition":"of an ecosystem or climate, to reduce swings so that the system stays within a workable range","definitionCN":"指生态系统或气候，减少波动使系统停留在可运转的范围内","example":"Wetland restoration can help stabilize the local climate.","exampleCN":"湿地修复有助于使当地气候趋于稳定。","why":"The largest systems are described with the smallest image: a hand steadying something that would otherwise sway.","whyCN":"最大的系统用最小的意象来描述：一只手稳住本来会摇摆的东西。"}],"etymology":{"intro":{"en":"Stabilize is an English verb formed from stable plus the verb ending -ize. Stable came through French from Latin stabilis, able to stand, which rests on stare, to stand.","cn":"这个词是英语在 stable 之上加动词词尾构成的，而 stable 经法语来自拉丁语 stabilis「能够站立的」，其底层是 stare「站立」。"},"items":[{"era":"LATIN STARE","en":"Stare meant to stand or remain in place, and it is the ground under a large family of standing words.","cn":"stare 意为站立或留在原处，是一大批表示「站立」的词的根基。"},{"era":"LATIN STABILIS","en":"The adjective meant firm or able to stand, used of posts, positions and later of character.","cn":"这个形容词意为牢固的、能站住的，先用于柱子与位置，后来也用于性格。"},{"era":"FRENCH ESTABLE","en":"Old French carried the adjective to English, where it named buildings for animals before it named anything else.","cn":"古法语把这个形容词带进英语，它在那里最先指关牲口的棚舍。"},{"era":"ENGLISH STABLE","en":"The English adjective added the sense of enduring and free from sudden change.","cn":"英语中的形容词义增加了「持久、不易突变」的意思。"},{"era":"ENGLISH STABILIZE","en":"The verb appeared in the nineteenth century, first in technical writing about ships and machines; the exact first date is uncertain.","cn":"这个动词在十九世纪出现，最早见于关于船只与机器的技术写作；确切首见年代不确定。"},{"era":"MODERN GENERAL USE","en":"Medicine, finance and climate science each took the verb and gave it a specialised object.","cn":"医学、金融与气候科学各自取用这个动词，并给它配上专门的对象。"}]},"similar":{"note":{"en":"The first group looks or sounds like stabilize; the second group names neighbouring ideas of steadiness.","cn":"第一组在形音上与 stabilize 相近；第二组是与「稳、安定」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stable","ipa":"/ˈsteɪbl/","tag":"same root","definition":"Firm and not likely to move or change; the adjective behind the verb.","definitionCN":"指牢固、不易移动或改变的，是本词背后的形容词。"},{"word":"stability","ipa":"/stəˈbɪləti/","tag":"same root","definition":"The state of being steady and unlikely to change.","definitionCN":"指稳定、不易改变的状态。"},{"word":"stabilizer","ipa":"/ˈsteɪbəlaɪzə/","tag":"same root","definition":"A device or substance that keeps something steady.","definitionCN":"指使某物保持稳定的装置或物质。"},{"word":"stabilization","ipa":"/ˌsteɪbəlaɪˈzeɪʃn/","tag":"same root","definition":"The act of making something steady or keeping it at a level.","definitionCN":"指使某物稳定或使其保持在一定水平的行为。"},{"word":"unstable","ipa":"/ʌnˈsteɪbl/","tag":"different formation","definition":"Not steady and likely to change or fall; it negates the adjective rather than deriving from the verb.","definitionCN":"指不稳定、容易变化或倒塌的；它否定的是形容词，而不是从动词派生。"}]},{"heading":"NEAR MEANING","entries":[{"word":"steady","ipa":"/ˈstedi/","tag":"near meaning","definition":"To make something stop shaking, often by holding it; it stresses the motion that stops.","definitionCN":"指使某物不再晃动，常含用手扶住之意；它强调停止的那个动作。"},{"word":"balance","ipa":"/ˈbæləns/","tag":"near meaning","definition":"To keep something from falling to one side, stressing equal weight rather than freedom from change.","definitionCN":"指使某物不向一侧倾倒，强调重量均衡而非不变。"},{"word":"secure","ipa":"/sɪˈkjʊə/","tag":"near meaning","definition":"To fasten something so that it cannot be moved or taken, stressing attachment.","definitionCN":"指把某物固定住使其无法移动或被拿走，强调固定连接。"},{"word":"settle","ipa":"/ˈsetl/","tag":"near meaning","definition":"To come to rest after movement, often without outside help; close to the intransitive sense.","definitionCN":"指运动之后静止下来，常无需外力；接近本词的不及物义项。"},{"word":"firm","ipa":"/fɜːm/","tag":"near meaning","definition":"To make something solid or fixed, stressing resistance to pressure.","definitionCN":"指使某物坚实或固定，强调抗压能力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the standing root, the adjective behind the verb and the many fields that borrowed it.","cn":"正常联想利用「站立」的词根、动词背后的形容词，以及借用过它的众多领域。"},"normal":[{"en":"The root means to stand, so to stabilize is to help something keep standing.","cn":"词根意为站立，所以「使稳定」就是帮某物一直站住。"},{"en":"A table with one short leg wobbles; a folded paper under that leg stabilizes it.","cn":"桌子有一条短腿就会晃，在腿下垫一张折好的纸就把它稳住了。"},{"en":"A stabilizer bar on a car does the same job as the outrigger on a boat.","cn":"汽车上的稳定杆，和船上的舷外浮架做的是同一件事。"},{"en":"Doctors say a patient is stable when the numbers stop swinging, which is the medical face of the word.","cn":"医生说病人情况稳定，是指各项数值不再大幅摆动，这就是这个词的医学面孔。"},{"en":"The word is transitive or intransitive: a hand stabilizes a ladder, and a ladder stabilizes by itself.","cn":"这个词既可及物也可不及物：一只手稳住梯子，梯子也会自行稳定下来。"}],"abstract":[{"en":"To stabilize is not to freeze; it is to keep change small enough to live with.","cn":"使稳定并不是使冻结，而是把变化控制到可以共处的程度。"},{"en":"Every stabilizing act chooses which movements matter and which can be ignored.","cn":"每一次稳定动作都在选择哪些晃动要紧、哪些可以不管。"},{"en":"A system is called stable when it can absorb a push and still return to its shape.","cn":"一个系统被称为稳定，是因为它能吸收一次推挤之后仍回到原来的形状。"}]},"examples":[{"en":"The crew used ropes to stabilize the mast in the wind.","cn":"船员用绳索在风中把桅杆稳住。"},{"en":"The government cut spending to stabilize the currency.","cn":"政府削减开支以稳住货币。"},{"en":"Her pulse began to stabilize after the second dose.","cn":"第二剂药之后，她的脉搏开始稳定下来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「斯泰波赖兹」——「斯泰」像「死抬」，四个人死抬一张桌子，桌子就稳了：使稳定","word":"stabilize"},"root":"拉丁语 stare「站立」→ stabilis「能站立的、牢固的」→ 法语 estable → 英语 stable「稳定的」→ 加动词词尾构成 stabilize「使稳定」；词义由「站住」扩展为「数值、病情、市场不摆动」。","sensesIntro":{"en":"Nine senses move from a hand holding an object to a body, a market and a whole climate: physical support, fixed levels, calm relations, medical control, self-settling, chemical stability, currency, craft balance and natural systems.","cn":"九个义项从一只手扶住物体，走向身体、市场与整个气候：物理支撑、数值恒定、关系缓和、病情控制、自行安定、化学稳定、货币、航行平衡与自然系统。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand tightening the last knob on a shaking tripod until the frame stops moving.","cn":"核心意象：一只手拧紧晃动三脚架上的最后一个旋钮，直到画面不再移动。"},"chain":["HOLD IN PLACE","KEEP AT A LEVEL","CALM THE SITUATION","STEADY THE BODY","SETTLE BY ITSELF","RESTORE BALANCE"],"branches":[{"senses":"01 · 08","en":"THE SUPPORT BRANCH: props hold a wall, and a pilot brings an aircraft back to level.","cn":"支撑分支：支柱撑住墙，飞行员把飞行器带回水平。"},{"senses":"02 · 07","en":"THE LEVEL BRANCH: a thermostat holds temperature and a central bank holds a currency.","cn":"水平分支：恒温器稳住温度，中央银行稳住货币。"},{"senses":"03","en":"THE RELATIONS BRANCH: a mediator keeps talks from tipping over.","cn":"关系分支：调解人使谈判不至于倾覆。"},{"senses":"04 · 05","en":"THE BODY BRANCH: doctors steady a patient, and a pulse settles on its own.","cn":"身体分支：医生稳住病人，脉搏也会自行安定。"},{"senses":"06 · 09","en":"THE MATERIAL AND SYSTEM BRANCH: acid keeps a solution from breaking down, and wetlands keep a climate within range.","cn":"材料与系统分支：酸使溶液不分解，湿地使气候停留在可运转的范围内。"}]},"affixes":{"intro":{"en":"Stabilize is an English verb built on a Latin adjective of standing, with a productive verb ending doing the work of making.","cn":"这是一个建立于拉丁语「站立」形容词之上的英语动词，由能产的动词词尾承担「使成为」的工作。"},"latinIntro":{"en":"Latin supplies the verb of standing, its adjective and a later verb of making firm; English adds its own verb ending.","cn":"拉丁语提供表示站立的动词、其形容词以及后来表示「使牢固」的动词；英语加上自己的动词词尾。"},"items":[{"word":"-ize","structure":"English verb-forming suffix through French and Latin","meaning":"to make or become","meaningCN":"使成为；使……化","example":"It turns the adjective into a verb of making.","exampleCN":"它把形容词变成表示「使成为」的动词。"},{"word":"stable","structure":"English adjective from French","meaning":"firm, steady","meaningCN":"牢固的；稳定的","example":"The adjective supplies the meaning the verb carries.","exampleCN":"这个形容词提供动词所承载的意义。"},{"word":"stabilis","structure":"Latin adjective from stare","meaning":"able to stand, firm","meaningCN":"能站立的；牢固的","example":"The Latin adjective already implies resistance to falling.","exampleCN":"这个拉丁形容词已经含有「抗倒塌」的意思。"},{"word":"stare","structure":"Latin verb, first conjugation","meaning":"to stand, remain","meaningCN":"站立；留在原处","example":"Standing is the physical picture under all the senses.","exampleCN":"站立是所有义项底下的物理图像。"},{"word":"-ation","structure":"Latin noun ending through French","meaning":"action or result","meaningCN":"动作或结果","example":"It forms the noun for the process of making steady.","exampleCN":"它构成表示「使稳定」这一过程的名词。"},{"word":"-er","structure":"English agent suffix","meaning":"one that does or a device that does","meaningCN":"做某事者；起某作用的器具","example":"It names the device that keeps a thing steady.","exampleCN":"它命名使某物保持稳定的装置。"},{"word":"-ity","structure":"Latin noun ending through French","meaning":"quality of being","meaningCN":"……的性质","example":"It forms the noun for the quality of standing firm.","exampleCN":"它构成表示「稳固」性质的名词。"},{"word":"-ization","structure":"English noun suffix, -ize + -ation","meaning":"action or result of making or becoming","meaningCN":"使……或变为……的行为或结果","example":"It forms stabilization, the act of making steady.","exampleCN":"它构成 stabilization，即「使稳定的行为」。"}],"latinEntries":[{"word":"stare","structure":"sto, steti, statum (verb, first conjugation)","meaning":"to stand, remain","meaningCN":"站立；停留"},{"word":"stabilis","structure":"adjective from stare","meaning":"firm, able to stand","meaningCN":"牢固的；能站立的"},{"word":"stabilire","structure":"stabilio, stabilivi, stabilitum (verb, first conjugation)","meaning":"to make firm","meaningCN":"使牢固；使稳定"}],"derivatives":[{"word":"stabilization","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「稳定化；稳定过程」"},{"word":"stabilizer","pos":"n.","zh":"由该动词加表示施动者或器具的名词尾构成，义为「稳定器；安定剂」"},{"word":"stabilized","pos":"adj.","zh":"由该动词的过去分词转成的形容词，义为「已稳定的」"},{"word":"stabilizing","pos":"adj.","zh":"由该动词的现在分词转成的形容词，义为「起稳定作用的」"}]}},{"word":"suppress","ipa_uk":"/səˈpres/","ipa_us":"/səˈpres/","definition_zh":"压制；镇压；抑制；忍住；隐瞒；抑制（生理反应）","definition_en":"to put something down by force, to hold it back from expression or release, and to keep it from being known","core_image":"桌上立着一根弹簧，一只手把它压到桌面，弹簧在掌下弯成扁弧，一松手就会弹起","scene":"桌上立着一根弹簧，一只手把它压到桌面，弹簧在掌下弯成扁弧，一松手就会弹起。The officer tried to suppress the disturbance before it spread.","sceneCN":"这里指以力量制止、镇压（第 1 个义项：用武力压住骚乱）；句意为那名官员试图在骚乱扩散之前把它压制住。","pos":[{"tag":"v.","zh":"压制；镇压；抑制；忍住；隐瞒"}],"collocations":[{"phrase":"suppress a revolt","zh":"镇压叛乱"},{"phrase":"suppress a smile","zh":"忍住笑"},{"phrase":"suppress the immune system","zh":"抑制免疫系统"},{"phrase":"suppress information","zh":"封锁消息"},{"phrase":"suppress weeds","zh":"抑制杂草"},{"phrase":"suppress a cough","zh":"止咳"},{"phrase":"suppress evidence","zh":"隐瞒证据"}],"forms":[{"label":"原形","form":"suppress"},{"label":"三单","form":"suppresses"},{"label":"过去式","form":"suppressed"},{"label":"过去分词","form":"suppressed"},{"label":"现在分词","form":"suppressing"},{"label":"名词（压制）","form":"suppression"}],"derivatives":[{"word":"suppression","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「压制；抑制；隐瞒」"},{"word":"suppressor","pos":"n.","zh":"由该动词加表示施动者或装置的名词尾构成，义为「压制者；抑制器」"},{"word":"suppressant","pos":"n./adj.","zh":"由该动词加表示起某作用之物的词尾构成，义为「抑制剂（尤指止咳药）」"},{"word":"suppressible","pos":"adj.","zh":"由该动词加表示可能性的形容词尾构成，义为「可被压制的」"},{"word":"suppressive","pos":"adj.","zh":"由该动词加表示性质的形容词尾构成，义为「压制的；抑制性的」"}],"senses":[{"no":"01","title":"Put down a revolt by force","titleCN":"以武力镇压","definition":"to end an uprising, riot or disturbance using authority or armed force","definitionCN":"用权威或武力结束暴动、骚乱或动乱","example":"Troops were sent to suppress the revolt.","exampleCN":"军队被派去镇压叛乱。","why":"The Latin compound means to press from below, and a force that presses a crowd down is the oldest sense of the word.","whyCN":"拉丁复合词意为「从下面压」，而把人群压下去的力量，正是这个词最古老的义项。"},{"no":"02","title":"Hold back an expression of feeling","titleCN":"忍住情绪的外露","definition":"to stop a smile, laugh, tear or cry from showing or escaping","definitionCN":"阻止笑、哭或眼泪表现出来或发出","example":"She could not suppress a smile at the joke.","exampleCN":"听到那个笑话，她忍不住笑了。","why":"A feeling pushes upward like a spring, and suppressing it is the hand that keeps the spring compressed.","whyCN":"情绪像弹簧一样向上顶，而「抑制」就是那只把弹簧压住的手。"},{"no":"03","title":"Hold back a bodily reflex","titleCN":"忍住身体的反应","definition":"to prevent a cough, sneeze or yawn from happening or being heard","definitionCN":"阻止咳嗽、打喷嚏或打哈欠发生或被听见","example":"He tried to suppress a cough during the lecture.","exampleCN":"讲座期间他努力忍住咳嗽。","why":"Here the body itself is the spring, and the will is the hand pressing it down for a while.","whyCN":"这里身体本身就是那根弹簧，而意志是暂时把它压住的手。"},{"no":"04","title":"Keep information from the public","titleCN":"封锁消息","definition":"to prevent a report, fact or image from being published or circulated","definitionCN":"阻止报道、事实或图像被发表或传播","example":"The government tried to suppress the report.","exampleCN":"政府试图压下那份报告。","why":"What is pressed down cannot rise into view, so the word moved from crowds to facts that someone wants buried.","whyCN":"被压住的东西无法升到眼前，于是这个词从人群转到有人想埋掉的事实。"},{"no":"05","title":"Hold back growth","titleCN":"抑制生长","definition":"to stop plants, cells or organisms from growing or spreading","definitionCN":"阻止植物、细胞或生物生长或蔓延","example":"Chemical sprays suppress the weeds along the fence.","exampleCN":"化学喷剂抑制了篱笆边的杂草。","why":"Growth is an upward push too, and agriculture uses the same pressing image as politics.","whyCN":"生长同样是一种向上的推力，农业用的也是政治里那同一个「压」的意象。"},{"no":"06","title":"Reduce a biological response","titleCN":"抑制生物反应","definition":"in medicine and biology, to weaken an immune, inflammatory or nervous response","definitionCN":"医学与生物学中指减弱免疫、炎症或神经反应","example":"The drug suppresses the immune response.","exampleCN":"这种药抑制免疫反应。","why":"A response that has been damped down is literally held back, which is exactly what the Latin verb says.","whyCN":"被压低的反应字面上就是被按住，这正是那个拉丁动词所说的。"},{"no":"07","title":"Reduce sound or vibration","titleCN":"降低声音或震动","definition":"to lessen noise, echo or shaking produced by a machine or a room","definitionCN":"减弱机器或房间产生的噪音、回声或震动","example":"New panels were fitted to suppress the engine noise.","exampleCN":"安装了新面板以压制发动机噪音。","why":"Sound is a wave that pushes outward, and damping it is another version of pressing down.","whyCN":"声音是向外推的波，把它减弱又是「压下去」的另一种版本。"},{"no":"08","title":"Keep evidence from being seen","titleCN":"隐瞒证据","definition":"to hide a document, witness or fact that would otherwise come before a court","definitionCN":"藏起本会呈上法庭的文件、证人或事实","example":"The company was accused of suppressing evidence.","exampleCN":"该公司被指控隐瞒证据。","why":"The legal sense sharpens the secrecy sense: what is suppressed is not destroyed but kept from surfacing.","whyCN":"法律义把「隐瞒」义磨得更锋利：被压下的东西不是被销毁，而是被阻止浮出水面。"},{"no":"09","title":"Put out a fire","titleCN":"扑灭火焰","definition":"to stop a fire or flame from spreading by smothering or cooling it","definitionCN":"用窒息或降温的方式阻止火或火焰蔓延","example":"Firefighters worked fast to suppress the blaze.","exampleCN":"消防员迅速行动扑灭大火。","why":"Fire is the most visible thing that spreads upward, and putting it out is the word at its most physical.","whyCN":"火是最显眼的向上蔓延之物，把火扑灭正是这个词最物理的一面。"}],"etymology":{"intro":{"en":"Suppress comes from Latin suppressus, the past participle of supprimere, to press down, built from sub-, under, and premere, to press.","cn":"这个词来自拉丁语 suppressus，即 supprimere「向下压」的过去分词，由 sub-「在下」与 premere「压」构成。"},"items":[{"era":"LATIN PREMERE","en":"Premere meant to press, squeeze or stamp, and its family includes press and imprint.","cn":"premere 意为压、挤或印，其同族包括「压」与「印痕」等词。"},{"era":"LATIN SUPPRIMERE","en":"The compound added the idea of downward pressure, and it could describe both a foot on a thing and a force on a people.","cn":"这个复合词加上向下的压力，既能描述脚踩在某物上，也能描述力量压在人群上。"},{"era":"LATIN SUPPRESSUS","en":"The participle meant pressed down or held back, and English took it as an adjective before it took it as a verb.","cn":"这个分词意为被压下、被按住的，英语先把它作形容词用，再作动词用。"},{"era":"ENGLISH SUPPRESS","en":"The verb entered English in the late Middle Ages with the political sense first; the exact first date is uncertain.","cn":"这个动词在中世纪末进入英语，最先带的正是政治义；确切首见年代不确定。"},{"era":"MODERN MEDICAL USE","en":"Medicine extended the word to coughs, immune responses and hormones that the body itself holds back.","cn":"医学把词扩展到咳嗽、免疫反应与身体自身会抑制的激素。"},{"era":"MODERN MEDIA USE","en":"Journalism gave the word its common modern sense of keeping a story out of sight.","cn":"新闻业赋予它常见的现代义：把一则报道挡在视线之外。"}]},"similar":{"note":{"en":"The first group looks or sounds like suppress; the second group names neighbouring ways of holding something down.","cn":"第一组在形音上与 suppress 相近；第二组是与「压住、止住」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"suppression","ipa":"/səˈpreʃn/","tag":"same root","definition":"The act of putting something down or keeping it from showing.","definitionCN":"指压制、抑制或隐瞒的行为。"},{"word":"suppressor","ipa":"/səˈpresə/","tag":"same root","definition":"A person or device that holds something back.","definitionCN":"指进行压制的人或装置。"},{"word":"suppressant","ipa":"/səˈpresnt/","tag":"same root","definition":"A substance that reduces a bodily function, especially a cough.","definitionCN":"指减弱身体功能的物质，尤指止咳药。"},{"word":"suppressive","ipa":"/səˈpresɪv/","tag":"same root","definition":"Acting to hold something down or reduce it.","definitionCN":"指起压制或减弱作用的。"},{"word":"suppose","ipa":"/səˈpəʊz/","tag":"different root","definition":"To think something is likely; it shares the prefix but rests on a verb meaning to place.","definitionCN":"指认为某事很可能；共享前缀，但底层是意为「放置」的动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"repress","ipa":"/rɪˈpres/","tag":"near meaning","definition":"To push a feeling or memory back so that it does not enter awareness; it stresses the inward push.","definitionCN":"指把情绪或记忆压回去使其不进入意识；强调向内的推压。"},{"word":"oppress","ipa":"/əˈpres/","tag":"near meaning","definition":"To keep people under harsh control over a long time; it stresses the weight on the group.","definitionCN":"指长期以严酷方式统治人群；强调压在群体身上的重量。"},{"word":"restrain","ipa":"/rɪˈstreɪn/","tag":"near meaning","definition":"To hold someone or something back from acting; it stresses the leash rather than the weight.","definitionCN":"指阻止某人或某物行动；强调缰绳而非重量。"},{"word":"quell","ipa":"/kwel/","tag":"near meaning","definition":"To put down a disturbance or a strong feeling; close to the first sense but more literary.","definitionCN":"指平息骚动或强烈情绪；接近第一个义项，但更书面。"},{"word":"stifle","ipa":"/ˈstaɪfl/","tag":"near meaning","definition":"To cut off the air or the expression of something; it stresses suffocation more than pressure.","definitionCN":"指切断空气或某种表达；强调窒息感而非压力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the pressing root, the downward prefix and the many objects the word has been applied to.","cn":"正常联想利用「压」的词根、向下的前缀，以及这个词曾被用到的众多对象。"},"normal":[{"en":"The prefix means under and the verb means press, so the word says press under.","cn":"前缀意为「在下」，词根意为「压」，所以这个词说的就是「往下压」。"},{"en":"A hand on a spring is the picture: hold it down and it cannot jump.","cn":"手压弹簧就是那幅图：按住它，它就弹不起来。"},{"en":"A cough suppressant does to a cough what a lid does to a flame.","cn":"止咳药对咳嗽做的事，就像盖子对火焰做的事。"},{"en":"A suppressed report is a report someone is sitting on.","cn":"被压下的报道，就是有人坐在上面的报道。"},{"en":"The word covers crowds, smiles, coughs, weeds, immune cells, noise, evidence and fire, all by the same downward gesture.","cn":"这个词覆盖人群、笑容、咳嗽、杂草、免疫细胞、噪音、证据与火焰，靠的都是同一个向下压的手势。"}],"abstract":[{"en":"Suppression works by making something invisible rather than by making it cease to exist.","cn":"压制靠的是让某物看不见，而不是让它不再存在。"},{"en":"What is held down keeps its energy; release it and the spring jumps.","cn":"被压住的东西保留着能量；一松手，弹簧就会跳起来。"},{"en":"A society that suppresses a fact usually pays for it later in a larger disturbance.","cn":"压制事实的社会，通常要在之后以更大的动荡付出代价。"}]},"examples":[{"en":"The regime suppressed every paper that criticised it.","cn":"该政权压制了每一份批评它的报纸。"},{"en":"She suppressed a yawn and kept writing.","cn":"她忍住哈欠，继续写下去。"},{"en":"Doctors gave him a drug to suppress the inflammation.","cn":"医生给他一种药以抑制炎症。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「瑟普雷斯」——「瑟」抖的弹簧被「普雷」一下压平，还「斯」的一声贴住桌面：压制","word":"suppress"},"root":"拉丁语 premere「压」→ sub-「在下」+ premere 构成 supprimere「向下压」→ 过去分词 suppressus「被压住的」→ 英语 suppress「压制；抑制；隐瞒」；核心动作始终是「从上方把东西按下去」。","sensesIntro":{"en":"Nine senses share one downward gesture: a revolt, a smile, a cough, a report, weeds, an immune response, noise, evidence and a fire.","cn":"九个义项共享同一个向下压的手势：叛乱、笑容、咳嗽、报道、杂草、免疫反应、噪音、证据与火焰。"},"semanticMap":{"core":{"en":"CORE IMAGE: a palm pressing a standing spring flat against the table.","cn":"核心意象：一只手掌把立着的弹簧压平在桌面上。"},"chain":["PRESS DOWN","PUT DOWN BY FORCE","HOLD BACK EXPRESSION","HOLD BACK THE BODY","KEEP OUT OF SIGHT","KEEP FROM SPREADING"],"branches":[{"senses":"01 · 09","en":"THE FORCE BRANCH: troops end a revolt, and firefighters end a blaze.","cn":"武力分支：军队平息叛乱，消防员扑灭大火。"},{"senses":"02 · 03","en":"THE HELD-BACK BRANCH: a smile is kept in and a cough is kept down.","cn":"忍住分支：笑容被收住，咳嗽被压下。"},{"senses":"04 · 08","en":"THE SECRECY BRANCH: a report is buried and evidence is kept from court.","cn":"隐瞒分支：报道被埋掉，证据被挡在法庭之外。"},{"senses":"05 · 06","en":"THE BIOLOGY BRANCH: sprays hold weeds back and drugs damp an immune response.","cn":"生物分支：喷剂抑制杂草，药物压低免疫反应。"},{"senses":"07","en":"THE NOISE BRANCH: panels take the push out of engine sound.","cn":"噪音分支：面板卸掉发动机声音里的推力。"}]},"affixes":{"intro":{"en":"Suppress is a Latin compound of under and press, and English added a full set of noun and adjective endings to it.","cn":"这是一个由「在下」与「压」构成的拉丁复合词，英语又给它配上一整套名词与形容词词尾。"},"latinIntro":{"en":"Latin supplies the prefix sub-, the verb premere and its compound supprimere, whose participle English borrowed.","cn":"拉丁语提供前缀 sub-、动词 premere 及其复合词 supprimere，英语借用的正是它的分词。"},"items":[{"word":"sub-","structure":"Latin prefix","meaning":"under, from below","meaningCN":"在下；从下面","example":"It gives the pressure its downward direction.","exampleCN":"它给这份压力一个向下的方向。"},{"word":"premere","structure":"Latin verb, third conjugation","meaning":"to press, squeeze","meaningCN":"压；挤","example":"The verb is the physical core of the whole family.","exampleCN":"这个动词是整族词的物理核心。"},{"word":"supprimere","structure":"sub- plus premere","meaning":"to press down, hold back","meaningCN":"向下压；按住","example":"The compound already carries both the physical and the political sense.","exampleCN":"这个复合词已经同时带有物理义与政治义。"},{"word":"suppressus","structure":"past participle of supprimere","meaning":"pressed down","meaningCN":"被压下的","example":"English took this participle as the base of the verb.","exampleCN":"英语把这个分词作为动词的基础。"},{"word":"-ion","structure":"Latin noun ending through French","meaning":"action or result","meaningCN":"动作或结果","example":"It forms the noun for the act of putting down.","exampleCN":"它构成表示「压下」这一动作的名词。"},{"word":"-or","structure":"Latin agent ending","meaning":"one that does","meaningCN":"做某事者","example":"It names the person or device that suppresses.","exampleCN":"它命名进行压制的个人或装置。"},{"word":"-ant","structure":"Latin present participle ending","meaning":"that does or causes","meaningCN":"起……作用的","example":"It forms the name of a cough-reducing drug.","exampleCN":"它构成表示止咳药物的名称。"},{"word":"-ible","structure":"Latin possibility ending","meaning":"capable of being","meaningCN":"能被……的","example":"It marks what can be held down.","exampleCN":"它标出可以被压住的东西。"},{"word":"-ive","structure":"Latin adjective ending","meaning":"tending to","meaningCN":"有……倾向的","example":"It forms the adjective for a damping action.","exampleCN":"它构成表示「起压制作用」的形容词。"}],"latinEntries":[{"word":"premere","structure":"premo, pressi, pressum (verb, third conjugation)","meaning":"to press, squeeze","meaningCN":"压；挤"},{"word":"supprimere","structure":"sub- plus premere (verb, third conjugation)","meaning":"to press down, hold back","meaningCN":"向下压；按住"},{"word":"suppressus","structure":"past participle of supprimere","meaning":"pressed down","meaningCN":"被压下的"}],"derivatives":[{"word":"suppression","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「压制；抑制；隐瞒」"},{"word":"suppressor","pos":"n.","zh":"由该动词加表示施动者或装置的名词尾构成，义为「压制者；抑制器」"},{"word":"suppressant","pos":"n./adj.","zh":"由该动词加表示起某作用之物的词尾构成，义为「抑制剂（尤指止咳药）」"},{"word":"suppressible","pos":"adj.","zh":"由该动词加表示可能性的形容词尾构成，义为「可被压制的」"},{"word":"suppressive","pos":"adj.","zh":"由该动词加表示性质的形容词尾构成，义为「压制的；抑制性的」"}]}},{"word":"transcend","ipa_uk":"/trænˈsend/","ipa_us":"/trænˈsend/","definition_zh":"超越；超出；胜过；凌驾于……之上","definition_en":"to go beyond a limit, level or ordinary range, and in older use to surpass or excel","core_image":"山路上雾线横在脚下，一个人继续往上走，穿过云层，回头已看不见那条界线","scene":"山路上雾线横在脚下，一个人继续往上走，穿过云层，回头已看不见那条界线。Music can transcend the barrier between two languages.","sceneCN":"这里指越过某种界限（第 1 个义项：超出界限与范围）；句意为音乐能够超越两种语言之间的障碍。","pos":[{"tag":"v.","zh":"超越；超出；胜过；凌驾于……之上"}],"collocations":[{"phrase":"transcend boundaries","zh":"超越边界"},{"phrase":"transcend differences","zh":"超越差异"},{"phrase":"transcend the limits of","zh":"超出……的限度"},{"phrase":"transcend one's time","zh":"超越自己所处的时代"},{"phrase":"transcend the material world","zh":"超越物质世界"},{"phrase":"transcend one's authority","zh":"超越自己的权限"}],"forms":[{"label":"原形","form":"transcend"},{"label":"三单","form":"transcends"},{"label":"过去式","form":"transcended"},{"label":"过去分词","form":"transcended"},{"label":"现在分词","form":"transcending"},{"label":"名词（超越）","form":"transcendence"}],"derivatives":[{"word":"transcendence","pos":"n.","zh":"由该动词加表示状态的名词尾构成，义为「超越；超然」"},{"word":"transcendent","pos":"adj.","zh":"由该动词的现在分词词干转成的形容词，义为「卓越的；超越的」"},{"word":"transcendental","pos":"adj.","zh":"由前一词加表示关系的形容词尾构成，义为「先验的；超越经验的」"},{"word":"transcendently","pos":"adv.","zh":"由形容词加表示方式的副词尾构成，义为「卓越地；超越地」"}],"senses":[{"no":"01","title":"Go beyond a limit or boundary","titleCN":"越过界限","definition":"to pass across the edge of what is allowed, mapped or expected","definitionCN":"越过被允许、被标定或被预期的边缘","example":"The path seemed to transcend the boundary of the map.","exampleCN":"那条小路似乎越过了地图上的边界。","why":"The Latin verb means to climb over, and the oldest image is a body moving past a line rather than a number beating another number.","whyCN":"那个拉丁动词意为「爬过」，最古老的意象是身体越过一条线，而不是数字胜过另一个数字。"},{"no":"02","title":"Rise above the material world","titleCN":"超越物质世界","definition":"in religion and philosophy, to move beyond bodily and worldly concerns","definitionCN":"在宗教与哲学中指超出身体与世俗的关切","example":"Monks sought to transcend the material world.","exampleCN":"僧侣们寻求超越物质世界。","why":"A climber who leaves the ground behind is the natural picture for a soul said to leave the world behind.","whyCN":"把地面留在身后的攀登者，正是用来形容灵魂把世界留在身后的自然图像。"},{"no":"03","title":"Surpass others in quality","titleCN":"在品质上胜过他人","definition":"to be so much better than rivals that comparison no longer applies","definitionCN":"比对手好得多，以致比较已不适用","example":"Her later work transcends every rival in the same field.","exampleCN":"她后期的作品超越了同领域的每一位对手。","why":"Here the word is close to surpass, but it claims a different level rather than a higher score.","whyCN":"这里这个词接近「胜过」，但它主张的是不同的层次，而不是更高的分数。"},{"no":"04","title":"Outlast the age that produced it","titleCN":"超越所产生的时代","definition":"of an idea or work, to remain valuable beyond the period in which it was made","definitionCN":"指思想或作品在产生它的时期之后仍然有价值","example":"Some ideas transcend the age that produced them.","exampleCN":"有些思想超越了产生它们的时代。","why":"Time is a boundary like any other, and what crosses it survives the terms it was born in.","whyCN":"时间也是一条界线，越过它的东西便活过了自己诞生时的那些条件。"},{"no":"05","title":"Cross the barrier between languages or cultures","titleCN":"跨越语言或文化的障碍","definition":"of art or feeling, to reach people who do not share a tongue or a tradition","definitionCN":"指艺术或情感抵达语言或传统不同的人","example":"Music can transcend the barrier between two languages.","exampleCN":"音乐能够超越两种语言之间的障碍。","why":"A barrier is a wall, and the word keeps the climbing image when it says the wall was crossed.","whyCN":"障碍是一道墙，而这个词在说「墙被越过」时，保留的仍是攀爬的意象。"},{"no":"06","title":"Go beyond one's own limits","titleCN":"超越自身的局限","definition":"of a person, to act beyond fear, habit or the role usually played","definitionCN":"指人做出超出恐惧、习惯或通常角色的行为","example":"He tried to transcend his own fears.","exampleCN":"他试图超越自己的恐惧。","why":"The self can be a boundary too, and the climber may be climbing out of a former self.","whyCN":"自我也可以是一条界线，攀登者也许正在爬出旧的自己。"},{"no":"07","title":"Lie beyond possible experience","titleCN":"超出经验可能的范围","definition":"in philosophy, of a question or principle that cannot be tested by experience","definitionCN":"哲学上指无法由经验检验的问题或原则","example":"Philosophers asked whether reason could transcend experience.","exampleCN":"哲学家追问理性是否能超越经验。","why":"This is the technical sense: not better than experience, but outside the region where experience can go.","whyCN":"这是术语义：不是比经验更好，而是在经验所能抵达的区域之外。"},{"no":"08","title":"Go beyond one's authority","titleCN":"超出自己的权限","definition":"of an order or act, to pass the legal or official power of the person who made it","definitionCN":"指命令或行为越过作出者合法的或官方的权力","example":"The officer's order seemed to transcend his legal authority.","exampleCN":"那名军官的命令似乎超越了他的法定权限。","why":"Authority is a line drawn by law, and crossing it uses the word in its plainest boundary sense.","whyCN":"权限是法律画出的一条线，越过它就是这个词最朴素的「界线」义。"},{"no":"09","title":"Be above the created world","titleCN":"凌驾于受造世界之上","definition":"in theology, of the divine as separate from and higher than everything created","definitionCN":"在神学中指神性独立于并高于一切受造之物","example":"Believers hold that the divine transcends the created world.","exampleCN":"信徒认为神超越受造的世界。","why":"The highest use of the word places its subject not at the top of a scale but outside the scale altogether.","whyCN":"这个词最高的用法，把主语放在不是刻度顶端、而是刻度之外的位置。"}],"etymology":{"intro":{"en":"Transcend comes from Latin transcendere, to climb over or go beyond, built from trans-, across, and scandere, to climb.","cn":"这个词来自拉丁语 transcendere「爬过、越过」，由 trans-「穿过」与 scandere「攀爬」构成。"},"items":[{"era":"LATIN SCANDERE","en":"Scandere meant to climb or ascend, and it also stands under the words for a ladder and for scanning a line of verse.","cn":"scandere 意为攀爬、上升，它也是「梯子」与「按格律诵读诗句」等词的底层。"},{"era":"LATIN TRANSCENDERE","en":"The compound meant to climb over or pass beyond, used of walls, hills and limits of every kind.","cn":"这个复合词意为爬过、越出，用于墙、山丘以及各种界限。"},{"era":"LATIN TRANSCENDENTIA","en":"Medieval Latin made a noun for that which lies beyond the categories of ordinary thought.","cn":"中世纪拉丁语造出一个名词，指超出日常思想范畴的东西。"},{"era":"FRENCH TRANSCENDANT","en":"French carried the adjective into philosophy, where it named what is above the world rather than merely great in it.","cn":"法语把这个形容词带进哲学，用来指高于世界者，而不只是世界之内的大者。"},{"era":"ENGLISH TRANSCEND","en":"English took the verb in the late Middle Ages; the exact first date is uncertain, and the religious sense came before the general one.","cn":"英语在中世纪末取用这个动词；确切首见年代不确定，宗教义先于一般义出现。"},{"era":"MODERN PHILOSOPHICAL USE","en":"Kant fixed the modern contrast between what experience can reach and what lies beyond it.","cn":"康德确立了现代意义上的对比：经验能抵达的东西，与处在它之外的东西。"}]},"similar":{"note":{"en":"The first group looks or sounds like transcend; the second group names neighbouring ideas of going past a limit.","cn":"第一组在形音上与 transcend 相近；第二组是与「越过限度」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"transcendence","ipa":"/trænˈsendəns/","tag":"same root","definition":"The state of being beyond ordinary limits or above the world.","definitionCN":"指超出寻常限度或高于世界的状态。"},{"word":"transcendent","ipa":"/trænˈsendənt/","tag":"same root","definition":"Going beyond the ordinary range, often used of excellence.","definitionCN":"指超出寻常范围的，常用于形容卓越。"},{"word":"transcendental","ipa":"/ˌtrænsenˈdentl/","tag":"same root","definition":"Relating to what lies beyond possible experience.","definitionCN":"指与超出可能经验之物相关的。"},{"word":"ascend","ipa":"/əˈsend/","tag":"same root","definition":"To climb or rise; it shares the climbing verb with a different prefix.","definitionCN":"指攀登或上升；共享同一个攀爬动词，前缀不同。"},{"word":"descend","ipa":"/dɪˈsend/","tag":"same root","definition":"To go down; the mirror image of climbing, built with a prefix meaning down.","definitionCN":"指下降；攀爬的镜像，由意为「向下」的前缀构成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"surpass","ipa":"/səˈpɑːs/","tag":"near meaning","definition":"To be greater than another in amount or degree; it stays inside the same scale.","definitionCN":"指在数量或程度上大于另一者；它仍停留在同一把刻度之内。"},{"word":"exceed","ipa":"/ɪkˈsiːd/","tag":"near meaning","definition":"To go past a stated number or limit; it is neutral and often numerical.","definitionCN":"指超过某个明示的数字或限度；中性，常指数值。"},{"word":"excel","ipa":"/ɪkˈsel/","tag":"near meaning","definition":"To be very good at something, often the best among a group.","definitionCN":"指在某方面极好，常指群体中最好的。"},{"word":"outstrip","ipa":"/ˌaʊtˈstrɪp/","tag":"near meaning","definition":"To go faster or further than another, as one runner leaves another behind.","definitionCN":"指比另一者更快或更远，像一名跑者把另一名甩在身后。"},{"word":"outdo","ipa":"/ˌaʊtˈduː/","tag":"near meaning","definition":"To perform better than someone else in the same task.","definitionCN":"指在同一件事上做得比他人更好。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the climbing root, the across prefix and the contrast with mere surpassing.","cn":"正常联想利用「攀爬」的词根、「穿过」的前缀，以及它与单纯「胜过」的对比。"},"normal":[{"en":"The prefix means across and the verb means climb, so the word pictures someone climbing over a wall.","cn":"前缀意为「穿过」，词根意为「攀爬」，于是这个词画的是有人翻过一道墙。"},{"en":"A ladder, a scale and a scan all come from the same climbing verb, because climbing is measuring step by step.","cn":"梯子、音阶与逐行扫读都出自同一个攀爬动词，因为攀爬正是一级一级地量。"},{"en":"The mountain fog line is the picture: below it is the ordinary route, above it the view changes.","cn":"山上的雾线就是那幅图：线以下是寻常路线，线以上视野就变了。"},{"en":"Transcend a boundary, not just a score; surpass a score, not a boundary.","cn":"超越的是界线，不只是分数；胜过的是分数，不是界线。"},{"en":"The word keeps a vertical direction even when the barrier is invisible, as with language or culture.","cn":"即使障碍看不见，比如语言或文化，这个词仍保留着竖直的方向。"}],"abstract":[{"en":"To transcend is to change the frame, not to win inside the old one.","cn":"超越是换掉框架，而不是在旧框架里取胜。"},{"en":"Every boundary is drawn by someone; crossing it exposes who drew it.","cn":"每条界线都由某人画出；越过它就暴露出是谁画的。"},{"en":"The word promises a higher place, and it quietly asks what ground you are leaving.","cn":"这个词许诺一个更高的位置，也悄悄追问你正把什么地面留在身后。"}]},"examples":[{"en":"The novel transcends the genre it was written in.","cn":"这部小说超越了它所属的文类。"},{"en":"Great architecture can transcend time and fashion.","cn":"伟大的建筑能够超越时间与风尚。"},{"en":"No emergency order may transcend the constitution.","cn":"任何紧急命令都不得超越宪法。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「传森德」——「传」过一片「森」林，到「德」国那头，已经越过界线：超越","word":"transcend"},"root":"拉丁语 scandere「攀爬」→ trans-「穿过」+ scandere 构成 transcendere「爬过、越过」→ 英语 transcend「超越」；由翻墙的具体动作，扩展为越过时代、语言、经验与权限等抽象界线。","sensesIntro":{"en":"Nine senses climb from a line on a map to the top of a scale and beyond it: limits, the material world, rivals, an age, language, the self, experience, authority and the divine.","cn":"九个义项从地图上的一条线一路爬到刻度的顶端之外：界线、物质世界、对手、时代、语言、自我、经验、权限与神性。"},"semanticMap":{"core":{"en":"CORE IMAGE: a walker rising through cloud until the boundary line below can no longer be seen.","cn":"核心意象：行走者穿过云层上升，直到脚下的界线再也看不见。"},"chain":["CLIMB OVER","CROSS THE LIMIT","RISE ABOVE THE WORLD","EXCEED COMPARISON","OUTLAST THE AGE","BEYOND EXPERIENCE"],"branches":[{"senses":"01 · 08","en":"THE LIMIT BRANCH: a path crosses the edge of the map, and an order crosses the edge of lawful power.","cn":"界线分支：小路越过地图边缘，命令越过合法权力的边缘。"},{"senses":"02 · 09","en":"THE ABOVE-THE-WORLD BRANCH: a monk leaves the material world, and the divine is said to be above all created things.","cn":"高于世界分支：僧侣离开物质世界，神性被说成高于一切受造之物。"},{"senses":"03 · 04","en":"THE COMPARISON AND TIME BRANCH: a work outclasses its rivals and outlives its age.","cn":"比较与时间分支：作品胜过对手，也活过自己的时代。"},{"senses":"05 · 06","en":"THE HUMAN BARRIER BRANCH: music crosses languages and a person crosses his own fear.","cn":"人的障碍分支：音乐越过语言，人越过自己的恐惧。"},{"senses":"07","en":"THE EXPERIENCE BRANCH: a philosophical question lies outside what any test can reach.","cn":"经验分支：哲学问题处在任何检验都到不了的地方。"}]},"affixes":{"intro":{"en":"Transcend is a Latin compound of across and climb, and its noun and adjective family grew inside philosophy.","cn":"这是一个由「穿过」与「攀爬」构成的拉丁复合词，其名词与形容词家族在哲学里长大。"},"latinIntro":{"en":"Latin supplies the prefix trans-, the verb scandere and the compound transcendere, plus a medieval noun in -entia.","cn":"拉丁语提供前缀 trans-、动词 scandere 与复合词 transcendere，以及一个带名词词尾的中世纪名词。"},"items":[{"word":"trans-","structure":"Latin prefix","meaning":"across, through, beyond","meaningCN":"穿过；越过；在……之外","example":"It gives the climbing a direction across a boundary.","exampleCN":"它给攀爬加上一条越过界线的方向。"},{"word":"scandere","structure":"Latin verb, third conjugation","meaning":"to climb, ascend","meaningCN":"攀爬；上升","example":"The verb supplies the vertical picture under every sense.","exampleCN":"这个动词提供每个义项底下的竖直图像。"},{"word":"transcendere","structure":"trans- plus scandere","meaning":"to climb over, go beyond","meaningCN":"爬过；越出","example":"The compound is the direct source of the English verb.","exampleCN":"这个复合词是英语动词的直接来源。"},{"word":"-ent","structure":"Latin present participle ending","meaning":"being or doing","meaningCN":"处于……状态的；做……的","example":"It forms the adjective for what goes beyond.","exampleCN":"它构成表示「越出者」的形容词。"},{"word":"-ence","structure":"Latin noun ending through French","meaning":"state or quality","meaningCN":"状态；性质","example":"It forms the noun for the state of being beyond.","exampleCN":"它构成表示「处于之外」状态的名词。"},{"word":"-al","structure":"Latin adjective ending","meaning":"relating to","meaningCN":"与……相关的","example":"It turns the adjective into the philosophical term.","exampleCN":"它把形容词变成哲学术语。"},{"word":"-ism","structure":"Latin and Greek -ismus, English noun suffix","meaning":"practice, system or doctrine","meaningCN":"主义；学说；体系","example":"It forms transcendentalism, the doctrine of the transcendental.","exampleCN":"它构成 transcendentalism，即先验论。"},{"word":"-ist","structure":"Latin -ista, English noun suffix for a person","meaning":"one who follows or practises","meaningCN":"信奉或从事的人","example":"It forms transcendentalist, a follower of that doctrine.","exampleCN":"它构成 transcendentalist，即信奉该学说的人。"}],"latinEntries":[{"word":"scandere","structure":"scando, scandi, scansum (verb, third conjugation)","meaning":"to climb, ascend","meaningCN":"攀爬；上升"},{"word":"transcendere","structure":"trans- plus scandere (verb, third conjugation)","meaning":"to climb over, go beyond","meaningCN":"爬过；越出"},{"word":"transcendentia","structure":"noun from transcendens (medieval Latin)","meaning":"that which is beyond","meaningCN":"超出范畴者"}],"derivatives":[{"word":"transcendence","pos":"n.","zh":"由该动词加表示状态的名词尾构成，义为「超越；超然」"},{"word":"transcendent","pos":"adj.","zh":"由该动词的现在分词词干转成的形容词，义为「卓越的；超越的」"},{"word":"transcendental","pos":"adj.","zh":"由前一词加表示关系的形容词尾构成，义为「先验的；超越经验的」"},{"word":"transcendently","pos":"adv.","zh":"由形容词加表示方式的副词尾构成，义为「卓越地；超越地」"}]}},{"word":"trigger","ipa_uk":"/ˈtrɪɡə/","ipa_us":"/ˈtrɪɡər/","definition_zh":"触发；引发；激起；扳机；触发器；诱因","definition_en":"to cause something to start suddenly, and the small lever or device that sets a mechanism going","core_image":"靶场上，一根手指搭在扳机上，只要一个很小的动作，整支枪的力量就会释放","scene":"靶场上，一根手指搭在扳机上，只要一个很小的动作，整支枪的力量就会释放。A single spark was enough to trigger the alarm.","sceneCN":"这里指引发、触发（第 1 个义项：使某事突然开始）；句意为一个火花就足以触发警报。","pos":[{"tag":"v.","zh":"触发；引发；激起"},{"tag":"n.","zh":"扳机；触发器；诱因"}],"collocations":[{"phrase":"trigger a reaction","zh":"引发反应"},{"phrase":"trigger an alarm","zh":"触发警报"},{"phrase":"trigger a debate","zh":"引发争论"},{"phrase":"pull the trigger","zh":"扣动扳机"},{"phrase":"trigger a memory","zh":"唤起记忆"},{"phrase":"trigger a crisis","zh":"引发危机"},{"phrase":"trigger warning","zh":"内容预警"}],"forms":[{"label":"原形","form":"trigger"},{"label":"三单","form":"triggers"},{"label":"过去式","form":"triggered"},{"label":"过去分词","form":"triggered"},{"label":"现在分词","form":"triggering"},{"label":"名词（扳机）","form":"trigger"}],"derivatives":[{"word":"triggering","pos":"n./adj.","zh":"由该动词的现在分词转成的名词或形容词，义为「触发；引发性的」"},{"word":"triggered","pos":"adj.","zh":"由该动词的过去分词转成的形容词，义为「被触发的；受激的」"},{"word":"trigger-happy","pos":"adj.","zh":"由该名词与表示「热衷」的形容词合成为复合形容词，义为「动辄开枪的；莽撞行事的」"},{"word":"triggerable","pos":"adj.","zh":"由该动词加表示可能性的形容词尾构成，义为「可被触发的」"}],"senses":[{"no":"01","title":"Cause an event to begin suddenly","titleCN":"引发事件突然开始","definition":"to set off an event or a chain of events that would not have started by itself","definitionCN":"使一个本不会自行开始的事件或连锁事件开始","example":"A small error can trigger a chain of failures.","exampleCN":"一个小错误就可能引发一连串故障。","why":"The word began as the small lever that releases a gun, and the idea of a little act releasing a large force is the heart of every sense.","whyCN":"这个词最初指释放枪械力量的小杠杆，而「一个小动作释放巨大力量」正是每个义项的核心。"},{"no":"02","title":"Provoke a strong feeling","titleCN":"激起强烈情绪","definition":"to cause anger, fear or excitement in a person or group","definitionCN":"引起个人或群体的愤怒、恐惧或激动","example":"The news triggered an angry response from the crowd.","exampleCN":"那条消息激起人群的愤怒回应。","why":"A feeling that was quiet suddenly fires, and the word pictures it as a mechanism released by a small event.","whyCN":"原本安静的情绪突然开火，这个词把它画成被小事释放的机械。"},{"no":"03","title":"Set a device into operation","titleCN":"使装置启动","definition":"to make a sensor, circuit or machine begin working, often automatically","definitionCN":"使传感器、电路或机器开始工作，常为自动进行","example":"The sensor triggers the lamp when someone walks past.","exampleCN":"有人走过时，传感器就会触发那盏灯。","why":"This is the most literal modern sense: a small signal releases a larger action.","whyCN":"这是最字面的现代义：一个小信号释放一个更大的动作。"},{"no":"04","title":"Induce an illness or symptom","titleCN":"诱发疾病或症状","definition":"in medicine, to cause a disease, attack or symptom to begin","definitionCN":"医学上指引起疾病、发作或症状开始","example":"The virus can trigger a high fever.","exampleCN":"这种病毒能引发高烧。","why":"A body already carrying a condition may need only one small provocation, and the word names that provocation.","whyCN":"身体本就带着病因，也许只差一个很小的刺激，而这个词命名的正是那个刺激。"},{"no":"05","title":"The lever on a firearm","titleCN":"枪械的扳机","definition":"the small lever a finger pulls to fire a gun","definitionCN":"手指扣动以使枪械击发的小杠杆","example":"He kept his finger off the trigger until the order came.","exampleCN":"在命令下达之前，他的手指一直没有放在扳机上。","why":"This is the sense from which every other sense borrows its shape: the smallest part controls the largest release.","whyCN":"这是其他所有义项借取形状的源头义：最小的部件控制最大的释放。"},{"no":"06","title":"An electronic pulse that starts an action","titleCN":"电子触发器或触发脉冲","definition":"a signal in a circuit that tells another part to begin its cycle","definitionCN":"电路中通知另一部件开始运行周期的信号","example":"The circuit sends a trigger to the camera every two seconds.","exampleCN":"电路每隔两秒向相机发送一个触发信号。","why":"Electronics kept the gun image and made the lever invisible: a pulse instead of a finger.","whyCN":"电子学保留了枪的意象，却把杠杆变得看不见：用脉冲代替手指。"},{"no":"07","title":"The cause or occasion of an event","titleCN":"事件的诱因","definition":"the event or remark that was the immediate occasion for something larger","definitionCN":"成为更大事件的直接起因的事件或言论","example":"The report was the trigger for a wider debate.","exampleCN":"那份报告成了更广泛争论的诱因。","why":"In this noun sense the lever becomes the occasion itself, the point at which the mechanism was released.","whyCN":"在这个名词义项里，杠杆变成了事件本身，即机械被释放的那一刻。"},{"no":"08","title":"Bring a memory back","titleCN":"唤起记忆","definition":"to cause a scene, smell or sound to bring an old memory into the mind","definitionCN":"使景象、气味或声音把旧日记忆带回心中","example":"The smell of bread triggered a memory of his grandmother's kitchen.","exampleCN":"面包的气味唤起了他对祖母厨房的记忆。","why":"A memory sits loaded like a spring, and one small sensory cue can release it whole.","whyCN":"记忆像上了弦的弹簧，一个小小的感官线索就能把它整个释放。"},{"no":"09","title":"Set off a biological response","titleCN":"引发生物反应","definition":"to start an allergic, immune or inflammatory reaction in a living body","definitionCN":"在生物体内引起过敏、免疫或炎症反应","example":"The pollen may trigger an allergic reaction.","exampleCN":"花粉可能引发过敏反应。","why":"The body is the machine here, and the allergen is the finger on the lever.","whyCN":"这里的机器是身体，而过敏原就是搭在杠杆上的那根手指。"}],"etymology":{"intro":{"en":"Trigger is a Dutch loan. It comes from trekker, a puller, from trekken, to pull, and it entered English first as a name for the lever of a firearm.","cn":"这个词借自荷兰语，来自 trekker「拉者」，而 trekker 出自 trekken「拉」；它进入英语时最先指枪械上的杠杆。"},"items":[{"era":"DUTCH TREKKEN","en":"Trekken meant to pull or draw, and it is also the source of the English word trek, a long journey drawn out by oxen.","cn":"trekken 意为拉、拖，它也是英语 trek「长途跋涉」的来源，那正是牛车拉出来的路。"},{"era":"DUTCH TREKKER","en":"The noun meant one that pulls, and it could name a person, a rope or a part of a machine.","cn":"这个名词意为「拉的东西」，可以指人、指绳，也可以指机器部件。"},{"era":"ENGLISH TRICKER","en":"The earliest English form was tricker, recorded in the sixteenth century for the lever of a gun; the spelling was not yet fixed.","cn":"最早的英语形式是 tricker，十六世纪时用来指枪的杠杆；当时拼写尚未固定。"},{"era":"ENGLISH TRIGGER","en":"The modern spelling settled in the seventeenth century, still tied to firearms before it moved to any small releasing part.","cn":"现代拼写在十七世纪固定下来，仍先与枪械绑定，之后才转向任何小的释放部件。"},{"era":"MODERN MECHANICAL USE","en":"Machines and then circuits borrowed the word for any small part that starts a larger motion.","cn":"机器、随后是电路，都借这个词来指任何启动更大运动的细小部件。"},{"era":"MODERN FIGURATIVE USE","en":"Psychology and medicine extended it to memories, emotions and symptoms, where a small cue releases a large response.","cn":"心理学与医学把它扩展到记忆、情绪与症状，那里一个小小的线索就释放出很大的反应。"}]},"similar":{"note":{"en":"The first group looks or sounds like trigger; the second group names neighbouring ways of starting something.","cn":"第一组在形音上与 trigger 相近；第二组是与「引发、启动」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"triggering","ipa":"/ˈtrɪɡərɪŋ/","tag":"same root","definition":"The act of setting something off, or the quality of doing so.","definitionCN":"指触发的行为，或指具有引发作用的性质。"},{"word":"triggered","ipa":"/ˈtrɪɡəd/","tag":"same root","definition":"Set off or activated by something else.","definitionCN":"指被某物触发或激活的。"},{"word":"trigger-happy","ipa":"/ˈtrɪɡə hæpi/","tag":"same root","definition":"Too ready to shoot or to act rashly.","definitionCN":"指动辄开枪或鲁莽行事的。"},{"word":"tiger","ipa":"/ˈtaɪɡə/","tag":"different root","definition":"A large striped cat; it looks close in spelling but has no shared history.","definitionCN":"指一种大型条纹猫科动物；拼写相近，但没有共同来源。"},{"word":"trickle","ipa":"/ˈtrɪkl/","tag":"different root","definition":"To flow in a thin stream; it sounds close but comes from a different verb.","definitionCN":"指细细地流；读音相近，但来自另一个动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cause","ipa":"/kɔːz/","tag":"near meaning","definition":"To make something happen; neutral about size and speed, and the broadest word here.","definitionCN":"指使某事发生；不涉及大小与速度，是这里最宽泛的词。"},{"word":"provoke","ipa":"/prəˈvəʊk/","tag":"near meaning","definition":"To stir a feeling or a reaction, often deliberately; it stresses the irritation.","definitionCN":"指激起情绪或反应，常含故意；强调被激起的恼怒。"},{"word":"spark","ipa":"/spɑːk/","tag":"near meaning","definition":"To start something large from a very small beginning, with the image of a spark and dry grass.","definitionCN":"指由极小的开端引发大事，意象是火星与干草。"},{"word":"set off","ipa":"/set ɒf/","tag":"near meaning","definition":"To start a device, alarm or chain of events; plainer and more physical than trigger.","definitionCN":"指启动装置、警报或一连串事件；比本词更朴素、更物理。"},{"word":"initiate","ipa":"/ɪˈnɪʃieɪt/","tag":"near meaning","definition":"To begin something formally or deliberately, without the idea of a small lever.","definitionCN":"指正式或有意地开始某事，不含「小杠杆」的意思。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the pulling root, the gun lever and the small-cause-large-effect pattern.","cn":"正常联想利用「拉」的词根、枪的杠杆，以及「小原因、大效果」的模式。"},"normal":[{"en":"The Dutch root means pull, so the trigger is the part you pull to release everything else.","cn":"荷兰语词根意为拉，所以扳机就是你拉一下、其余一切随之释放的那个部件。"},{"en":"A finger moves a few millimetres and the whole gun answers; that is the shape of the word.","cn":"手指移动几毫米，整支枪都作出回应；这就是这个词的形状。"},{"en":"A smoke detector is a trigger made electronic: a little smoke, a loud alarm.","cn":"烟雾报警器就是电子化的扳机：一点烟，一阵大响。"},{"en":"A smell that brings back a kitchen is the same mechanism working on memory.","cn":"让厨房重现的气味，是同一套机械在记忆上工作。"},{"en":"The stock phrase pull the trigger keeps the original object visible inside the modern verb.","cn":"固定说法「扣动扳机」让原本的物件在现代动词里仍然可见。"}],"abstract":[{"en":"A trigger is defined by the ratio between the small input and the large release.","cn":"扳机的本质，在于小输入与大释放之间的比例。"},{"en":"The same event can be a trigger for one person and a trifle for another, because the mechanism is inside.","cn":"同一件事对一个人是扳机，对另一个人却无关紧要，因为机械装在内部。"},{"en":"Naming a trigger is already a way of taking some power back from it.","cn":"说出一个触发点，本身已经是从它手里收回一部分权力。"}]},"examples":[{"en":"The ruling triggered protests across the country.","cn":"那项裁决引发了全国范围的抗议。"},{"en":"A loud noise can trigger a panic attack.","cn":"巨大的声响可能引发惊恐发作。"},{"en":"The alarm was triggered by a broken wire.","cn":"警报是被一根断线触发的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「吹格」——手指一「吹」，扳机一「格」响，整支枪就响了：扳机、触发","word":"trigger"},"root":"荷兰语 trekken「拉」→ trekker「拉者、拉动的部件」→ 英语早期形式 tricker（十六世纪指枪的杠杆）→ trigger「扳机」→ 动词「触发、引发」；核心是「一个很小的拉动释放很大的力量」。","sensesIntro":{"en":"Nine senses all follow one pattern, a small act releasing a large response: events, feelings, devices, illness, the gun lever itself, circuits, occasions, memories and allergic reactions.","cn":"九个义项都遵循同一个模式——小动作释放大反应：事件、情绪、装置、疾病、枪的杠杆本身、电路、诱因、记忆与过敏反应。"},"semanticMap":{"core":{"en":"CORE IMAGE: one finger on a small lever, and the whole weapon answers.","cn":"核心意象：一根手指搭在小杠杆上，整件武器随之响应。"},"chain":["SMALL ACT","BIG RELEASE","SUDDEN START","DEVICE FIRES","BODY REACTS","MEMORY RETURNS"],"branches":[{"senses":"01 · 09","en":"THE RELEASE BRANCH: one error starts a chain, and one allergen starts a reaction.","cn":"释放分支：一个错误引发连锁，一个过敏原引发反应。"},{"senses":"02 · 08","en":"THE INNER BRANCH: a piece of news fires anger, and a smell fires a memory.","cn":"内部分支：一条消息点燃愤怒，一种气味点燃记忆。"},{"senses":"03 · 06","en":"THE MACHINE BRANCH: a sensor starts a lamp, and a pulse starts a camera.","cn":"机械分支：传感器启动灯，脉冲启动相机。"},{"senses":"04","en":"THE ILLNESS BRANCH: a virus provokes a fever in a body already carrying it.","cn":"疾病分支：病毒在本已带病的身体里诱发高烧。"},{"senses":"05 · 07","en":"THE ORIGIN BRANCH: the gun lever itself, and the occasion that releases a debate.","cn":"源头分支：枪的杠杆本身，以及释放一场争论的诱因。"}]},"affixes":{"intro":{"en":"Trigger is not a Latin word at all: it is a Dutch loan whose parts are a verb of pulling and an agent ending.","cn":"这个词根本不是拉丁词，而是一个荷兰语借词，其部件是一个表示「拉」的动词和一个施动词尾。"},"latinIntro":{"en":"There is no Latin etymon behind this word. Its family is Germanic, and the Latin entries are therefore left empty.","cn":"这个词背后没有拉丁语词源，它属于日耳曼语族，因此拉丁语条目留空。"},"items":[{"word":"trekken","structure":"Dutch verb","meaning":"to pull, draw","meaningCN":"拉；拖","example":"The pulling action is the physical core of the word.","exampleCN":"「拉」这个动作是这个词的物理核心。"},{"word":"-er","structure":"Dutch agent suffix","meaning":"one that does","meaningCN":"做某事者","example":"It turns the verb into a noun for the thing that pulls.","exampleCN":"它把动词变成指「拉动之物」的名词。"},{"word":"trekker","structure":"trekken plus -er","meaning":"a puller","meaningCN":"拉者；拉动的部件","example":"The Dutch noun named the part that sets a mechanism going.","exampleCN":"这个荷兰语名词命名启动机械的那个部件。"},{"word":"trigger","structure":"English loan noun","meaning":"the lever of a firearm","meaningCN":"枪械的扳机","example":"English took the Dutch noun and narrowed it to the gun part.","exampleCN":"英语借入这个荷兰语名词，并把意义收窄到枪的部件。"},{"word":"trigger","structure":"English conversion from noun to verb","meaning":"to set off, cause","meaningCN":"触发；引发","example":"English turned the part into an action without adding an ending.","exampleCN":"英语把这个部件直接变成动作，没有加任何词尾。"},{"word":"trigger-happy","structure":"English compound with happy","meaning":"too ready to shoot","meaningCN":"动辄开枪的","example":"The compound keeps the gun sense alive in ordinary speech.","exampleCN":"这个复合词让枪的义项在日常说法里继续存活。"},{"word":"-ed","structure":"English past-tense and past-participle ending","meaning":"past or completed action","meaningCN":"过去或已完成的动作","example":"It forms triggered, the past and participle of the verb.","exampleCN":"它构成 triggered，即该动词的过去式与过去分词。"},{"word":"-ing","structure":"English present-participle and gerund ending","meaning":"ongoing action, or the act itself","meaningCN":"正在进行的动作，或行为本身","example":"It forms triggering, both participle and verbal noun.","exampleCN":"它构成 triggering，既是分词也是动名词。"}],"latinEntries":[],"derivatives":[{"word":"triggering","pos":"n./adj.","zh":"由该动词的现在分词转成的名词或形容词，义为「触发；引发性的」"},{"word":"triggered","pos":"adj.","zh":"由该动词的过去分词转成的形容词，义为「被触发的；受激的」"},{"word":"trigger-happy","pos":"adj.","zh":"由该名词与表示「热衷」的形容词合成为复合形容词，义为「动辄开枪的；莽撞行事的」"},{"word":"triggerable","pos":"adj.","zh":"由该动词加表示可能性的形容词尾构成，义为「可被触发的」"}]}},{"word":"undermine","ipa_uk":"/ˌʌndəˈmaɪn/","ipa_us":"/ˌʌndərˈmaɪn/","definition_zh":"削弱；暗中破坏；逐渐损毁根基；动摇（信心、权威）","definition_en":"to weaken something gradually from below, often secretly, by taking away what supports it","core_image":"老墙脚下，水从砖缝里一点点掏空泥沙，墙面看上去完好，根基却已经空了","scene":"老墙脚下，水从砖缝里一点点掏空泥沙，墙面看着完好，根基却已经空了。Constant leaks had begun to undermine the old wall.","sceneCN":"这里指从根基上逐渐削弱、掏空（第 1 个义项：损毁实物的基础）；句意为持续的渗漏已经开始逐渐损毁那面老墙。","pos":[{"tag":"v.","zh":"削弱；暗中破坏；逐渐损毁根基；动摇"}],"collocations":[{"phrase":"undermine confidence","zh":"削弱信心"},{"phrase":"undermine authority","zh":"动摇权威"},{"phrase":"undermine credibility","zh":"损害可信度"},{"phrase":"undermine an argument","zh":"削弱论点"},{"phrase":"undermine the foundations","zh":"损毁根基"},{"phrase":"undermine trust","zh":"破坏信任"},{"phrase":"undermine efforts","zh":"破坏努力"}],"forms":[{"label":"原形","form":"undermine"},{"label":"三单","form":"undermines"},{"label":"过去式","form":"undermined"},{"label":"过去分词","form":"undermined"},{"label":"现在分词","form":"undermining"},{"label":"名词（破坏）","form":"undermining"}],"derivatives":[{"word":"undermining","pos":"n./adj.","zh":"由该动词的现在分词转成的名词或形容词，义为「暗中破坏；起削弱作用的」"},{"word":"underminer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「暗中破坏者」"},{"word":"undermined","pos":"adj.","zh":"由该动词的过去分词转成的形容词，义为「已被削弱的；根基受损的」"}],"senses":[{"no":"01","title":"Hollow out a physical base","titleCN":"掏空实物根基","definition":"of water, digging or decay, to remove the material under a wall, road or building","definitionCN":"指水、挖掘或腐朽移除墙、路或建筑底下的材料","example":"Salt water can undermine the foundation of a bridge.","exampleCN":"盐水会逐渐掏空桥基。","why":"The word is literally under plus mine, so the first sense is the mining sense: taking the ground out from beneath a structure.","whyCN":"这个词字面上就是「在下」加「挖掘」，所以第一个义项就是采矿义：把结构底下的地基取走。"},{"no":"02","title":"Secretly damage a plan or effort","titleCN":"暗中破坏计划或努力","definition":"to weaken a plan, campaign or effort by quiet action rather than open opposition","definitionCN":"以暗中行动而非公开反对来削弱计划、行动或努力","example":"A few leaks were enough to undermine the plan.","exampleCN":"几次泄密就足以破坏那项计划。","why":"A tunnel dug under a defence does its work unseen, and the word kept that secrecy when it moved from walls to plans.","whyCN":"在防线底下挖的坑道在看不见处做工，这个词从墙转到计划时保留了那份隐秘。"},{"no":"03","title":"Weaken a person's confidence","titleCN":"削弱一个人的信心","definition":"to make someone steadily less sure of themselves or of a decision","definitionCN":"使某人对自己或某个决定逐渐失去把握","example":"Constant criticism undermined her confidence.","exampleCN":"不断的批评削弱了她的信心。","why":"Confidence stands on supports, and enough small attacks from below can make it sag without ever being hit directly.","whyCN":"信心立在支撑上，足够多来自下方的小攻击能让它下沉，却从未被直接击中。"},{"no":"04","title":"Shake an authority or position","titleCN":"动摇权威或地位","definition":"to make a leader, office or institution less respected and less able to act","definitionCN":"使领导者、职位或机构受到的尊重减少、行动能力下降","example":"The scandal undermined the minister's authority.","exampleCN":"丑闻动摇了那位部长的权威。","why":"Authority is a structure that stands on accepted ground, and removing that ground is the word's exact work.","whyCN":"权威是立在公认地基上的结构，而抽走那层地基正是这个词的确切工作。"},{"no":"05","title":"Damage a reputation","titleCN":"损害声誉","definition":"to lower the trust that others place in a person, company or brand","definitionCN":"降低他人对个人、公司或品牌的信任","example":"Rumours undermined the company's reputation.","exampleCN":"谣言损害了公司的声誉。","why":"A reputation is built from many small confirmations, so it can be undone from below without any single open attack.","whyCN":"声誉由许多小确认堆成，因此可以被下方一点点拆掉，而无需任何一次公开攻击。"},{"no":"06","title":"Weaken an argument","titleCN":"削弱论点的可靠性","definition":"to make a case less convincing by removing the support under one of its claims","definitionCN":"抽掉某个主张底下的支撑，使论证不那么令人信服","example":"One weak example undermined the whole argument.","exampleCN":"一个薄弱的例证削弱了整个论证。","why":"An argument is a building of reasons, and the word is used for taking a load-bearing stone out of it.","whyCN":"论证是由理由搭起的建筑，这个词就用来形容从中抽走一块承重的石头。"},{"no":"07","title":"Dig beneath a seam or deposit","titleCN":"在矿层下方挖掘","definition":"in mining, to cut a tunnel under a body of coal or ore so that it can be removed","definitionCN":"采矿中指在煤层或矿体下方开掘巷道以便采出","example":"Miners undermined the seam from a lower tunnel.","exampleCN":"矿工从下方的巷道掏挖那层煤层。","why":"This is the technical sense that keeps the two halves of the word visible: under, and mine.","whyCN":"这是让词的两个半截都保持可见的技术义：在下，以及挖掘。"},{"no":"08","title":"Sap physical strength","titleCN":"逐渐损耗体力","definition":"of illness, hunger or overwork, to wear down a person's strength slowly","definitionCN":"指疾病、饥饿或过劳缓慢损耗一个人的体力","example":"Illness had undermined his strength over the winter.","exampleCN":"疾病在冬天里一点点损耗了他的体力。","why":"The body also has foundations, and slow removal from below describes a decline that no single event explains.","whyCN":"身体也有根基，而从下方缓慢抽走，描述的是一种无法归因于单一事件的衰退。"},{"no":"09","title":"Break the ground under trust","titleCN":"破坏信任的基础","definition":"to make the trust between people or groups collapse through repeated small betrayals","definitionCN":"通过反复的小背叛使人或群体之间的信任崩塌","example":"Broken promises undermined the trust between them.","exampleCN":"屡次食言破坏了他们之间的信任。","why":"Trust rests on a floor of kept promises, and this word describes the floor being taken away one tile at a time.","whyCN":"信任铺在守诺的地板上，而这个词描述的就是地板被一块块抽走。"}],"etymology":{"intro":{"en":"Undermine is an English compound of under and mine. The first half is native Old English; the second came through Old French and its deeper origin is uncertain.","cn":"这个词是英语由「在下」与「矿、挖掘」构成的复合词。前半是本土古英语，后半经古法语而来，其更深来源不明。"},"items":[{"era":"OLD ENGLISH UNDER","en":"Under is a native preposition and prefix meaning below, and it has shaped hundreds of English compounds.","cn":"under 是本土介词与副词，意为在下方，它参与构成了数以百计的英语复合词。"},{"era":"OLD FRENCH MINE","en":"The noun meant a mine, an ore bed or a subterranean passage, and English borrowed it in the Middle Ages.","cn":"这个名词意为矿、矿层或地下通道，英语在中世纪借入。"},{"era":"MEDIEVAL LATIN MINA","en":"The written source is mina, but its own origin is uncertain; it may have come from a Celtic word for ore.","cn":"有记载的来源是 mina，但它自身的来源不明，可能来自某支凯尔特语中表示矿石的词。"},{"era":"ENGLISH UNDERMINE","en":"The verb first meant to dig under a wall or a fort so that it would fall; the military sense is the oldest recorded one.","cn":"这个动词最初意为在墙或堡垒底下挖掘使之倒塌；军事义是最早有记载的义项。"},{"era":"MODERN FIGURATIVE USE","en":"From digging under defences the word moved to weakening confidence, authority and trust; the date of each shift is uncertain.","cn":"从在防线底下挖掘，这个词转向削弱信心、权威与信任；每次转变的年代不确定。"},{"era":"MODERN MEDICAL USE","en":"Medicine uses it for slow declines of strength and immunity that no single cause can explain.","cn":"医学用它形容无法归因于单一原因的体力与免疫力缓慢衰退。"}]},"similar":{"note":{"en":"The first group looks or sounds like undermine; the second group names neighbouring ways of weakening something.","cn":"第一组在形音上与 undermine 相近；第二组是与「削弱、破坏」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"undermining","ipa":"/ˌʌndəˈmaɪnɪŋ/","tag":"same root","definition":"The act of weakening something from below or in secret.","definitionCN":"指从下方或暗中削弱某物的行为。"},{"word":"underminer","ipa":"/ˌʌndəˈmaɪnə/","tag":"same root","definition":"A person who quietly damages a plan or an authority.","definitionCN":"指暗中破坏计划或权威的人。"},{"word":"mine","ipa":"/maɪn/","tag":"same element","definition":"An excavation for ore, or the act of digging one; the second half of this word.","definitionCN":"指矿坑，或挖掘矿坑的行为；是本词的后半部分。"},{"word":"underground","ipa":"/ˌʌndəˈɡraʊnd/","tag":"different compound","definition":"Below the surface of the earth; it shares the prefix but not the mining verb.","definitionCN":"指地面之下；共享前缀，但不含那个挖掘动词。"},{"word":"undertake","ipa":"/ˌʌndəˈteɪk/","tag":"different compound","definition":"To take on a task; it shares the prefix but has an unrelated second half.","definitionCN":"指承担任务；共享前缀，但后半部分无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"weaken","ipa":"/ˈwiːkən/","tag":"near meaning","definition":"To make less strong; the broad word, with no image of digging or secrecy.","definitionCN":"指使变弱；最宽泛的词，不含挖掘或隐秘的意象。"},{"word":"erode","ipa":"/ɪˈrəʊd/","tag":"near meaning","definition":"To wear something away gradually by wind, water or friction; it stresses slow surface loss.","definitionCN":"指风、水或摩擦逐渐磨损；强调表面的缓慢流失。"},{"word":"sabotage","ipa":"/ˈsæbətɑːʒ/","tag":"near meaning","definition":"To damage something deliberately, usually from inside an organisation; it stresses intent.","definitionCN":"指故意破坏，通常从组织内部下手；强调意图。"},{"word":"subvert","ipa":"/səbˈvɜːt/","tag":"near meaning","definition":"To overturn an authority or system from within; it stresses turning the order upside down.","definitionCN":"指从内部颠覆权威或制度；强调把秩序翻过来。"},{"word":"impair","ipa":"/ɪmˈpeə/","tag":"near meaning","definition":"To reduce the function of something; it stresses loss of working ability rather than support.","definitionCN":"指降低某物的功能；强调工作能力的损失，而非支撑。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two visible halves, under and mine, and the image of ground removed from beneath.","cn":"正常联想利用两个看得见的半截——「在下」与「挖掘」，以及从底下抽走地面的意象。"},"normal":[{"en":"Say the two halves in order: under, then mine. The word is a tunnel dug beneath a wall.","cn":"按顺序念两个半截：先「在下」，再「挖掘」。这个词就是在墙底下挖的一条坑道。"},{"en":"A wall can look perfect from the street while the ground beneath it has already been taken away.","cn":"一面墙从街上看似完好，它底下的土却早已被掏走。"},{"en":"A rumour works like water in a brick joint: no hammer, but the joint gets wider.","cn":"谣言像砖缝里的水：没有锤子，缝却越来越宽。"},{"en":"The word is always gradual; it never means one clean blow.","cn":"这个词总是渐进的，从不指干净利落的一击。"},{"en":"The secret is part of the meaning: the damage is done where no one is looking.","cn":"隐秘是意义的一部分：破坏发生在没人看的地方。"}],"abstract":[{"en":"Undermining is the quiet form of opposition, and it is harder to answer than an open attack.","cn":"暗中破坏是反对的安静形式，比公开攻击更难回应。"},{"en":"Structures fail from below long before they fail from the front.","cn":"结构从下方失效，远早于它从正面失效。"},{"en":"What is undermined is not destroyed but left standing on nothing.","cn":"被掏空的东西不是被摧毁，而是被留在虚无之上继续立着。"}]},"examples":[{"en":"The constant flooding undermined the road's foundations.","cn":"反复的洪水损毁了那条路的地基。"},{"en":"His careless remarks undermined the peace talks.","cn":"他轻率的言论破坏了和谈。"},{"en":"Low pay undermines the morale of the whole team.","cn":"低薪削弱了整个团队的士气。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「安德曼」——「安德」是「在下」，在墙「曼」慢地挖，墙就从底下空了：暗中削弱","word":"undermine"},"root":"古英语 under「在下」+ 古法语 mine「矿、挖掘」→ 中古英语 undermine「在墙下挖坑道使之倒塌」→ 现代义「从根基上逐渐削弱、暗中破坏」；其中「矿」的更深来源不明，可能出自凯尔特语。","sensesIntro":{"en":"Nine senses keep one direction, from below and often unseen: a foundation, a plan, a confidence, an authority, a reputation, an argument, a coal seam, a body and the trust between people.","cn":"九个义项保持同一个方向——自下而上、常在暗处：地基、计划、信心、权威、声誉、论证、煤层、身体，以及人与人之间的信任。"},"semanticMap":{"core":{"en":"CORE IMAGE: water taking sand out of a brick joint until the wall stands on emptiness.","cn":"核心意象：水把砖缝里的沙一点点带走，直到墙立在空处。"},"chain":["HOLLOW OUT THE BASE","DIG FROM BELOW","WEAKEN CONFIDENCE","SHAKE AUTHORITY","BURN REPUTATION","BREAK TRUST"],"branches":[{"senses":"01 · 07","en":"THE PHYSICAL BASE BRANCH: water takes a bridge's foundation, and miners cut under a seam.","cn":"实物根基分支：水掏空桥基，矿工在煤层下方开挖。"},{"senses":"02 · 06","en":"THE PLAN AND ARGUMENT BRANCH: leaks damage a campaign and one weak example damages a case.","cn":"计划与论证分支：泄密破坏行动，一个薄弱例证破坏论证。"},{"senses":"03 · 08","en":"THE INNER STRENGTH BRANCH: criticism lowers confidence and illness lowers bodily strength.","cn":"内在力量分支：批评压低信心，疾病损耗体力。"},{"senses":"04","en":"THE AUTHORITY BRANCH: a scandal removes the ground a minister stands on.","cn":"权威分支：丑闻抽走部长脚下的地基。"},{"senses":"05 · 09","en":"THE REPUTATION AND TRUST BRANCH: rumours spoil a name and broken promises spoil a bond.","cn":"声誉与信任分支：谣言毁掉名声，食言毁掉纽带。"}]},"affixes":{"intro":{"en":"Undermine is a native prefix on a borrowed noun, and the join is so old that English speakers no longer feel the two parts separately.","cn":"这是一个本土前缀加在借来的名词上，接合得太久，英语使用者已不再分别感觉这两个部分。"},"latinIntro":{"en":"The second half reached English through Old French from Medieval Latin mina, a word of uncertain origin that may be Celtic.","cn":"后半部分经古法语、来自中世纪拉丁语 mina，这个词来源不明，可能出自凯尔特语。"},"items":[{"word":"under-","structure":"Old English prefix","meaning":"below, beneath","meaningCN":"在下方；在底下","example":"It fixes the direction of the damage from the start.","exampleCN":"它从一开始就定下破坏的方向。"},{"word":"mine","structure":"noun from Old French","meaning":"a pit for ore, a subterranean passage","meaningCN":"矿坑；地下通道","example":"The noun supplies the digging that the verb describes.","exampleCN":"这个名词提供动词所描述的挖掘动作。"},{"word":"mine","structure":"English verb converted from the noun","meaning":"to dig for ore","meaningCN":"挖掘矿石","example":"English turned the pit into an action without adding an ending.","exampleCN":"英语把这个坑直接变成动作，没有加词尾。"},{"word":"-ing","structure":"English gerund and participle ending","meaning":"the act or process of","meaningCN":"……的行为或过程","example":"It forms the noun for the slow work of weakening.","exampleCN":"它构成表示「缓慢削弱」这一工作的名词。"},{"word":"-er","structure":"English agent suffix","meaning":"one that does","meaningCN":"做某事者","example":"It names the person who digs from below.","exampleCN":"它命名从下方挖掘的人。"},{"word":"-ed","structure":"English past-tense and past-participle ending","meaning":"past or completed action","meaningCN":"过去或已完成的动作","example":"It forms undermined, a position already weakened.","exampleCN":"它构成 undermined，表示已被削弱的处境。"},{"word":"undermining","structure":"under- (below) + mine (dig) + -ing","meaning":"the act of weakening from below","meaningCN":"从下方逐渐削弱的行为","example":"The constant undermining of trust ruined the talks.","exampleCN":"对信任的持续侵蚀毁了会谈。"},{"word":"underminer","structure":"under- (below) + mine (dig) + -er","meaning":"one who digs from below or weakens in secret","meaningCN":"从下方挖掘或暗中削弱的人","example":"An underminer works out of sight.","exampleCN":"暗中破坏者在看不见的地方行事。"}],"latinEntries":[{"word":"mina","structure":"Medieval Latin noun, origin uncertain","meaning":"mine, ore pit","meaningCN":"矿；矿坑"}],"derivatives":[{"word":"undermining","pos":"n./adj.","zh":"由该动词的现在分词转成的名词或形容词，义为「暗中破坏；起削弱作用的」"},{"word":"underminer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「暗中破坏者」"},{"word":"undermined","pos":"adj.","zh":"由该动词的过去分词转成的形容词，义为「已被削弱的；根基受损的」"}]}},{"word":"undergo","ipa_uk":"/ˌʌndəˈɡəʊ/","ipa_us":"/ˌʌndərˈɡoʊ/","definition_zh":"经历；经受；接受（治疗、检查）；遭受；接受（训练、改造）","definition_en":"to pass through an experience, treatment or change that is imposed on you rather than chosen","core_image":"车间里，传送带把矿石送进炉口，石头在里面被烧、被压、被淬，出来时已经换了样子","scene":"车间里，传送带把矿石送进炉口，石头在里面被烧、被压、被淬，出来时已换了样子。Every new worker must undergo three weeks of training.","sceneCN":"这里指经历、接受某种过程（第 1 个义项：经历一个被安排的过程）；句意为每个新员工都必须接受为期三周的训练。","pos":[{"tag":"v.","zh":"经历；经受；接受；遭受"}],"collocations":[{"phrase":"undergo training","zh":"接受训练"},{"phrase":"undergo surgery","zh":"接受手术"},{"phrase":"undergo a change","zh":"经历变化"},{"phrase":"undergo tests","zh":"接受检测"},{"phrase":"undergo scrutiny","zh":"受到审查"},{"phrase":"undergo repairs","zh":"接受维修"},{"phrase":"undergo hardship","zh":"经受困苦"}],"forms":[{"label":"原形","form":"undergo"},{"label":"三单","form":"undergoes"},{"label":"过去式","form":"underwent"},{"label":"过去分词","form":"undergone"},{"label":"现在分词","form":"undergoing"},{"label":"名词（经历者）","form":"undergoer"}],"derivatives":[{"word":"undergoer","pos":"n.","zh":"由该动词加表示施动者或承受者的名词尾构成，义为「经历者；受事者」"},{"word":"undergoing","pos":"n./adj.","zh":"由该动词的现在分词转成的名词或形容词，义为「经历；正在经受的」"}],"senses":[{"no":"01","title":"Pass through a process","titleCN":"经历一个过程","definition":"to be carried through a process that changes the subject in some way","definitionCN":"被带过一个过程，使主体在某方面发生改变","example":"The old town will undergo great changes within a decade.","exampleCN":"这座老城在十年内将经历巨大变化。","why":"The word is under plus go, and the subject goes through the experience rather than arranging it.","whyCN":"这个词是「在下」加「走」，主语是从这段经历里走过去，而不是安排它。"},{"no":"02","title":"Bear pain or hardship","titleCN":"经受痛苦或困苦","definition":"to endure suffering, difficulty or an unpleasant experience over a period","definitionCN":"在一段时间里忍受痛苦、困难或不愉快的经历","example":"The refugees had to undergo months of hardship.","exampleCN":"难民们不得不经受数月的困苦。","why":"Going under a burden is the old picture, and the word does not promise that the experience will be pleasant.","whyCN":"走到重担之下是旧的意象，这个词并不承诺这段经历会愉快。"},{"no":"03","title":"Receive medical treatment","titleCN":"接受医疗","definition":"to have an operation, course of drugs or other treatment performed on one's body","definitionCN":"让手术、疗程或其他治疗在自己的身体上进行","example":"She must undergo surgery on her knee.","exampleCN":"她必须接受膝部手术。","why":"The patient is the one who goes through the procedure; the surgeon is the one who performs it.","whyCN":"病人是走过程序的那一方，外科医生是施行程序的那一方。"},{"no":"04","title":"Be put through a test or check","titleCN":"接受检测或检查","definition":"to be examined, measured or tested by an official or technical procedure","definitionCN":"被官方或技术程序检验、测量或测试","example":"Every machine must undergo a safety check each year.","exampleCN":"每台机器每年都必须接受安全检查。","why":"A test is a passage the object is made to go through, and the word keeps the object passive.","whyCN":"检测是让对象走过去的一道通道，这个词让对象保持被动。"},{"no":"05","title":"Suffer a loss or decline","titleCN":"遭受损失或下降","definition":"to experience a fall in value, health or amount that one did not choose","definitionCN":"经历并非自己选择的财富、健康或数量上的下降","example":"The company did not undergo any loss last year.","exampleCN":"公司去年没有遭受任何损失。","why":"Loss is something that happens to a subject, and the grammar of the word marks that subject as the receiver.","whyCN":"损失是发生在主体身上的事，这个词的语法把主体标成接受者。"},{"no":"06","title":"Receive training or instruction","titleCN":"接受训练或指导","definition":"to go through a course of training, lessons or preparation","definitionCN":"走完一段训练、课程或准备","example":"New staff undergo two weeks of training.","exampleCN":"新员工要接受两周培训。","why":"Training is a passage that changes the person who walks it, and the word describes the walking, not the teaching.","whyCN":"训练是一段改变走过者的通道，这个词描述的是走，而不是教。"},{"no":"07","title":"Be subjected to scrutiny","titleCN":"受到审查","definition":"to have one's actions, records or motives examined closely by others","definitionCN":"让自己的行为、记录或动机受到他人仔细检查","example":"The proposal will undergo close scrutiny.","exampleCN":"这项提案将受到严密审查。","why":"Scrutiny is an uncomfortable passage, and the word makes clear that the subject does not control the examining.","whyCN":"审查是一段不舒服的通道，这个词明确表示主体并不能控制这场检查。"},{"no":"08","title":"Be transformed in form","titleCN":"经历形态上的转变","definition":"of a substance or system, to pass through a process that alters its state","definitionCN":"指物质或系统走过一个改变其状态的过程","example":"The neighbourhood is beginning to undergo a slow transformation.","exampleCN":"这个街区正开始经历缓慢的转变。","why":"Ore entering a furnace is changed by the passage itself, which is the clearest image of the word.","whyCN":"矿石进入炉子，被这段通道本身改变，这是这个词最清晰的意象。"},{"no":"09","title":"Receive repairs or alterations","titleCN":"接受维修或改装","definition":"of a building, vehicle or machine, to have repair or modification done to it","definitionCN":"指建筑、车辆或机器被施加维修或改装","example":"The bridge will undergo repairs next spring.","exampleCN":"这座桥将在明年春天接受维修。","why":"The object does not repair itself; it is put through a workshop process, and English uses the same verb.","whyCN":"物体不会自己修自己，它是被送过一段工坊流程，英语用的是同一个动词。"}],"etymology":{"intro":{"en":"Undergo is native Old English, undergan, from under plus gan, to go. It has no Latin ancestor and its past forms went, gone are irregular.","cn":"这个词是本土古英语 undergan，由 under「在下」与 gan「走」构成。它没有拉丁语祖先，其过去式与过去分词属于不规则变化。"},"items":[{"era":"OLD ENGLISH GAN","en":"Gan meant to go, and it is the ancestor of the modern verb go, one of the oldest verbs in the language.","cn":"gan 意为走，是现代动词 go 的祖先，也是这门语言里最古老的动词之一。"},{"era":"OLD ENGLISH UNDERGĀN","en":"The compound meant to go under or pass beneath, and it could describe both a road and an experience.","cn":"这个复合词意为走到下面、从底下经过，既能描述道路，也能描述经历。"},{"era":"MIDDLE ENGLISH UNDERGON","en":"The middle form kept the sense of passing through, and it widened from space to events.","cn":"中古形式保留了「穿过」的意思，并从空间扩展到事件。"},{"era":"EARLY MODERN UNDERGO","en":"By the early modern period the word was fixed in the sense of enduring or being subjected to something.","cn":"到近代早期，这个词已固定为「忍受」或「被施加某事」的意思。"},{"era":"MODERN MEDICAL USE","en":"Medicine made the word a standard verb for operations, tests and treatment: the patient undergoes them.","cn":"医学使这个词成为手术、检查与治疗的标准动词：病人接受它们。"},{"era":"MODERN ADMINISTRATIVE USE","en":"Administration extended it to inspections, repairs, reviews and training, always with the subject on the receiving side.","cn":"行政语言把它扩展到检查、维修、评审与培训，主语始终处在接受的一方。"}]},"similar":{"note":{"en":"The first group looks or sounds like undergo; the second group names neighbouring ideas of living through something.","cn":"第一组在形音上与 undergo 相近；第二组是与「经历、承受」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"undergoes","ipa":"/ˌʌndəˈɡəʊz/","tag":"same root","definition":"The third person singular form of the verb.","definitionCN":"该动词的第三人称单数形式。"},{"word":"underwent","ipa":"/ˌʌndəˈwent/","tag":"same root","definition":"The past form of the verb.","definitionCN":"该动词的过去式。"},{"word":"undergone","ipa":"/ˌʌndəˈɡɒn/","tag":"same root","definition":"The past participle of the verb.","definitionCN":"该动词的过去分词。"},{"word":"undertake","ipa":"/ˌʌndəˈteɪk/","tag":"different word","definition":"To take on a task oneself; it shares the prefix but reverses the direction of agency.","definitionCN":"指自己承担一项任务；共享前缀，但主动方向相反。"},{"word":"underground","ipa":"/ˌʌndəˈɡraʊnd/","tag":"different word","definition":"Below the surface; it shares the prefix and a travel image but not the meaning.","definitionCN":"指地面之下；共享前缀与行走意象，但意义不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"experience","ipa":"/ɪkˈspɪəriəns/","tag":"near meaning","definition":"To live through an event and be affected by it; broader and less formal than undergo.","definitionCN":"指经历一件事并受影响；比本词更宽泛、更不正式。"},{"word":"endure","ipa":"/ɪnˈdjʊə/","tag":"near meaning","definition":"To bear something painful over time; it stresses duration and strength.","definitionCN":"指长时间承受痛苦；强调持续与力量。"},{"word":"suffer","ipa":"/ˈsʌfə/","tag":"near meaning","definition":"To feel pain or loss; it always carries a negative judgement.","definitionCN":"指感到痛苦或损失；总带负面判断。"},{"word":"be subjected to","ipa":"/biː səbˈdʒektɪd tuː/","tag":"near meaning","definition":"To be made to experience something by someone else; it states the outside agent openly.","definitionCN":"指被他人安排去经历某事；把外部施动者明说出来。"},{"word":"go through","ipa":"/ɡəʊ θruː/","tag":"near meaning","definition":"To pass through an experience; the everyday phrase that matches the word's image.","definitionCN":"指走过一段经历；是与本词意象最贴合的日常说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two native halves, the irregular past forms and the passive direction of the word.","cn":"正常联想利用两个本土半截、不规则的过去形式，以及这个词的被动方向。"},"normal":[{"en":"The word says go under, and the subject is the one who goes under the process, not the one who runs it.","cn":"这个词说「走到下面」，主语是从过程下面走过去的人，而不是运行过程的人。"},{"en":"A patient undergoes surgery; a surgeon performs it. Keep the two verbs apart.","cn":"病人接受手术，外科医生施行手术。要把这两个动词分开。"},{"en":"The past forms went and gone come from the old verb of going, so the middle of the word changes and the under stays.","cn":"过去形式来自古老的「走」动词，所以词的中间变化，而「在下」那一截不动。"},{"en":"Ore in a furnace is the picture: the passage, not the ore, does the changing.","cn":"炉中的矿石就是那幅图：起作用的是通道，而不是矿石。"},{"en":"Undergo is passive in grammar even when it has an object: you undergo a test because the test is applied to you.","cn":"这个词即使带宾语，语法上也是被动的：你接受检测，是因为检测被施加于你。"}],"abstract":[{"en":"Undergo marks the line between what a person chooses and what a person lives through.","cn":"这个词标出「人选择的事」与「人熬过的事」之间的界线。"},{"en":"A process that can be undergone is a process that leaves a mark.","cn":"能被经历的过程，都是会留下痕迹的过程。"},{"en":"The word asks for patience rather than action; it describes the position of the one acted upon.","cn":"这个词要求的是耐心而非行动；它描述的是被作用者的位置。"}]},"examples":[{"en":"The building will undergo a complete restoration.","cn":"这座建筑将接受一次全面修复。"},{"en":"Patients undergo a series of tests before the operation.","cn":"病人在手术前要接受一系列检查。"},{"en":"The region has undergone rapid economic change.","cn":"该地区经历了快速的经济变化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「安德狗」——「安德」是「在下」，一条狗从下面钻过去，被水淋了一身：经历、经受","word":"undergo"},"root":"古英语 under「在下」+ gān「走」→ undergān「从下面走过、经历」→ 中古英语 undergon → 现代 undergo「经历；经受；接受」；与拉丁语无涉，过去式与过去分词为不规则形式。","sensesIntro":{"en":"Nine senses all place the subject on the receiving side: a process, pain, surgery, a test, a loss, training, scrutiny, transformation and repairs.","cn":"九个义项都把主语放在接受的一方：过程、痛苦、手术、检测、损失、训练、审查、转变与维修。"},"semanticMap":{"core":{"en":"CORE IMAGE: ore on a belt entering the furnace and coming out changed.","cn":"核心意象：矿石随传送带进入炉口，出来时已经变了。"},"chain":["PASS THROUGH","BEAR THE PAIN","ACCEPT TREATMENT","FACE A TEST","LOSE SOMETHING","CHANGE FORM"],"branches":[{"senses":"01 · 08","en":"THE PASSAGE BRANCH: a town goes through change, and a district goes through a slow transformation.","cn":"通道分支：城市走过变化，街区走过缓慢的转变。"},{"senses":"02 · 05","en":"THE BURDEN BRANCH: refugees bear hardship, and a firm bears a loss.","cn":"重担分支：难民经受困苦，公司遭受损失。"},{"senses":"03 · 09","en":"THE TREATMENT AND REPAIR BRANCH: a patient receives surgery, and a bridge receives repairs.","cn":"治疗与维修分支：病人接受手术，桥梁接受维修。"},{"senses":"04 · 07","en":"THE EXAMINATION BRANCH: a machine faces a safety check, and a proposal faces scrutiny.","cn":"检查分支：机器接受安全检查，提案受到审查。"},{"senses":"06","en":"THE TRAINING BRANCH: new staff walk through two weeks of instruction.","cn":"训练分支：新员工走完两周的指导。"}]},"affixes":{"intro":{"en":"Undergo is a native compound of a preposition and a verb of going, with no borrowed parts at all.","cn":"这是一个本土复合词，由一个介词与一个表示「走」的动词构成，完全没有借来的部件。"},"latinIntro":{"en":"There is no Latin etymon behind this word; both halves are Germanic, so the Latin entries are left empty.","cn":"这个词背后没有拉丁语词源，两个半截都属日耳曼语，因此拉丁语条目留空。"},"items":[{"word":"under-","structure":"Old English prefix","meaning":"below, beneath","meaningCN":"在下方；在底下","example":"It places the subject beneath the process rather than above it.","exampleCN":"它把主语放在过程之下，而不是之上。"},{"word":"gān","structure":"Old English verb","meaning":"to go","meaningCN":"走；行走","example":"The old verb survives as the modern go.","exampleCN":"这个古老动词以现代形式继续存在。"},{"word":"-er","structure":"English agent or patient suffix","meaning":"one that does or undergoes","meaningCN":"做某事者；承受某事者","example":"It forms the rare noun for the one who experiences.","exampleCN":"它构成表示「经历者」的罕见名词。"},{"word":"-ing","structure":"English gerund ending","meaning":"the act or process of","meaningCN":"……的行为或过程","example":"It forms the noun for the experience itself.","exampleCN":"它构成表示「经历」本身的名词。"},{"word":"go","structure":"modern English verb, from Old English gān","meaning":"to move, travel","meaningCN":"走；行进","example":"The second half of undergo is this everyday verb.","exampleCN":"undergo 的后半部分就是这个日常动词。"},{"word":"-en","structure":"English past-participle ending, as in taken and gone","meaning":"completed action in a participle","meaningCN":"分词中已完成的动作","example":"It appears in undergone, the participle of undergo.","exampleCN":"它出现在 undergone，即 undergo 的过去分词。"},{"word":"underwent","structure":"under- (below) + went (past of go)","meaning":"experienced in the past","meaningCN":"过去经历过","example":"The patient underwent two operations.","exampleCN":"病人接受过两次手术。"},{"word":"undergone","structure":"under- (below) + gone (past participle of go)","meaning":"experienced, as a completed state","meaningCN":"已经历，作为完成状态","example":"The building has undergone extensive repairs.","exampleCN":"这座建筑已经历大规模修缮。"}],"latinEntries":[],"derivatives":[{"word":"undergoer","pos":"n.","zh":"由该动词加表示施动者或承受者的名词尾构成，义为「经历者；受事者」"},{"word":"undergoing","pos":"n./adj.","zh":"由该动词的现在分词转成的名词或形容词，义为「经历；正在经受的」"}]}},{"word":"undertake","ipa_uk":"/ˌʌndəˈteɪk/","ipa_us":"/ˌʌndərˈteɪk/","definition_zh":"承担；着手做；承诺；从事；接受（挑战、风险）","definition_en":"to take on a task, responsibility or obligation, and formally to promise to do it","core_image":"会议室里，一个人把一摞图纸和账本一起抱起来，在合同末尾签下名字，从此这些活都落在他肩上","scene":"会议室里，一个人把一摞图纸和账本一起抱起来，在合同末尾签下名字，从此这些活都落在他肩上。The firm agreed to undertake the whole repair of the bridge.","sceneCN":"这里指承担一项工程（第 2 个义项：承担责任或工程）；句意为该公司同意承担这座桥的全部维修工作。","pos":[{"tag":"v.","zh":"承担；着手做；承诺；从事"}],"collocations":[{"phrase":"undertake a task","zh":"承担一项任务"},{"phrase":"undertake a project","zh":"承担一个项目"},{"phrase":"undertake research","zh":"开展研究"},{"phrase":"undertake a review","zh":"进行评审"},{"phrase":"undertake repairs","zh":"承担维修"},{"phrase":"undertake to do something","zh":"承诺做某事"},{"phrase":"undertake a risk","zh":"承担风险"}],"forms":[{"label":"原形","form":"undertake"},{"label":"三单","form":"undertakes"},{"label":"过去式","form":"undertook"},{"label":"过去分词","form":"undertaken"},{"label":"现在分词","form":"undertaking"},{"label":"名词（任务）","form":"undertaking"}],"derivatives":[{"word":"undertaking","pos":"n.","zh":"由该动词的现在分词转成的名词，义为「任务；事业；承诺」"},{"word":"undertaker","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，原义为「承担者」，现代常指「殡葬承办人」"}],"senses":[{"no":"01","title":"Begin a task","titleCN":"着手进行一项任务","definition":"to start work on something that needs time and effort","definitionCN":"开始从事需要时间与精力的工作","example":"She agreed to undertake the survey alone.","exampleCN":"她同意独自承担这项调查。","why":"The word is under plus take, and taking a task up is the active mirror of undergoing it.","whyCN":"这个词是「在下」加「拿取」，把任务拿起来，正是「经历」的主动镜像。"},{"no":"02","title":"Accept responsibility for work","titleCN":"承担责任或工程","definition":"to make oneself the person answerable for a piece of work","definitionCN":"使自己成为某项工作负责的人","example":"The firm agreed to undertake the whole repair of the bridge.","exampleCN":"该公司同意承担这座桥的全部维修工作。","why":"Taking a job under one's own name is the commercial core of the word: the burden is accepted, not merely received.","whyCN":"把工作接到自己名下，是这个词的商业核心：重担是被接受下来的，而不只是被收到。"},{"no":"03","title":"Promise formally to do something","titleCN":"正式承诺做某事","definition":"to bind oneself by a promise, especially in a contract or an official statement","definitionCN":"以承诺约束自己，尤指在合同或官方声明中","example":"The supplier undertakes to deliver within three days.","exampleCN":"供应商承诺在三天内交货。","why":"In legal English the word means a binding promise, because a promise taken up is a duty laid on oneself.","whyCN":"在法律英语里这个词指有约束力的承诺，因为被接下的承诺就是加在自己身上的义务。"},{"no":"04","title":"Carry out a study or inquiry","titleCN":"从事研究或调查","definition":"to conduct research, an inquiry or a systematic piece of academic work","definitionCN":"开展研究、调查或系统的学术工作","example":"They plan to undertake research on coastal erosion.","exampleCN":"他们计划开展海岸侵蚀研究。","why":"Research is a long task that someone must take up, and the word marks the person who accepts its length.","whyCN":"研究是一项必须有人接下的长期任务，这个词标出接受其长度的那个人。"},{"no":"05","title":"Accept a risk or a cost","titleCN":"承担风险或费用","definition":"to agree to bear the possible loss or expense of an action","definitionCN":"同意承受某一行动可能带来的损失或开支","example":"No one wanted to undertake the risk of the first flight.","exampleCN":"没有人愿意承担首次飞行的风险。","why":"A risk is a weight one lifts onto one's own shoulders, which is exactly the picture the compound draws.","whyCN":"风险是被抬到自己肩上的一份重量，这正是这个复合词画出的图。"},{"no":"06","title":"Take on a challenge","titleCN":"接受挑战","definition":"to accept a difficult task with the intention of seeing it through","definitionCN":"接受一项困难任务，并打算把它做到底","example":"She was ready to undertake the challenge.","exampleCN":"她准备好接受这项挑战。","why":"The word carries will: unlike undergo, it names a choice to pick the difficulty up.","whyCN":"这个词带着意志：与「经历」不同，它命名的正是把困难拾起来的选择。"},{"no":"07","title":"Be answerable for a project","titleCN":"负责一个项目","definition":"to hold the leading responsibility for a plan from start to finish","definitionCN":"从开始到结束对一个计划负主要责任","example":"The department will undertake the project next year.","exampleCN":"该部门明年将负责这个项目。","why":"A project has one neck under it in ordinary speech, and this word is the formal way to name that neck.","whyCN":"日常说法里，一个项目底下压着一个人的脖子，而这个词是命名那个脖子的正式方式。"},{"no":"08","title":"Take on an office or role","titleCN":"担任职务或角色","definition":"to accept a post, duty or function and begin to act in it","definitionCN":"接受一个职位、职责或职能并开始履行","example":"He agrees to undertake the role of treasurer.","exampleCN":"他同意担任财务主管一职。","why":"A role is taken up like a tool, and the person who takes it becomes responsible for what it requires.","whyCN":"角色像工具一样被拿起，拿起它的人便对它所要求的事负起责任。"},{"no":"09","title":"Contract to provide a service","titleCN":"承揽一项服务","definition":"of a company, to sign a contract to carry out work for a client","definitionCN":"指公司签约为客户完成工作","example":"The company will undertake the contract for the new line.","exampleCN":"该公司将承揽这条新线路的合同。","why":"Business English uses the word for the moment a firm takes a job into its own books.","whyCN":"商业英语用这个词指一家公司把一项工作接进自己账本的那一刻。"}],"etymology":{"intro":{"en":"Undertake is native Old English, undertacan, from under plus tacan, to take. It has no Latin ancestor and its past forms are irregular.","cn":"这个词是本土古英语 undertacan，由 under「在下」与 tacan「拿取」构成。它没有拉丁语祖先，过去形式不规则。"},"items":[{"era":"OLD ENGLISH TACAN","en":"Tacan meant to take or grasp, and it is the ancestor of the modern verb take.","cn":"tacan 意为拿取或抓住，是现代动词 take 的祖先。"},{"era":"OLD ENGLISH UNDERTACAN","en":"The compound meant to take something upon oneself, often a duty or a burden.","cn":"这个复合词意为把某事接到自己身上，常指职责或重担。"},{"era":"MIDDLE ENGLISH UNDERTAKE","en":"The middle form kept the sense of taking a task in hand and began to appear in promises.","cn":"中古形式保留了「把任务接到手里」的意思，并开始出现在承诺里。"},{"era":"ENGLISH LEGAL SENSE","en":"In legal writing the verb became a fixed formula for binding oneself to perform.","cn":"在法律写作中，这个动词成为约束自己履行义务的固定说法。"},{"era":"MODERN BUSINESS USE","en":"Commerce extended it to contracts, projects and services that a firm takes into its books.","cn":"商业把它扩展到公司接进自己账本的合同、项目与服务。"},{"era":"MODERN ACADEMIC USE","en":"Universities made undertake the standard verb for beginning a study or an inquiry.","cn":"大学把这个词定为开始一项研究或调查的标准动词。"}]},"similar":{"note":{"en":"The first group looks or sounds like undertake; the second group names neighbouring ways of taking something on.","cn":"第一组在形音上与 undertake 相近；第二组是与「承担、接手」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"undertaking","ipa":"/ˌʌndəˈteɪkɪŋ/","tag":"same root","definition":"A task, enterprise or formal promise that one has taken on.","definitionCN":"指已承担的任务、事业或正式承诺。"},{"word":"undertaker","ipa":"/ˌʌndəˈteɪkə/","tag":"same root","definition":"One who takes on a task; in modern use, a funeral director.","definitionCN":"指承担事务者；现代常指殡葬承办人。"},{"word":"take","ipa":"/teɪk/","tag":"same element","definition":"To grasp or receive; the second half of this word.","definitionCN":"指拿取或接收；是本词的后半部分。"},{"word":"undergo","ipa":"/ˌʌndəˈɡəʊ/","tag":"different word","definition":"To experience something imposed on you; it shares the prefix but reverses the direction of agency.","definitionCN":"指经历被施加于自己的事；共享前缀，但主动方向相反。"},{"word":"overtake","ipa":"/ˌəʊvəˈteɪk/","tag":"different compound","definition":"To catch up with and pass another; it shares the take verb with a different prefix.","definitionCN":"指追上并超过另一者；共享「拿取」动词，前缀不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assume","ipa":"/əˈsjuːm/","tag":"near meaning","definition":"To take a duty or role as one's own, often without a formal promise.","definitionCN":"指把职责或角色接为自己所有，常无正式承诺。"},{"word":"take on","ipa":"/teɪk ɒn/","tag":"near meaning","definition":"To accept work or a responsibility; the everyday phrase, less formal than undertake.","definitionCN":"指接受工作或责任；日常说法，不如本词正式。"},{"word":"embark on","ipa":"/ɪmˈbɑːk ɒn/","tag":"near meaning","definition":"To begin a large project or journey, with the image of boarding a ship.","definitionCN":"指开始大工程或旅程，意象是登船。"},{"word":"shoulder","ipa":"/ˈʃəʊldə/","tag":"near meaning","definition":"To carry a burden or responsibility, with the physical image of lifting it onto the shoulder.","definitionCN":"指扛起负担或责任，带有把它抬上肩膀的身体意象。"},{"word":"accept","ipa":"/əˈsept/","tag":"near meaning","definition":"To agree to receive or take on something offered; it stresses the consent more than the work.","definitionCN":"指同意接受被提供之物；强调同意，而非工作本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two halves, the contrast with undergo and the idea of a burden taken onto oneself.","cn":"正常联想利用两个半截、与「经历」的对比，以及「把重担接到自己身上」的意思。"},"normal":[{"en":"The word says take under, so picture a person putting a load under his own arm and carrying it.","cn":"这个词说「拿到下面」，于是想象一个人把重物夹到自己臂下并搬走。"},{"en":"Undergo is what happens to you; undertake is what you agree to do. The second half decides the direction.","cn":"经历是发生在你身上的事，承担是你同意去做的事；后半截决定了方向。"},{"en":"A signature at the end of a contract is the modern picture of the word.","cn":"合同末尾的一个签名，就是这个词的现代图像。"},{"en":"A researcher undertakes a study the way a climber undertakes a route: both accept the length of it.","cn":"研究者开展研究，就像攀登者选择一条路线：两者都接受了它的长度。"},{"en":"The noun undertaking can mean a task, an enterprise or a promise, because all three are things taken up.","cn":"名词形式既可指任务、事业，也可指承诺，因为三者都是被接起来的东西。"}],"abstract":[{"en":"To undertake is to make one's own will the first cause of the work.","cn":"承担，就是把自身的意志变成这项工作的第一原因。"},{"en":"Responsibility here is not given; it is picked up and carried.","cn":"这里的责任不是被发给的，而是被拾起并搬运的。"},{"en":"Every undertaking fixes a future obligation in the present tense.","cn":"每一项承担都在现在时里固定了一项未来的义务。"}]},"examples":[{"en":"The team will undertake a full safety review.","cn":"团队将进行一次全面的安全评审。"},{"en":"She undertakes to finish the report by Monday.","cn":"她承诺在周一之前完成报告。"},{"en":"Few banks would undertake such a risky loan.","cn":"很少有银行愿意承担这样一笔高风险贷款。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「安德泰克」——「安德」是「在下」，把担子「泰」然放到肩「克」上，就是承担","word":"undertake"},"root":"古英语 under「在下」+ tacan「拿取」→ undertacan「把某事接到自己身上」→ 中古英语 undertake → 现代义「承担；着手做；承诺」；与拉丁语无涉，过去式与过去分词为不规则形式。","sensesIntro":{"en":"Nine senses all show someone actively picking something up: a task, responsibility, a promise, research, risk, challenge, project, role and contract.","cn":"九个义项都表示某人主动把东西接起来：任务、责任、承诺、研究、风险、挑战、项目、职务与合同。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person lifting drawings and ledgers together and signing at the bottom of a contract.","cn":"核心意象：一个人把图纸与账本一起抱起，并在合同末尾签名。"},"chain":["TAKE UP A TASK","ACCEPT RESPONSIBILITY","PROMISE TO DO","START A PROJECT","CARRY THE RISK","TAKE A ROLE"],"branches":[{"senses":"01 · 04","en":"THE TASK BRANCH: a survey is begun, and a research programme is opened.","cn":"任务分支：调查被开始，研究计划被开启。"},{"senses":"02 · 07","en":"THE RESPONSIBILITY BRANCH: a firm takes the repair, and a department takes the project.","cn":"责任分支：公司接下维修，部门接下项目。"},{"senses":"03","en":"THE PROMISE BRANCH: a supplier binds itself to a delivery date.","cn":"承诺分支：供应商以交货日期约束自己。"},{"senses":"05 · 06","en":"THE RISK AND CHALLENGE BRANCH: someone accepts the first flight's danger and the difficulty of the task.","cn":"风险与挑战分支：有人接受首飞的危险，也接受任务的难度。"},{"senses":"08 · 09","en":"THE ROLE AND CONTRACT BRANCH: a treasurer takes an office, and a company takes a contract.","cn":"职务与合同分支：财务主管接任职位，公司承揽合同。"}]},"affixes":{"intro":{"en":"Undertake is a native compound of under and take, and its two halves are still transparent to any English speaker.","cn":"这是一个由「在下」与「拿取」构成的本土复合词，两个半截对任何英语使用者都仍然透明。"},"latinIntro":{"en":"There is no Latin etymon behind this word; both halves are Germanic, so the Latin entries are left empty.","cn":"这个词背后没有拉丁语词源，两个半截都属日耳曼语，因此拉丁语条目留空。"},"items":[{"word":"under-","structure":"Old English prefix","meaning":"below, beneath","meaningCN":"在下方；在底下","example":"It pictures the load placed under the body.","exampleCN":"它画出重物被放在身体下方的样子。"},{"word":"tacan","structure":"Old English verb","meaning":"to take, grasp","meaningCN":"拿取；抓住","example":"The old verb survives as the modern take.","exampleCN":"这个古老动词以现代形式继续存在。"},{"word":"take","structure":"modern English verb","meaning":"to grasp, receive","meaningCN":"拿取；接收","example":"The second half supplies the act of accepting.","exampleCN":"后半部分提供「接受」这个动作。"},{"word":"-ing","structure":"English gerund ending","meaning":"the act or result of","meaningCN":"……的行为或结果","example":"It forms the noun for a task or an enterprise.","exampleCN":"它构成表示「任务或事业」的名词。"},{"word":"-er","structure":"English agent suffix","meaning":"one that does","meaningCN":"做某事者","example":"It names the one who takes a task upon himself.","exampleCN":"它命名把任务接到自己身上的人。"},{"word":"undertook","structure":"under- (below) + took (past of take)","meaning":"took a task upon oneself in the past","meaningCN":"过去承担了某项任务","example":"The firm undertook the whole survey.","exampleCN":"这家公司承担了整项勘测。"},{"word":"undertaken","structure":"under- (below) + taken (past participle of take)","meaning":"taken upon oneself, as a completed act","meaningCN":"已被承担，作为完成动作","example":"The repairs have been undertaken at last.","exampleCN":"修缮终于被承担起来。"},{"word":"-en","structure":"English past-participle ending, as in taken","meaning":"completed action in a participle","meaningCN":"分词中已完成的动作","example":"It appears in undertaken, the participle of undertake.","exampleCN":"它出现在 undertaken，即 undertake 的过去分词。"}],"latinEntries":[],"derivatives":[{"word":"undertaking","pos":"n.","zh":"由该动词的现在分词转成的名词，义为「任务；事业；承诺」"},{"word":"undertaker","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，原义为「承担者」，现代常指「殡葬承办人」"}]}},{"word":"utilize","ipa_uk":"/ˈjuːtəlaɪz/","ipa_us":"/ˈjuːtəlaɪz/","definition_zh":"利用；使用；发挥……的效用；开发（资源）","definition_en":"to make practical use of something, especially in a way that puts it to productive purpose","core_image":"车间角落堆着旧木箱，一个人把它们拆开、刨平，重新钉成一排货架","scene":"车间角落堆着旧木箱，一个人把它们拆开、刨平，重新钉成一排货架。The workshop utilized old crates to build new shelves.","sceneCN":"这里指把某物派上用场、加以利用（第 1 个义项：实际利用材料或资源）；句意为工坊利用旧木箱做了新货架。","pos":[{"tag":"v.","zh":"利用；使用；发挥效用；开发"}],"collocations":[{"phrase":"utilize resources","zh":"利用资源"},{"phrase":"utilize space","zh":"利用空间"},{"phrase":"utilize data","zh":"利用数据"},{"phrase":"utilize one's potential","zh":"发挥潜力"},{"phrase":"utilize a technique","zh":"运用一种技术"},{"phrase":"fully utilize","zh":"充分利用"},{"phrase":"utilize existing equipment","zh":"利用现有设备"}],"forms":[{"label":"原形","form":"utilize"},{"label":"三单","form":"utilizes"},{"label":"过去式","form":"utilized"},{"label":"过去分词","form":"utilized"},{"label":"现在分词","form":"utilizing"},{"label":"名词（利用）","form":"utilization"}],"derivatives":[{"word":"utilization","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「利用；使用」"},{"word":"utilizer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「利用者」"},{"word":"utilizable","pos":"adj.","zh":"由该动词加表示可能性的形容词尾构成，义为「可利用的」"},{"word":"underutilize","pos":"v.","zh":"由表示「不足」的前缀加该动词构成，义为「未充分利用」"},{"word":"underutilization","pos":"n.","zh":"由前一词加表示动作结果的名词尾构成，义为「利用不足」"}],"senses":[{"no":"01","title":"Make practical use of materials","titleCN":"实际利用材料或资源","definition":"to put available materials or resources to a useful purpose instead of wasting them","definitionCN":"把可得的材料或资源用于有用的目的，而不是浪费掉","example":"The farm utilizes every hectare of its land.","exampleCN":"这个农场利用了每一公顷土地。","why":"The root means useful, so the word begins with the judgement that a thing can be turned to use.","whyCN":"词根意为「有用的」，所以这个词一开始就带着判断：某物可以被转为用途。"},{"no":"02","title":"Use a tool or a method","titleCN":"使用工具或方法","definition":"to employ an instrument, technique or procedure for a task","definitionCN":"为完成一项任务而使用工具、技术或程序","example":"They utilize a simple press to shape the clay.","exampleCN":"他们用一台简单的压机来塑形黏土。","why":"Here the word is close to use, but its formality suggests a deliberate choice of the right instrument.","whyCN":"这里这个词接近「使用」，但其正式程度暗示着对合适工具的刻意选择。"},{"no":"03","title":"Draw out hidden potential","titleCN":"发挥潜在能力","definition":"to help a capacity or talent become active and productive","definitionCN":"帮助某种能力或才干变为活跃、有产出","example":"The program helps students utilize their full potential.","exampleCN":"该项目帮助学生发挥全部潜力。","why":"Potential is a resource stored in a person, and the word treats it like any other material to be worked.","whyCN":"潜力是储存在一个人身上的资源，这个词把它当作任何其他待加工的材料。"},{"no":"04","title":"Use time or space well","titleCN":"善用时间或空间","definition":"to fill available hours or room with productive activity or arrangement","definitionCN":"用有产出的活动或安排填满可用的时间或空间","example":"Good planners utilize the hours before noon.","exampleCN":"善于规划的人会利用中午之前的几个小时。","why":"Empty time and empty floor space are resources too, and the word asks whether they were put to work.","whyCN":"空余时间与空地也是资源，这个词追问它们是否被派上了用场。"},{"no":"05","title":"Develop a natural resource","titleCN":"开发利用自然资源","definition":"to bring water, land, heat or minerals into productive service","definitionCN":"使水、土地、热能或矿产进入生产性用途","example":"The region utilizes geothermal heat for its greenhouses.","exampleCN":"该地区利用地热为温室供暖。","why":"Nature offers a standing reserve, and the word marks the moment it is converted into service.","whyCN":"自然提供一份常备的储备，而这个词标出它被转成服务的时刻。"},{"no":"06","title":"Apply a theory or technology","titleCN":"运用理论或技术","definition":"to put a body of knowledge or a technology into practical operation","definitionCN":"把一套知识或一项技术投入实际运行","example":"Engineers utilize a new model to predict floods.","exampleCN":"工程师运用一个新模型来预测洪水。","why":"A model that stays on paper is not utilized; the word insists on the step into practice.","whyCN":"停留在纸上的模型并未被利用，这个词坚持要那一步进入实践。"},{"no":"07","title":"Take advantage of an opportunity","titleCN":"利用机会或优势","definition":"to make prompt productive use of a chance or a favourable condition","definitionCN":"及时、有产出地使用一次机会或有利条件","example":"She utilized the break to finish her notes.","exampleCN":"她利用休息时间写完笔记。","why":"An opportunity is useful only for a short window, and the word names the act of catching it.","whyCN":"机会只在很短的窗口里有用，而这个词命名的正是抓住它这个动作。"},{"no":"08","title":"Work with data or records","titleCN":"利用数据或档案","definition":"to analyse or draw conclusions from information that already exists","definitionCN":"分析已有的信息并从中得出结论","example":"Researchers utilize the archive to trace migration.","exampleCN":"研究者利用档案追溯人口迁移。","why":"Data are raw material, and the word is the formal verb for turning them into findings.","whyCN":"数据是原料，而这个词是把原料变成研究结论的正式动词。"},{"no":"09","title":"Treat people as instruments","titleCN":"把人当作工具使用","definition":"to use other people mainly as means to one's own end, with a cold or critical tone","definitionCN":"主要把他人当作达成自己目的的手段，带冷淡或批评的语气","example":"The manager was accused of utilizing his staff as tools.","exampleCN":"那名经理被指责把员工当作工具使用。","why":"The word's usefulness logic can be turned on people, and when it is, it sounds like a moral accusation.","whyCN":"这个词的「有用」逻辑也可以用在人身上，一旦这样用，听起来就像道德指控。"}],"etymology":{"intro":{"en":"Utilize came into English through French utiliser from Italian utilizzare, both resting on Latin utilis, useful, from uti, to use.","cn":"这个词经法语 utiliser 进入英语，而法语形式出自意大利语 utilizzare，两者都建立在拉丁语 utilis「有用的」之上，其底层是 uti「使用」。"},"items":[{"era":"LATIN UTI","en":"Uti meant to use or enjoy, and it is the oldest verb in the family, older than any of its English children.","cn":"uti 意为使用或享用，是这个词族里最古老的动词，比它任何英语后代都古老。"},{"era":"LATIN UTILIS","en":"The adjective meant useful or serviceable, and it gave English utility and utilitarian.","cn":"这个形容词意为有用的、可用的，它给英语带来「效用」与「功利」等词。"},{"era":"ITALIAN UTILIZZARE","en":"Italian formed a verb meaning to turn to use, with a productive verb ending.","cn":"意大利语用一个能产的动词词尾造出「转为使用」的动词。"},{"era":"FRENCH UTILISER","en":"French carried the verb into administrative and technical writing.","cn":"法语把这个动词带进行政与技术写作。"},{"era":"ENGLISH UTILIZE","en":"English borrowed it in the nineteenth century, when it sounded more formal than use; the exact first date is uncertain.","cn":"英语在十九世纪借入，当时它听起来比「使用」更正式；确切首见年代不确定。"},{"era":"MODERN TECHNICAL USE","en":"Industry, computing and environmental policy made it a standard verb for turning a resource into service.","cn":"工业、计算机与环境政策把它变成把资源转为服务的标准动词。"}]},"similar":{"note":{"en":"The first group looks or sounds like utilize; the second group names neighbouring ways of using something.","cn":"第一组在形音上与 utilize 相近；第二组是与「使用、利用」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"utilization","ipa":"/ˌjuːtɪlaɪˈzeɪʃn/","tag":"same root","definition":"The act of putting something to practical use.","definitionCN":"指把某物投入实际用途的行为。"},{"word":"utilizer","ipa":"/ˈjuːtɪlaɪzə/","tag":"same root","definition":"One who puts something to use.","definitionCN":"指把某物加以利用的人。"},{"word":"utilizable","ipa":"/ˌjuːtɪˈlaɪzəbl/","tag":"same root","definition":"Capable of being put to practical use.","definitionCN":"指可以被投入实际使用的。"},{"word":"utility","ipa":"/juːˈtɪləti/","tag":"same root","definition":"Usefulness, or a service such as power or water.","definitionCN":"指有用性，或指电力、供水之类的公共服务。"},{"word":"utile","ipa":"/ˈjuːtɪl/","tag":"same root","definition":"Useful; a rare adjective that keeps the Latin form visible.","definitionCN":"指有用的；一个罕见的形容词，保留了拉丁语形态。"}]},{"heading":"NEAR MEANING","entries":[{"word":"use","ipa":"/juːz/","tag":"near meaning","definition":"To employ something for a purpose; the plain word, with no claim to formality or efficiency.","definitionCN":"指为某目的使用某物；最朴素的词，不声称正式或高效。"},{"word":"employ","ipa":"/ɪmˈplɔɪ/","tag":"near meaning","definition":"To use a method or tool, and to give work to a person; formal but neutral.","definitionCN":"指使用方法或工具，也指雇用某人；正式但中性。"},{"word":"apply","ipa":"/əˈplaɪ/","tag":"near meaning","definition":"To put a method, rule or substance to a particular case; it stresses fit between tool and target.","definitionCN":"指把方法、规则或物质用于特定对象；强调工具与目标的匹配。"},{"word":"exploit","ipa":"/ɪkˈsplɔɪt/","tag":"near meaning","definition":"To use a resource, and often to use a person unfairly for one's own gain.","definitionCN":"指利用资源，也常指为自己获利而不公平地利用他人。"},{"word":"harness","ipa":"/ˈhɑːnɪs/","tag":"near meaning","definition":"To capture and put to work a natural force such as wind or water.","definitionCN":"指捕获风力、水力等自然力量并使其做功。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the useful root, the formal register and the image of turning waste into equipment.","cn":"正常联想利用「有用」的词根、正式的语体，以及把废料变成器具的意象。"},"normal":[{"en":"The root means useful, so to utilize is to make a thing prove its usefulness.","cn":"词根意为有用，所以「利用」就是让某物证明自己的用处。"},{"en":"Old crates become shelves: the material does not change, only its service does.","cn":"旧木箱变成货架：材料没有变，变的只是它提供的服务。"},{"en":"Utilize is the formal cousin of use; reports and manuals prefer it, kitchens do not.","cn":"这个词是「使用」的正式表亲：报告与手册偏爱它，厨房里不这么说。"},{"en":"Potential, time and space can all be utilized because all three can be left idle.","cn":"潜力、时间与空间都能被利用，因为三者都可能被闲置。"},{"en":"When the object is a person, the word turns cold and sounds like an accusation.","cn":"当对象是人时，这个词就变冷了，听起来像一项指控。"}],"abstract":[{"en":"Utilization measures the distance between what a thing is and what it can be made to do.","cn":"利用衡量的是「某物是什么」与「它能被用来做什么」之间的距离。"},{"en":"A resource is not a thing but a relation between a material and a purpose.","cn":"资源不是一件东西，而是材料与目的之间的一种关系。"},{"en":"The word quietly asks who gets the benefit of the use.","cn":"这个词在悄悄追问：这份利用的好处归谁。"}]},"examples":[{"en":"The factory utilizes scrap metal in its furnaces.","cn":"这家工厂在炉中使用废金属。"},{"en":"We should utilize the existing equipment before buying more.","cn":"在购置更多设备之前，我们应先利用现有设备。"},{"en":"The new system utilizes real-time data from the port.","cn":"新系统利用港口的实时数据。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「优特莱兹」——「优」秀的「特」色被「莱」回使用，兹证明有用：利用","word":"utilize"},"root":"拉丁语 uti「使用」→ utilis「有用的」→ 意大利语 utilizzare「加以使用」→ 法语 utiliser → 英语 utilize「利用」；与 use 同根，但借道法语与意大利语，语体更正式，强调把资源转为实际效用。","sensesIntro":{"en":"Nine senses turn usefulness into action: materials, tools, potential, time and space, natural resources, theory, opportunity, data, and finally people treated as means.","cn":"九个义项把「有用」变成行动：材料、工具、潜力、时间与空间、自然资源、理论、机会、数据，最后是把人当作手段。"},"semanticMap":{"core":{"en":"CORE IMAGE: old crates taken apart, planed flat and nailed into a row of shelves.","cn":"核心意象：旧木箱被拆开、刨平，重新钉成一排货架。"},"chain":["FIND A USE","PUT TO WORK","DRAW OUT VALUE","WASTE NOTHING","OPEN A RESOURCE","TREAT AS A MEANS"],"branches":[{"senses":"01 · 08","en":"THE MATERIAL AND DATA BRANCH: land is farmed and an archive is searched.","cn":"材料与数据分支：土地被耕作，档案被检索。"},{"senses":"02 · 06","en":"THE TOOL AND METHOD BRANCH: a press shapes clay and a model predicts floods.","cn":"工具与方法分支：压机塑形黏土，模型预测洪水。"},{"senses":"03 · 04","en":"THE POTENTIAL AND TIME BRANCH: students grow into their capacity and planners fill the morning.","cn":"潜力与时间分支：学生长成自己的能力，规划者填满上午。"},{"senses":"05 · 07","en":"THE RESOURCE AND OPPORTUNITY BRANCH: geothermal heat warms greenhouses and a break is caught.","cn":"资源与机会分支：地热温暖温室，休息时间被抓住。"},{"senses":"09","en":"THE PEOPLE BRANCH: staff are treated as instruments, and the word turns critical.","cn":"人的分支：员工被当作工具，这个词转为批评语气。"}]},"affixes":{"intro":{"en":"Utilize is a Latin-derived verb that travelled through Italian and French before English added its own spelling.","cn":"这是一个源自拉丁语的动词，先经意大利语与法语，之后英语才加上自己的拼写。"},"latinIntro":{"en":"Latin supplies the verb uti, the adjective utilis and the noun utilitas; the verb ending came through the Romance languages.","cn":"拉丁语提供动词 uti、形容词 utilis 与名词 utilitas；动词词尾则经罗曼语族传来。"},"items":[{"word":"-ize","structure":"verb-forming suffix through French and Latin","meaning":"to make or turn into","meaningCN":"使成为；使转为","example":"It turns the idea of usefulness into an action.","exampleCN":"它把「有用」这个观念变成动作。"},{"word":"uti","structure":"Latin verb, deponent","meaning":"to use, enjoy","meaningCN":"使用；享用","example":"The verb is the oldest element in the family.","exampleCN":"这个动词是词族里最古老的元素。"},{"word":"utilis","structure":"Latin adjective from uti","meaning":"useful","meaningCN":"有用的","example":"The adjective supplies the judgement behind the verb.","exampleCN":"这个形容词提供动词背后的判断。"},{"word":"-ation","structure":"Latin noun ending through French","meaning":"action or result","meaningCN":"动作或结果","example":"It forms the noun for the act of putting to use.","exampleCN":"它构成表示「投入使用」这一行为的名词。"},{"word":"-er","structure":"English agent suffix","meaning":"one that does","meaningCN":"做某事者","example":"It names the one who puts something to use.","exampleCN":"它命名把某物投入使用的人。"},{"word":"-able","structure":"Latin possibility ending through French","meaning":"capable of being","meaningCN":"能被……的","example":"It marks what can be put to use.","exampleCN":"它标出可以被投入使用的东西。"},{"word":"-ity","structure":"Latin noun suffix -itas, through French -ité","meaning":"quality or state","meaningCN":"性质；状态","example":"It forms utility, the quality of being useful.","exampleCN":"它构成 utility，即「有用」这一性质。"},{"word":"-ization","structure":"English noun suffix, -ize + -ation","meaning":"action or result of putting to use","meaningCN":"投入使用的行为或结果","example":"It forms utilization, the act of putting to use.","exampleCN":"它构成 utilization，即「投入使用」这一行为。"}],"latinEntries":[{"word":"uti","structure":"utor, usus sum (verb, deponent)","meaning":"to use, enjoy","meaningCN":"使用；享用"},{"word":"utilis","structure":"adjective from uti","meaning":"useful","meaningCN":"有用的"},{"word":"utilitas","structure":"noun from utilis","meaning":"usefulness, utility","meaningCN":"有用性；效用"}],"derivatives":[{"word":"utilization","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「利用；使用」"},{"word":"utilizer","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「利用者」"},{"word":"utilizable","pos":"adj.","zh":"由该动词加表示可能性的形容词尾构成，义为「可利用的」"},{"word":"underutilize","pos":"v.","zh":"由表示「不足」的前缀加该动词构成，义为「未充分利用」"},{"word":"underutilization","pos":"n.","zh":"由前一词加表示动作结果的名词尾构成，义为「利用不足」"}]}},{"word":"validate","ipa_uk":"/ˈvælɪdeɪt/","ipa_us":"/ˈvælɪdeɪt/","definition_zh":"验证；确认……有效；使生效；批准认可","definition_en":"to prove or confirm that something is valid, true or legally effective","core_image":"窗口前，一张表格递进来，工作人员在最后一栏盖上圆形印章，纸上的内容立刻有了效力","scene":"窗口前，一张表格递进来，工作人员在最后一栏盖上圆形印章，纸上的内容立刻有了效力。Engineers validate every sensor against a known standard.","sceneCN":"这里指检验并确认某物符合标准（第 1 个义项：验证数据或器件有效）；句意为工程师用已知标准校验每一个传感器。","pos":[{"tag":"v.","zh":"验证；确认有效；使生效；批准"}],"collocations":[{"phrase":"validate a claim","zh":"证实一项主张"},{"phrase":"validate data","zh":"验证数据"},{"phrase":"validate a ticket","zh":"验票"},{"phrase":"validate a contract","zh":"使合同生效"},{"phrase":"validate a model","zh":"验证模型"},{"phrase":"validate someone's feelings","zh":"认可某人的感受"},{"phrase":"validate a qualification","zh":"确认学历资格"}],"forms":[{"label":"原形","form":"validate"},{"label":"三单","form":"validates"},{"label":"过去式","form":"validated"},{"label":"过去分词","form":"validated"},{"label":"现在分词","form":"validating"},{"label":"名词（验证）","form":"validation"}],"derivatives":[{"word":"validation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「验证；生效；认可」"},{"word":"validator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「验证者；校验器」"},{"word":"validated","pos":"adj.","zh":"由该动词的过去分词转成的形容词，义为「已验证的；已生效的」"},{"word":"validating","pos":"adj.","zh":"由该动词的现在分词转成的形容词，义为「起验证作用的」"}],"senses":[{"no":"01","title":"Check data against a standard","titleCN":"按标准验证数据","definition":"to test measurements or records against a known rule to show that they are sound","definitionCN":"用已知规则检验测量值或记录，以证明它们可靠","example":"The lab validates each batch of samples before release.","exampleCN":"实验室在放行之前验证每一批样品。","why":"The root means strong, and the verb asks whether a result can stand up to a standard.","whyCN":"词根意为「强、有力」，而这个动词问的是：一项结果能否在标准面前站得住。"},{"no":"02","title":"Confirm a claim or hypothesis","titleCN":"证实主张或假设","definition":"to give evidence that a statement or theory is correct","definitionCN":"提供证据说明某项陈述或理论是正确的","example":"New evidence validated his earlier claim.","exampleCN":"新证据证实了他先前的说法。","why":"A claim is valid when it holds, and the verb names the act of showing that it holds.","whyCN":"主张站得住就叫有效，而这个动词命名的正是证明它站得住的动作。"},{"no":"03","title":"Give legal force to a document","titleCN":"使文件具有法律效力","definition":"of a court or official, to declare a will, contract or act legally effective","definitionCN":"指法院或官员宣布遗嘱、合同或行为在法律上有效","example":"The judge validated the will after the hearing.","exampleCN":"听证之后，法官确认了遗嘱的效力。","why":"This is the sense where the word does not merely check but confers force; validation changes the legal status.","whyCN":"在这个义项里，词不只是检查，而是授予效力；「确认有效」改变了法律地位。"},{"no":"04","title":"Approve a plan or decision","titleCN":"批准计划或决定","definition":"of a body with authority, to accept a proposal and allow it to proceed","definitionCN":"指有权的机构接受提案并允许其推进","example":"The board validated the plan at its monthly meeting.","exampleCN":"董事会在月度会议上批准了该计划。","why":"Approval is a stamp that makes a paper count, which is the image the word carries in administration.","whyCN":"批准是一枚让纸张算数的印章，这正是这个词在行政语境里携带的意象。"},{"no":"05","title":"Prove a ticket or identity","titleCN":"验票或确认身份","definition":"to check that a ticket, pass or document belongs to the person using it","definitionCN":"检查票证或文件是否属于使用它的人","example":"The gate validates each ticket before the concert.","exampleCN":"音乐会在入场前逐一验票。","why":"A ticket is valid only for one holder and one time, and the verb is the act of confirming both.","whyCN":"一张票只对一位持有者和一个时间有效，而这个动词就是确认这两件事的动作。"},{"no":"06","title":"Check that input is acceptable","titleCN":"校验输入是否合格","definition":"in computing, to test data entered by a user against the rules a system requires","definitionCN":"计算机中指按系统规则检验用户输入的数据","example":"The app validates the form before sending it.","exampleCN":"应用在发送之前会校验表单。","why":"Software borrowed the word because a form either meets the rule or does not, exactly like a document before a clerk.","whyCN":"软件借用这个词，因为表单要么符合规则、要么不符合，正如文件到了办事员面前。"},{"no":"07","title":"Test a model or method","titleCN":"验证模型或方法","definition":"to show that a model, instrument or procedure produces trustworthy results","definitionCN":"证明模型、仪器或程序能产生可信结果","example":"The team validated the model with a second data set.","exampleCN":"团队用第二套数据验证了该模型。","why":"A model is valid when it works beyond the cases that built it, and validation is the test of that reach.","whyCN":"模型能在建造它的案例之外也起作用才算有效，而验证就是对这份覆盖力的测试。"},{"no":"08","title":"Recognize someone's feelings","titleCN":"认可某人的感受","definition":"in psychology, to affirm that another person's emotional experience is real and understandable","definitionCN":"心理学中指确认他人的情感体验是真实、可理解的","example":"A good listener validates what the speaker feels.","exampleCN":"好的倾听者会认可说话者的感受。","why":"Here validity is granted to an inner state rather than to a document, and the word turns warm.","whyCN":"这里被授予效力的是内心状态而不是文件，这个词也随之变暖。"},{"no":"09","title":"Confirm the standing of a qualification","titleCN":"确认学历或资格的效力","definition":"of an authority, to accept a degree, licence or certificate as officially usable","definitionCN":"指权威机构承认学位、执照或证书可正式使用","example":"The registry validates foreign qualifications case by case.","exampleCN":"登记机构逐一确认海外学历的效力。","why":"A qualification is only useful where it is recognized, and the verb marks the boundary between holding and being able to use.","whyCN":"资格只有在被承认的地方才有用，而这个动词标出「持有」与「能够使用」之间的界线。"}],"etymology":{"intro":{"en":"Validate comes from Medieval Latin validare, to make valid, from validus, strong, from valere, to be strong or be worth.","cn":"这个词来自中世纪拉丁语 validare「使有效」，而 validare 出自 validus「强壮的」，其底层是 valere「有力、有价值」。"},"items":[{"era":"LATIN VALERE","en":"Valere meant to be strong, to be worth or to have influence, and it also gave English value and valour.","cn":"valere 意为有力、有价值或有影响，它还给英语带来「价值」与「英勇」等词。"},{"era":"LATIN VALIDUS","en":"The adjective meant strong, sturdy or effective, and it became the everyday word for a sound argument or a sound body.","cn":"这个形容词意为强壮的、坚实的、有效的，后来成为形容论证可靠或身体强健的日常词。"},{"era":"MEDIEVAL LATIN VALIDARE","en":"Legal Latin formed a verb meaning to make valid or to give force to a document.","cn":"法律拉丁语造出一个动词，意为使有效、授予文件效力。"},{"era":"FRENCH VALIDER","en":"French carried the legal verb into administrative use before English borrowed it.","cn":"法语把这个法律动词带进行政用途，之后英语才借入。"},{"era":"ENGLISH VALIDATE","en":"English took the verb in the seventeenth century; the exact first date is uncertain, and the legal sense came first.","cn":"英语在十七世纪取用这个动词；确切首见年代不确定，法律义最先出现。"},{"era":"MODERN TECHNICAL USE","en":"Science and computing made it the standard verb for testing data, models and input against a rule.","cn":"科学与计算机使它成为按规则检验数据、模型与输入的标准动词。"}]},"similar":{"note":{"en":"The first group looks or sounds like validate; the second group names neighbouring ways of confirming something.","cn":"第一组在形音上与 validate 相近；第二组是与「确认、证实」意思相邻的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"validation","ipa":"/ˌvælɪˈdeɪʃn/","tag":"same root","definition":"The act of proving something valid or giving it force.","definitionCN":"指证明某物有效或授予其效力的行为。"},{"word":"validator","ipa":"/ˈvælɪdeɪtə/","tag":"same root","definition":"A person or program that checks validity.","definitionCN":"指检查有效性的个人或程序。"},{"word":"valid","ipa":"/ˈvælɪd/","tag":"same root","definition":"Sound, legally effective or based on good reasoning.","definitionCN":"指可靠的、法律上有效的，或基于良好推理的。"},{"word":"validity","ipa":"/vəˈlɪdəti/","tag":"same root","definition":"The quality of being sound or legally effective.","definitionCN":"指可靠或法律上有效的性质。"},{"word":"invalidate","ipa":"/ɪnˈvælɪdeɪt/","tag":"same family","definition":"To make something void; it is built on the negative of the adjective, not on this verb.","definitionCN":"指使某物失效；它建立在形容词的否定形式之上，而不是本动词之上。"}]},{"heading":"NEAR MEANING","entries":[{"word":"verify","ipa":"/ˈverɪfaɪ/","tag":"near meaning","definition":"To check whether a fact or figure is true; it asks about accuracy rather than effect.","definitionCN":"指检查事实或数字是否真实；它追问准确与否，而非效力。"},{"word":"confirm","ipa":"/kənˈfɜːm/","tag":"near meaning","definition":"To show that something already believed is true; it adds certainty rather than force.","definitionCN":"指表明原本已被相信的事是真的；增加的是确定性，而非效力。"},{"word":"certify","ipa":"/ˈsɜːtɪfaɪ/","tag":"near meaning","definition":"To state officially, often in writing, that something meets a standard.","definitionCN":"指以官方方式、常以书面形式声明某物符合标准。"},{"word":"ratify","ipa":"/ˈrætɪfaɪ/","tag":"near meaning","definition":"To give formal approval to a treaty or agreement, making it binding.","definitionCN":"指对条约或协议给予正式批准，使其具有约束力。"},{"word":"substantiate","ipa":"/səbˈstænʃieɪt/","tag":"near meaning","definition":"To support a claim with evidence; it stresses the proof offered.","definitionCN":"指用证据支撑主张；强调所提供的证明。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the strong root, the stamp image and the contrast with mere checking.","cn":"正常联想利用「有力」的词根、盖章的意象，以及它与单纯检查的对比。"},"normal":[{"en":"The root means strong, so something valid can stand; to validate is to show that it stands.","cn":"词根意为有力，所以有效的东西站得住；而「验证」就是证明它站得住。"},{"en":"A round stamp on the last column is the picture: the paper does not change, its force does.","cn":"最后一栏上的圆形印章就是那幅图：纸没有变，变的是它的效力。"},{"en":"A ticket is validated at the gate, a model at a second data set, a feeling by a good listener.","cn":"票在闸口被验证，模型在第二套数据上被验证，感受由好的倾听者来确认。"},{"en":"Verify asks whether it is true; validate asks whether it counts.","cn":"「核实」问的是真假，「确认有效」问的是算不算数。"},{"en":"The word can be cold in a laboratory and warm in a therapist's room, because validity applies to numbers and to feelings alike.","cn":"这个词在实验室里是冷的，在治疗室里是暖的，因为「有效」既能用于数字，也能用于感受。"}],"abstract":[{"en":"Validation is the moment a private fact becomes a public one.","cn":"验证，是一个私下的事实变成公开事实的那一刻。"},{"en":"To validate is to answer the question of whether something may be relied on.","cn":"验证就是回答「某物是否可以被依靠」这个问题。"},{"en":"The word grants standing, and standing is a social gift as much as a technical result.","cn":"这个词授予的是「站得住」的地位，而地位既是技术结果，也是社会赠予。"}]},"examples":[{"en":"The survey was validated by a second team.","cn":"这项调查由第二个团队作了验证。"},{"en":"The court validated the agreement in March.","cn":"法院在三月确认了该协议的效力。"},{"en":"Please validate your parking ticket at the desk.","cn":"请在服务台确认停车票。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「瓦利得特」——「瓦」片盖印，「利」上生效，「得」到批准才「特」别算数：验证、使生效","word":"validate"},"root":"拉丁语 valere「有力、有价值」→ validus「强壮的、有效的」→ 中世纪拉丁语 validare「使有效」→ 法语 valider → 英语 validate「验证；使生效；批准」；核心是「让某物在标准或权威面前站得住」。","sensesIntro":{"en":"Nine senses all confer or test standing: data, a claim, a will, a plan, a ticket, an input, a model, a feeling and a qualification.","cn":"九个义项都在授予或检验「站得住」的资格：数据、主张、遗嘱、计划、票证、输入、模型、感受与学历。"},"semanticMap":{"core":{"en":"CORE IMAGE: a round stamp coming down on the last column of a form.","cn":"核心意象：一枚圆形印章落在表格最后一栏。"},"chain":["CHECK THE STANDARD","CONFIRM THE CLAIM","GIVE FORCE","GRANT APPROVAL","PROVE IDENTITY","RECOGNIZE FEELING"],"branches":[{"senses":"01 · 07","en":"THE DATA AND MODEL BRANCH: samples are tested and a model is tried on fresh data.","cn":"数据与模型分支：样品被检验，模型在新数据上被试用。"},{"senses":"02 · 08","en":"THE CLAIM AND FEELING BRANCH: evidence supports a statement, and a listener supports an inner state.","cn":"主张与感受分支：证据支撑陈述，倾听者支撑内心状态。"},{"senses":"03 · 09","en":"THE FORCE BRANCH: a will is given legal effect and a foreign degree is given official standing.","cn":"效力分支：遗嘱被赋予法律效力，海外学位被赋予官方地位。"},{"senses":"04","en":"THE APPROVAL BRANCH: a board lets a plan proceed.","cn":"批准分支：董事会允许计划推进。"},{"senses":"05 · 06","en":"THE IDENTITY AND INPUT BRANCH: a gate checks a ticket and an app checks a form.","cn":"身份与输入分支：闸口检查票证，应用检查表单。"}]},"affixes":{"intro":{"en":"Validate is a Latin verb of making strong, and English built a full noun and agent family on it.","cn":"这是一个表示「使强、使有效」的拉丁动词，英语在它之上建起完整的名词与施动者家族。"},"latinIntro":{"en":"Latin supplies valere, validus and the medieval verb validare; English adds its own endings for noun, agent and adjective.","cn":"拉丁语提供 valere、validus 与中世纪动词 validare；英语加上自己的名词、施动者与形容词词尾。"},"items":[{"word":"-ate","structure":"Latin verb ending through French","meaning":"to make or cause","meaningCN":"使……；使成为","example":"It turns the adjective of strength into a verb of making valid.","exampleCN":"它把表示「强」的形容词变成「使有效」的动词。"},{"word":"valere","structure":"Latin verb, second conjugation","meaning":"to be strong, be worth","meaningCN":"有力；有价值","example":"The verb is the source of the whole family.","exampleCN":"这个动词是整族词的源头。"},{"word":"validus","structure":"Latin adjective from valere","meaning":"strong, effective","meaningCN":"强壮的；有效的","example":"The adjective supplies the idea of standing firm.","exampleCN":"这个形容词提供「站得稳」的意思。"},{"word":"-ation","structure":"Latin noun ending through French","meaning":"action or result","meaningCN":"动作或结果","example":"It forms the noun for the act of confirming validity.","exampleCN":"它构成表示「确认有效」这一行为的名词。"},{"word":"-or","structure":"Latin agent ending","meaning":"one that does","meaningCN":"做某事者","example":"It names the person or program that checks validity.","exampleCN":"它命名检查有效性的个人或程序。"},{"word":"-ity","structure":"Latin noun ending through French","meaning":"quality of being","meaningCN":"……的性质","example":"It forms the noun for the quality of being valid.","exampleCN":"它构成表示「有效」性质的名词。"},{"word":"in-","structure":"Latin negative prefix","meaning":"not","meaningCN":"不；非","example":"It reverses the adjective to form the opposite verb.","exampleCN":"它翻转形容词，构成反义动词。"},{"word":"valid","structure":"English adjective from French valide, from Latin validus","meaning":"sound, legally effective","meaningCN":"可靠的；法律上有效的","example":"The adjective is the base the verb is built on.","exampleCN":"这个形容词是该动词赖以构成的词基。"}],"latinEntries":[{"word":"valere","structure":"valeo, valui, valitum (verb, second conjugation)","meaning":"to be strong, be worth","meaningCN":"有力；有价值"},{"word":"validus","structure":"adjective from valere","meaning":"strong, effective","meaningCN":"强壮的；有效的"},{"word":"validare","structure":"valido, validavi, validatum (verb, first conjugation, medieval Latin)","meaning":"to make valid","meaningCN":"使有效"}],"derivatives":[{"word":"validation","pos":"n.","zh":"由该动词加表示动作结果的名词尾构成，义为「验证；生效；认可」"},{"word":"validator","pos":"n.","zh":"由该动词加表示施动者的名词尾构成，义为「验证者；校验器」"},{"word":"validated","pos":"adj.","zh":"由该动词的过去分词转成的形容词，义为「已验证的；已生效的」"},{"word":"validating","pos":"adj.","zh":"由该动词的现在分词转成的形容词，义为「起验证作用的」"}]}}]);
